function RiderSpotMap({ className = '' }) {
  return <svg viewBox="0 0 124 104" className={className} fill="none" strokeLinecap="round" strokeLinejoin="round" aria-hidden><defs><clipPath id="rmapclip"><rect x="11" y="15" width="102" height="78" rx="11"/></clipPath></defs>
  <rect x="10" y="14" width="104" height="80" rx="12" fill="#E3F4EF" stroke="#0B2B26" strokeWidth="2.5"/>
  <g clipPath="url(#rmapclip)"><path d="M10 46 C 40 40, 60 70, 114 58" stroke="#fff" strokeWidth="8"/>
  <path d="M46 14 C 50 40, 70 60, 66 94" stroke="#fff" strokeWidth="8"/></g>
  <path d="M28 76 C 44 70, 52 50, 70 46 S 92 30, 96 30" stroke="#0B2B26" strokeWidth="2.5" strokeDasharray="5 6"/>
  <circle cx="28" cy="76" r="6" fill="#1FD9C4" stroke="#0B2B26" strokeWidth="2.5"/>
  <path d="M96 10 C 106 10, 110 20, 106 26 L 96 42 L 86 26 C 82 20, 86 10, 96 10 Z" fill="#FFB020" stroke="#0B2B26" strokeWidth="2.5"/>
  <circle cx="96" cy="21" r="4" fill="#fff"/></svg>;
}
function RiderSpotPay({ className = '' }) {
  return <svg viewBox="0 0 124 110" className={className} fill="none" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
  <rect x="22" y="8" width="56" height="94" rx="12" fill="#fff" stroke="#0B2B26" strokeWidth="2.5"/>
  <path d="M42 16 h16" stroke="#0B2B26" strokeWidth="2.5"/>
  <rect x="30" y="30" width="40" height="30" rx="6" fill="#E3F4EF"/>
  <text x="50" y="51" textAnchor="middle" fontFamily="Inter, Arial" fontWeight="800" fontSize="16" fill="#0B3B33">₦</text>
  <path d="M32 70 h36 M32 80 h24" stroke="#0B2B26" strokeWidth="2.5" opacity="0.35"/>
  <circle cx="90" cy="36" r="16" fill="#FFB020" stroke="#0B2B26" strokeWidth="2.5"/>
  <text x="90" y="42" textAnchor="middle" fontFamily="Inter, Arial" fontWeight="800" fontSize="16" fill="#0B2B26">₦</text>
  <circle cx="98" cy="70" r="12" fill="#FFD27A" stroke="#0B2B26" strokeWidth="2.5"/>
  <path d="M6 44 l8 4 M4 60 h9" stroke="#0B2B26" strokeWidth="2.5"/></svg>;
}
function RiderSpotSafe({ className = '' }) {
  return <svg viewBox="0 0 124 100" className={className} fill="none" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
  <rect x="6" y="40" width="70" height="48" rx="8" fill="#fff" stroke="#0B2B26" strokeWidth="2.5"/>
  <circle cx="26" cy="62" r="9" fill="#8D5A3B" stroke="#0B2B26" strokeWidth="2"/>
  <path d="M42 56 h24 M42 66 h16" stroke="#0B2B26" strokeWidth="2.5" opacity="0.5"/>
  <path d="M84 10 L 116 22 V 50 C 116 72, 100 86, 84 94 C 68 86, 52 72, 52 50 V 22 Z" fill="#1FD9C4" stroke="#0B2B26" strokeWidth="2.5"/>
  <path d="M70 52 l10 10 l18 -20" stroke="#0B2B26" strokeWidth="4"/></svg>;
}

// The rider's pass: fills in as they apply, and becomes their verified card once approved
function RiderPass({ r, photo, compact = false }) {
  const v = RIDER_VEHICLES.find(([k]) => k === r?.vehicle);
  const VIcon = v ? v[3] : Bike;
  const status = r?.status || 'draft';
  const stamp = status === 'approved' ? ['Verified rider', C.sage, BadgeCheck] : status === 'submitted' ? ['Being checked', C.copper, Clock] : status === 'needs_fix' ? ['Needs a fix', C.rust, Pencil]
    : status === 'suspended' ? ['Paused', C.rust, Lock] : status === 'rejected' ? ['Not approved', C.rust, Ban] : ['Application', C.inkDim, Pencil];
  const StampIcon = stamp[2];
  return (
    <div className={`relative overflow-hidden rounded-[24px] ${compact ? 'p-4' : 'p-5'}`} style={{ background: 'linear-gradient(145deg, #143D35 0%, #0E2B26 55%, #0B231F 100%)', border: '1px solid rgba(255,255,255,0.09)', boxShadow: '0 30px 60px -30px rgba(0,0,0,0.8), inset 0 1px 0 rgba(255,255,255,0.06)' }}>
      <span aria-hidden className="absolute -right-16 -top-16 w-56 h-56 rounded-full" style={{ background: 'radial-gradient(circle, rgba(255,176,32,0.22), transparent 65%)' }} />
      <span aria-hidden className="absolute -left-10 -bottom-20 w-56 h-56 rounded-full" style={{ background: 'radial-gradient(circle, rgba(31,217,196,0.16), transparent 65%)' }} />
      <svg aria-hidden className="absolute right-0 bottom-0 opacity-[0.07]" width="220" height="120" viewBox="0 0 220 120" fill="none"><path d="M0 110 C 60 110, 70 40, 130 40 S 200 10, 220 10" stroke="#fff" strokeWidth="2" strokeDasharray="6 8" /><circle cx="130" cy="40" r="5" fill="#fff" /></svg>
      <div className="relative flex items-center justify-between">
        <div className="flex items-center gap-2"><XorlaMark size={20} /><span className="text-[11px] font-bold tracking-[0.18em]" style={{ color: C.inkDim }}>XORLA RIDER</span></div>
        <span className="flex items-center gap-1 px-2 py-1 rounded-full text-[10.5px] font-bold" style={{ background: 'rgba(0,0,0,0.3)', color: stamp[1], border: `1px solid ${stamp[1]}40` }}><StampIcon size={11} />{stamp[0]}</span>
      </div>
      <div className={`relative flex items-center gap-4 ${compact ? 'mt-4' : 'mt-5'}`}>
        <div className={`${compact ? 'w-16 h-16' : 'w-[76px] h-[76px]'} rounded-2xl overflow-hidden shrink-0 flex items-center justify-center`} style={{ background: 'rgba(255,255,255,0.06)', border: `2px solid ${status === 'approved' ? C.sage : 'rgba(255,255,255,0.12)'}` }}>
          {photo ? <img src={photo} alt="" className="w-full h-full object-cover" /> : <span className="text-[22px] font-bold" style={{ color: C.inkDim }}>{riderInitials(r?.full_name)}</span>}
        </div>
        <div className="min-w-0">
          <div className={`${compact ? 'text-[17px]' : 'text-[20px]'} font-bold leading-tight truncate`} style={{ letterSpacing: '-0.01em', color: r?.full_name ? C.ink : C.inkFaint }}>{r?.full_name || 'Your name'}</div>
          <div className="flex items-center gap-1.5 mt-1 text-[12.5px]" style={{ color: C.inkDim }}><VIcon size={14} style={{ color: C.copper }} />{v ? v[1] : 'Your ride'}{r?.plate_number ? <span className="cx-mono px-1.5 py-0.5 rounded-md text-[11px] font-semibold" style={{ background: 'rgba(255,255,255,0.07)', color: C.ink }}>{r.plate_number}</span> : null}</div>
          <div className="flex items-center gap-1.5 mt-1 text-[12px] truncate" style={{ color: C.inkFaint }}><MapPin size={12} />{(r?.areas || []).length ? `${r.areas.slice(0, 2).join(', ')}${r.areas.length > 2 ? ` +${r.areas.length - 2}` : ''}` : 'Your areas'}</div>
        </div>
      </div>
    </div>
  );
}

// ---------- Approved riders: the job board, the job in hand, and earnings ----------
const RIDER_JOB_POLL = 12000;
function jobAgo(t) { const m = Math.max(0, Math.round((Date.now() - new Date(t).getTime()) / 60000)); return m < 1 ? 'just now' : m < 60 ? `${m} min ago` : m < 1440 ? `${Math.floor(m / 60)}h ago` : `${Math.floor(m / 1440)}d ago`; }
function riderTime(t) { return t ? new Date(t).toLocaleString('en-GB', { timeZone: 'Africa/Lagos', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit', hour12: true }) : ''; }
function RiderCodeBox({ label, hint, busy, onSubmit, error }) {
  const [code, setCode] = useState('');
  const C = RIDER_LIGHT;
  return (
    <div className="mt-3 rounded-2xl p-3.5" style={{ background: C.field }}>
      <div className="text-[13px] font-bold">{label}</div>
      <div className="text-[12px] mt-0.5 leading-snug" style={{ color: C.inkDim }}>{hint}</div>
      <div className="mt-2.5 flex gap-2">
        <input value={code} onChange={(e) => setCode(e.target.value.replace(/\D/g, '').slice(0, 4))} inputMode="numeric" autoComplete="one-time-code" placeholder="• • • •" aria-label={label}
          className="flex-1 min-w-0 h-12 rounded-xl px-4 text-[22px] font-bold tracking-[0.5em] text-center outline-none" style={{ background: C.surface, border: `1.5px solid ${error ? C.rust : C.lineStrong}`, color: C.ink, fontFamily: "'IBM Plex Mono', ui-monospace, monospace" }} />
        <button type="button" disabled={busy || code.length !== 4} onClick={() => onSubmit(code, () => setCode(''))} className="shrink-0 h-12 px-5 rounded-xl text-[14px] font-bold" style={{ background: C.copper, color: '#fff', opacity: busy || code.length !== 4 ? 0.45 : 1 }}>{busy ? '…' : 'Confirm'}</button>
      </div>
      {error && <div className="mt-2 text-[12.5px] font-semibold" style={{ color: C.rust }}>{error}</div>}
    </div>
  );
}
function RiderWork({ call, me, photo, token }) {
  const C = RIDER_LIGHT;
  const first = String(me.full_name || '').split(' ')[0];
  const [tab, setTab] = useState(() => { try { const t = new URLSearchParams(window.location.search).get('tab'); return ['jobs', 'active', 'earnings'].includes(t) ? t : 'jobs'; } catch (e) { return 'jobs'; } });
  const [open, setOpen] = useState(null);
  const [mine, setMine] = useState(null);
  const [busy, setBusy] = useState('');
  const [errs, setErrs] = useState({});
  const [note, setNote] = useState('');
  const [alerts, setAlerts] = useState(() => { try { return typeof Notification !== 'undefined' && Notification.permission === 'granted'; } catch (e) { return false; } });
  const seenRef = useRef(null);
  const refresh = useCallback(async (quiet = true) => {
    try {
      const [o, m] = await Promise.all([call('rider_open_jobs'), call('rider_my_jobs')]);
      const list = Array.isArray(o) ? o : [];
      // A new job just arrived: a buzz and a short sound
      if (seenRef.current && list.some((j) => !seenRef.current.has(j.id))) {
        try { navigator.vibrate && navigator.vibrate([120, 60, 120]); } catch (e) {}
        try { const ac = new (window.AudioContext || window.webkitAudioContext)(); const osc = ac.createOscillator(); const g = ac.createGain(); osc.frequency.value = 880; g.gain.value = 0.08; osc.connect(g); g.connect(ac.destination); osc.start(); setTimeout(() => { osc.frequency.value = 1320; }, 120); setTimeout(() => { osc.stop(); ac.close(); }, 260); } catch (e) {}
        setNote('New job near you');
      }
      seenRef.current = new Set(list.map((j) => j.id));
      setOpen(list); setMine(m || { jobs: [] });
    } catch (e) { if (!quiet) setNote(e.message); }
  }, [call]);
  useEffect(() => {
    refresh(false);
    const t = setInterval(() => { if (document.visibilityState === 'visible') refresh(); }, RIDER_JOB_POLL);
    const back = () => { if (document.visibilityState === 'visible') refresh(); };
    document.addEventListener('visibilitychange', back); window.addEventListener('online', back);
    return () => { clearInterval(t); document.removeEventListener('visibilitychange', back); window.removeEventListener('online', back); };
  }, [refresh]);
  useEffect(() => { if (!note) return undefined; const t = setTimeout(() => setNote(''), 4000); return () => clearTimeout(t); }, [note]);
  const jobs = mine?.jobs || [];
  const active = jobs.filter((j) => ['taken', 'picked_up'].includes(j.status));
  const done = jobs.filter((j) => j.status === 'delivered');
  const available = !!mine?.available;
  const act = async (job, action, extra = {}) => {
    setBusy(`${job.id}:${action}`); setErrs((x) => ({ ...x, [job.id]: '' }));
    try {
      const r = await call('rider_job_act', { p_job: job.id, p_action: action, p_code: extra.code || null, p_note: extra.note || null });
      if (r && r.error) { setErrs((x) => ({ ...x, [job.id]: r.error })); await refresh(); return false; }
      if (action === 'take') { setTab('active'); setNote(`It's yours. Go to ${r.pickup_name}.`); }
      if (action === 'pickup') setNote('Picked up. Now deliver it.');
      if (action === 'deliver') setNote(`Delivered! ${fmt(r.fee)} earned.`);
      await refresh();
      return true;
    } catch (e) { setErrs((x) => ({ ...x, [job.id]: e.message })); await refresh(); return false; }
    finally { setBusy(''); }
  };
  const toggleAvailable = async () => {
    const next = !available;
    try {
      await call('rider_set_available', { p_on: next });
      setMine((m) => ({ ...(m || {}), available: next }));
      if (next && !alerts) turnOnAlerts();
    } catch (e) { setNote(e.message); }
  };
  const turnOnAlerts = async () => {
    try {
      if (!('serviceWorker' in navigator && 'PushManager' in window && 'Notification' in window)) { setNote("This phone can't show job alerts. Keep Xorla open to see new jobs."); return; }
      const perm = await Notification.requestPermission();
      if (perm !== 'granted') { setNote('Allow notifications to hear about new jobs.'); return; }
      const reg = await navigator.serviceWorker.ready;
      const res = await fetch(`${SB_URL}/functions/v1/push`, { method: 'POST', headers: { 'Content-Type': 'application/json', apikey: SB_KEY, Authorization: `Bearer ${token}` }, body: JSON.stringify({ action: 'config' }) });
      const { publicKey } = await res.json();
      const sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: base64UrlToUint8Array(publicKey) });
      const j = sub.toJSON();
      await call('save_push_subscription', { p_endpoint: j.endpoint, p_p256dh: j.keys.p256dh, p_auth: j.keys.auth });
      setAlerts(true); setNote("Job alerts are on. We'll buzz you when a job opens near you.");
    } catch (e) { setNote("Couldn't turn on alerts. Keep Xorla open to see new jobs."); }
  };
  const maps = (q) => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q || '')}`;
  const tel = (p) => `tel:${String(p || '').replace(/[^0-9+]/g, '')}`;
  const payLabel = (j) => (j.pay_how === 'cash_pickup' ? 'Cash at pick-up' : 'Transfer after delivery');
  const tabs = [['jobs', 'Jobs', (open || []).length], ['active', 'My jobs', active.length], ['earnings', 'Earnings', 0]];
  const Pill = ({ children, tone = 'ink' }) => <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-bold" style={tone === 'sage' ? { background: C.sageSoft, color: C.sage } : tone === 'amber' ? { background: 'rgba(245,163,0,0.14)', color: '#A86F00' } : tone === 'rust' ? { background: C.rustSoft, color: C.rust } : { background: C.chip, color: C.inkDim }}>{children}</span>;
  return (
    <div>
      <div className="flex items-center gap-3">
        <RiderFaceLocal photo={photo} name={me.full_name} />
        <div className="flex-1 min-w-0">
          <div className="text-[13px]" style={{ color: C.inkDim }}>Hello,</div>
          <div className="text-[22px] font-bold leading-tight truncate" style={{ fontFamily: RIDER_DISPLAY, letterSpacing: '-0.03em' }}>{first}</div>
        </div>
        <button type="button" role="switch" aria-checked={available} onClick={toggleAvailable} className="shrink-0 flex items-center gap-2.5 rounded-full pl-3.5 pr-1.5 py-1.5" style={{ background: available ? C.copper : C.surface, color: available ? '#fff' : C.ink, border: `1px solid ${available ? C.copper : C.lineStrong}` }}>
          <span className="text-[12.5px] font-bold">{available ? 'Taking jobs' : 'Not taking jobs'}</span>
          <span className="w-10 h-6 rounded-full relative transition-colors" style={{ background: available ? '#1FD9C4' : C.track }}><span className="absolute top-[3px] w-[18px] h-[18px] rounded-full bg-white transition-all" style={{ left: available ? 19 : 3 }} /></span>
        </button>
      </div>
      {available && !alerts && <button type="button" onClick={turnOnAlerts} className="mt-3 w-full rounded-2xl px-4 py-3 flex items-center gap-3 text-left" style={{ background: 'rgba(245,163,0,0.12)', border: '1px solid rgba(245,163,0,0.35)' }}><Bell size={18} style={{ color: '#A86F00' }} /><span className="flex-1 text-[13px] font-semibold">Turn on job alerts, so your phone buzzes when a job opens</span><ChevronRight size={16} /></button>}
      <div className="mt-4 grid grid-cols-3 gap-1 p-1 rounded-2xl" style={{ background: C.chip }} role="tablist">
        {tabs.map(([id, l, n]) => (
          <button key={id} type="button" role="tab" aria-selected={tab === id} onClick={() => setTab(id)} className="h-10 rounded-xl text-[12.5px] font-bold flex items-center justify-center gap-1.5" style={tab === id ? { background: C.surface, color: C.ink, boxShadow: '0 1px 3px rgba(11,43,38,0.12)' } : { color: C.inkDim }}>
            {l}{n > 0 && <span className="min-w-[18px] h-[18px] px-1 rounded-full text-[10.5px] flex items-center justify-center" style={{ background: id === 'jobs' ? C.amber : C.sage, color: '#fff' }}>{n}</span>}
          </button>
        ))}
      </div>

      {tab === 'jobs' && (
        <div className="mt-4 space-y-3">
          {open === null && <div className="text-center text-[13px] py-8" style={{ color: C.inkFaint }}>Looking for jobs…</div>}
          {open && open.length === 0 && (
            <div className="rounded-[22px] p-6 text-center" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
              <RiderSpotMap className="w-24 h-24 mx-auto" />
              <div className="mt-2 text-[16px] font-bold" style={{ fontFamily: RIDER_DISPLAY, letterSpacing: '-0.02em' }}>No jobs right now</div>
              <div className="mt-1 text-[13px] leading-relaxed" style={{ color: C.inkDim }}>You'll see jobs from {(me.areas || []).slice(0, 3).join(', ')}{(me.areas || []).length > 3 ? ` and ${(me.areas || []).length - 3} more` : ''}. {available ? "We'll buzz you when one opens." : 'Switch on "Taking jobs" to get alerts.'}</div>
            </div>
          )}
          {(open || []).map((j) => (
            <div key={j.id} className="rounded-[22px] p-4" style={{ background: C.surface, border: `1px solid ${C.line}`, boxShadow: '0 14px 30px -24px rgba(11,43,38,0.5)' }}>
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <div className="text-[11.5px] font-semibold" style={{ color: C.inkFaint }}>{jobAgo(j.created_at)} · {payLabel(j)}</div>
                  <div className="mt-1 text-[15.5px] font-bold leading-snug">{j.pickup_name}</div>
                  <div className="mt-1 text-[13px] flex items-center gap-1.5 flex-wrap" style={{ color: C.inkDim }}><MapPin size={13} style={{ color: C.sage }} /> {j.pickup_lga}<ArrowRight size={13} /> {j.dropoff_area || 'Nearby'}</div>
                  {j.package && <div className="mt-1 text-[12.5px] truncate" style={{ color: C.inkFaint }}><Package size={12} className="inline mr-1" />{j.package}</div>}
                </div>
                <div className="text-right shrink-0"><div className="text-[24px] font-bold leading-none" style={{ fontFamily: RIDER_DISPLAY, letterSpacing: '-0.04em' }}>{fmt(j.fee)}</div><div className="text-[11px] mt-1" style={{ color: C.inkFaint }}>you earn</div></div>
              </div>
              {errs[j.id] && <div className="mt-2 text-[12.5px] font-semibold" style={{ color: C.rust }}>{errs[j.id]}</div>}
              <button type="button" disabled={!!busy || active.length >= 2} onClick={() => act(j, 'take')} className="mt-3 w-full h-12 rounded-2xl text-[15px] font-bold flex items-center justify-center gap-2" style={{ background: C.copper, color: '#fff', opacity: busy || active.length >= 2 ? 0.5 : 1 }}>{busy === `${j.id}:take` ? 'Taking it…' : active.length >= 2 ? 'Finish a job first' : <>Accept job <ArrowRight size={17} /></>}</button>
            </div>
          ))}
        </div>
      )}

      {tab === 'active' && (
        <div className="mt-4 space-y-3">
          {active.length === 0 && <div className="rounded-[22px] p-6 text-center text-[13.5px]" style={{ background: C.surface, border: `1px solid ${C.line}`, color: C.inkDim }}>No job in hand. Accept one from <button type="button" onClick={() => setTab('jobs')} className="font-bold underline">Jobs</button>.</div>}
          {active.map((j) => {
            const picked = j.status === 'picked_up';
            return (
              <div key={j.id} className="rounded-[22px] overflow-hidden" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
                <div className="px-4 py-3 flex items-center justify-between" style={{ background: C.mint }}>
                  <span className="text-[12.5px] font-bold" style={{ color: C.copper }}>{picked ? 'Step 2 of 2 · Deliver' : 'Step 1 of 2 · Pick up'}</span>
                  <span className="text-[16px] font-bold" style={{ fontFamily: RIDER_DISPLAY }}>{fmt(j.fee)}</span>
                </div>
                <div className="p-4">
                  {[[false, 'Pick up from', j.pickup_name, j.pickup_address, j.pickup_phone], [true, 'Deliver to', j.customer_name, j.dropoff_address, j.customer_phone]].map(([second, l, who, addr, ph]) => {
                    const current = second === picked;
                    return (
                      <div key={l} className="flex gap-3" style={{ opacity: !second && picked ? 0.5 : 1 }}>
                        <div className="flex flex-col items-center">
                          <span className="w-7 h-7 rounded-full flex items-center justify-center text-[12px] font-bold" style={{ background: !second && picked ? C.sage : current ? C.amber : C.chip, color: !second && picked ? '#fff' : C.ink }}>{!second && picked ? <Check size={14} /> : second ? 2 : 1}</span>
                          {!second && <span className="w-[2px] flex-1 my-1 rounded-full" style={{ background: C.track, minHeight: 18 }} />}
                        </div>
                        <div className="flex-1 min-w-0 pb-3">
                          <div className="text-[11.5px] font-semibold uppercase tracking-wide" style={{ color: C.inkFaint }}>{l}</div>
                          <div className="text-[15px] font-bold">{who}</div>
                          {addr && <div className="text-[13px] leading-snug mt-0.5" style={{ color: C.inkDim }}>{addr}</div>}
                          {current && (
                            <div className="flex flex-wrap gap-2 mt-2">
                              {addr && <a href={maps(addr)} target="_blank" rel="noopener noreferrer" className="h-9 px-3 rounded-xl text-[12.5px] font-bold flex items-center gap-1.5" style={{ background: C.chip }}><MapPin size={14} /> Directions</a>}
                              {ph && <a href={tel(ph)} className="h-9 px-3 rounded-xl text-[12.5px] font-bold flex items-center gap-1.5" style={{ background: C.chip }}><Phone size={14} /> Call</a>}
                              {ph && <a href={`https://wa.me/${toWhatsAppNumber(ph)}`} target="_blank" rel="noopener noreferrer" className="h-9 px-3 rounded-xl text-[12.5px] font-bold flex items-center gap-1.5" style={{ background: C.sageSoft, color: C.sage }}><MessageCircle size={14} /> WhatsApp</a>}
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                  {j.package && <div className="text-[12.5px] rounded-xl px-3 py-2" style={{ background: C.field, color: C.inkDim }}><strong style={{ color: C.ink }}>Package:</strong> {j.package}{j.note ? <><br /><strong style={{ color: C.ink }}>Note:</strong> {j.note}</> : null}</div>}
                  {j.locked ? (
                    <div className="mt-3 rounded-2xl p-3.5 text-[13px] leading-relaxed" style={{ background: C.rustSoft, color: C.rust }}><strong>Locked after 5 wrong codes.</strong> Call {j.pickup_name} so they can send new codes.</div>
                  ) : picked ? (
                    <RiderCodeBox label={`${String(j.customer_name || 'The customer').split(' ')[0]}'s code`} hint="Hand over the order, then ask the customer for their 4-digit delivery code." busy={busy === `${j.id}:deliver`} error={errs[j.id]} onSubmit={async (code, clear) => { if (await act(j, 'deliver', { code })) clear(); }} />
                  ) : (
                    <RiderCodeBox label="Pick-up code" hint={`When you collect the package, ${j.pickup_name} gives you a 4-digit code.`} busy={busy === `${j.id}:pickup`} error={errs[j.id]} onSubmit={async (code, clear) => { if (await act(j, 'pickup', { code })) clear(); }} />
                  )}
                  <div className="mt-3 flex items-center justify-between text-[12px]" style={{ color: C.inkFaint }}>
                    <span>{payLabel(j)}</span>
                    {!picked && <button type="button" onClick={async () => { if (await brandConfirm(`Give this job back? ${j.pickup_name} is told, and it goes back to other riders. Giving jobs back often can pause your account.`, { confirm: 'Give it back', danger: true, theme: 'light' })) act(j, 'release', { note: '' }); }} className="font-semibold underline">Give the job back</button>}
                  </div>
                </div>
              </div>
            );
          })}
          {jobs.filter((j) => j.status === 'cancelled' && Date.now() - new Date(j.cancelled_at).getTime() < 6 * 3600000).map((j) => (
            <div key={j.id} className="rounded-2xl px-4 py-3 text-[13px]" style={{ background: C.rustSoft, color: C.rust }}><strong>{j.pickup_name} cancelled a job</strong>{j.cancel_reason ? `: ${j.cancel_reason}` : ''}. Don't go for the pick-up.</div>
          ))}
        </div>
      )}

      {tab === 'earnings' && (
        <div className="mt-4 space-y-3">
          <RiderPass r={me} photo={photo} compact />
          <div className="grid grid-cols-3 gap-2">
            {[['This week', fmt(mine?.earned_week || 0)], ['All time', fmt(mine?.earned_all || 0)], ['Deliveries', String(mine?.delivered_count || 0)]].map(([l, v]) => (
              <div key={l} className="rounded-2xl px-3 py-3" style={{ background: C.surface, border: `1px solid ${C.line}` }}><div className="text-[11px] font-semibold uppercase tracking-wide" style={{ color: C.inkFaint }}>{l}</div><div className="text-[18px] font-bold mt-0.5 truncate" style={{ fontFamily: RIDER_DISPLAY, letterSpacing: '-0.03em' }}>{v}</div></div>
            ))}
          </div>
          <div className="text-[12px] leading-relaxed px-1" style={{ color: C.inkFaint }}>Businesses pay you directly: cash at pick-up, or a transfer to {me.bank_name ? `your ${me.bank_name} account` : 'your bank'}. Confirm each one when the money reaches you.</div>
          {done.length === 0 && <div className="rounded-2xl p-5 text-center text-[13px]" style={{ background: C.surface, border: `1px solid ${C.line}`, color: C.inkDim }}>Your deliveries and payments show here.</div>}
          <div className="rounded-[22px] overflow-hidden" style={{ background: C.surface, border: done.length ? `1px solid ${C.line}` : 'none' }}>
            {done.map((j, i) => (
              <div key={j.id} className="px-4 py-3" style={{ borderTop: i ? `1px solid ${C.line}` : 'none' }}>
                <div className="flex items-center justify-between gap-3">
                  <span className="min-w-0"><span className="block text-[14px] font-bold truncate">{j.pickup_name}</span><span className="block text-[12px]" style={{ color: C.inkFaint }}>{riderTime(j.delivered_at)} · {j.pickup_lga}</span></span>
                  <span className="text-[16px] font-bold shrink-0" style={{ fontFamily: RIDER_DISPLAY }}>{fmt(j.fee)}</span>
                </div>
                <div className="mt-1.5 flex items-center gap-2 flex-wrap">
                  {j.rider_confirmed_paid_at ? <Pill tone="sage"><Check size={11} /> You got it</Pill>
                    : j.paid_at ? <><Pill tone="amber">Business says it's paid ({j.paid_how === 'cash' ? 'cash' : 'transfer'})</Pill><button type="button" disabled={!!busy} onClick={() => act(j, 'got_paid')} className="h-7 px-3 rounded-full text-[11.5px] font-bold" style={{ background: C.copper, color: '#fff' }}>I got it</button></>
                    : <Pill>Waiting for payment</Pill>}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
      {note && <div className="fixed left-0 right-0 bottom-6 z-50 flex justify-center px-4 pointer-events-none"><div className="rounded-full px-4 py-2.5 text-[13px] font-bold xorla-fade-up" style={{ background: C.copper, color: '#fff', boxShadow: '0 10px 30px rgba(11,43,38,0.35)' }}>{note}</div></div>}
    </div>
  );
}
function RiderFaceLocal({ photo, name }) {
  const C = RIDER_LIGHT;
  const initials = String(name || '?').trim().split(/\s+/).slice(0, 2).map((w) => w[0]).join('').toUpperCase();
  return photo ? <img src={photo} alt="" className="w-14 h-14 rounded-2xl object-cover shrink-0" style={{ border: `2px solid ${C.sage}` }} /> : <span className="w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 text-[17px] font-bold" style={{ background: C.mint, color: C.copper }}>{initials}</span>;
}

// ============ Live selfie: the camera opens inside the page (nothing to leave, so the phone can't close the page) ============
// The rider sees themselves in an oval, takes the photo, and checks it before using it. The saved photo is not mirrored,
// so it matches the face on their ID. If the camera can't open (no permission, old phone), the caller offers other ways.
const canLiveCamera = () => typeof navigator !== 'undefined' && !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia) && typeof window !== 'undefined' && window.isSecureContext !== false;
function LiveSelfie({ onUse, onClose, onFail }) {
  const videoRef = useRef(null); const streamRef = useRef(null);
  const [state, setState] = useState('starting');   // starting | live | shot | error
  const [shot, setShot] = useState(null);           // { url, blob }
  const [count, setCount] = useState(0);
  const [msg, setMsg] = useState('');
  const stop = () => { try { (streamRef.current?.getTracks() || []).forEach((t) => t.stop()); } catch (e) {} streamRef.current = null; };
  const start = async () => {
    setState('starting'); setMsg('');
    try {
      const st = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 1280 } }, audio: false });
      streamRef.current = st;
      const v = videoRef.current; if (!v) { stop(); return; }
      v.srcObject = st; v.setAttribute('playsinline', ''); v.muted = true;
      await v.play().catch(() => {});
      setState('live');
    } catch (e) {
      const denied = e && /NotAllowed|Permission|Security/i.test(`${e.name} ${e.message}`);
      setMsg(denied ? 'Xorla needs your permission to use the camera. Tap the camera or lock icon in your browser\'s address bar, allow the camera, then try again.' : "Your camera didn't open on this phone.");
      setState('error'); onFail && onFail(denied ? 'denied' : 'unavailable');
    }
  };
  useEffect(() => {
    start();
    const prev = document.body.style.overflow; document.body.style.overflow = 'hidden';
    return () => { stop(); document.body.style.overflow = prev; };
  }, []);
  useEffect(() => () => { if (shot?.url) URL.revokeObjectURL(shot.url); }, [shot]);
  const snap = () => {
    const v = videoRef.current; if (!v || !v.videoWidth) return;
    const max = 1280; const scale = Math.min(1, max / Math.max(v.videoWidth, v.videoHeight));
    const c = document.createElement('canvas'); c.width = Math.round(v.videoWidth * scale); c.height = Math.round(v.videoHeight * scale);
    c.getContext('2d').drawImage(v, 0, 0, c.width, c.height);
    c.toBlob((b) => { if (!b) return; setShot({ blob: b, url: URL.createObjectURL(b) }); setState('shot'); stop(); }, 'image/jpeg', 0.9);
  };
  const countdown = () => {
    if (count) return;
    let n = 3; setCount(n);
    const t = setInterval(() => { n -= 1; if (n <= 0) { clearInterval(t); setCount(0); snap(); } else setCount(n); }, 700);
  };
  const retake = () => { setShot(null); start(); };
  const use = () => { if (!shot) return; const file = new File([shot.blob], `selfie-${Date.now()}.jpg`, { type: 'image/jpeg' }); onUse(file); };
  return createPortal(
    <div className="fixed inset-0 z-[120] flex flex-col" style={{ background: '#050B0A', color: '#fff', fontFamily: "'Poppins', 'Inter', system-ui, sans-serif" }} role="dialog" aria-modal="true" aria-label="Take a selfie">
      <div className="flex items-center justify-between px-4 pt-[max(14px,env(safe-area-inset-top))] pb-3">
        <button onClick={() => { stop(); onClose(); }} className="w-10 h-10 rounded-full flex items-center justify-center" style={{ background: 'rgba(255,255,255,0.1)' }} aria-label="Close"><X size={18} /></button>
        <span className="text-[14px] font-semibold">{state === 'shot' ? 'Is your face clear?' : 'Take a selfie'}</span>
        <span className="w-10" />
      </div>
      <div className="relative flex-1 min-h-0 mx-4 rounded-3xl overflow-hidden" style={{ background: '#0B1513' }}>
        <video ref={videoRef} autoPlay playsInline muted className="absolute inset-0 w-full h-full object-cover" style={{ transform: 'scaleX(-1)', display: state === 'shot' ? 'none' : 'block' }} />
        {state === 'shot' && shot && <img src={shot.url} alt="Your selfie" className="absolute inset-0 w-full h-full object-cover" style={{ transform: 'scaleX(-1)' }} />}
        {(state === 'live' || state === 'starting') && (
          <svg aria-hidden className="absolute inset-0 w-full h-full pointer-events-none" viewBox="0 0 100 130" preserveAspectRatio="xMidYMid slice">
            <defs><mask id="xsm"><rect width="100" height="130" fill="#fff" /><ellipse cx="50" cy="58" rx="29" ry="38" fill="#000" /></mask></defs>
            <rect width="100" height="130" fill="rgba(5,11,10,0.55)" mask="url(#xsm)" />
            <ellipse cx="50" cy="58" rx="29" ry="38" fill="none" stroke={count ? '#FFB020' : '#1FD9C4'} strokeWidth="0.8" strokeDasharray={count ? '0' : '2.2 1.6'} />
          </svg>
        )}
        {state === 'starting' && <div className="absolute inset-0 flex items-center justify-center"><Loader2 size={26} className="animate-spin" style={{ color: '#1FD9C4' }} /></div>}
        {count > 0 && <div className="absolute inset-0 flex items-center justify-center"><span key={count} className="xorla-fade-up text-[84px] font-extrabold" style={{ color: '#FFB020', textShadow: '0 6px 30px rgba(0,0,0,0.6)' }}>{count}</span></div>}
        {state === 'error' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-center px-6">
            <span className="w-14 h-14 rounded-2xl flex items-center justify-center mb-3" style={{ background: 'rgba(255,176,32,0.15)' }}><CameraOff size={24} style={{ color: '#FFB020' }} /></span>
            <div className="text-[15px] font-semibold mb-1.5">Camera not available</div>
            <div className="text-[13px] leading-relaxed max-w-[300px]" style={{ color: 'rgba(255,255,255,0.72)' }}>{msg}</div>
          </div>
        )}
      </div>
      <div className="px-5 pt-3 pb-[max(18px,env(safe-area-inset-bottom))]">
        {state === 'shot' ? (
          <>
            <div className="text-[12.5px] text-center mb-3" style={{ color: 'rgba(255,255,255,0.7)' }}>Whole face showing, in good light, no cap or sunglasses?</div>
            <div className="flex gap-3">
              <button onClick={retake} className="flex-1 h-12 rounded-xl text-[14.5px] font-semibold flex items-center justify-center gap-1.5" style={{ border: '1px solid rgba(255,255,255,0.25)' }}><RotateCcw size={16} /> Retake</button>
              <button onClick={use} className="flex-[1.4] h-12 rounded-xl text-[14.5px] font-bold flex items-center justify-center gap-1.5" style={{ background: '#1FD9C4', color: '#062420' }}><Check size={17} /> Use this photo</button>
            </div>
          </>
        ) : state === 'error' ? (
          <div className="flex gap-3">
            <button onClick={() => { stop(); onClose(); }} className="flex-1 h-12 rounded-xl text-[14.5px] font-semibold" style={{ border: '1px solid rgba(255,255,255,0.25)' }}>Other ways</button>
            <button onClick={start} className="flex-1 h-12 rounded-xl text-[14.5px] font-bold" style={{ background: '#1FD9C4', color: '#062420' }}>Try again</button>
          </div>
        ) : (
          <>
            <div className="text-[12.5px] text-center mb-3" style={{ color: 'rgba(255,255,255,0.7)' }}>Fit your face in the oval. Face the light, no cap or sunglasses.</div>
            <div className="flex justify-center">
              <button onClick={countdown} disabled={state !== 'live' || !!count} aria-label="Take photo" className="w-[74px] h-[74px] rounded-full flex items-center justify-center" style={{ border: '4px solid #fff', opacity: state === 'live' ? 1 : 0.5 }}>
                <span className="w-[58px] h-[58px] rounded-full" style={{ background: count ? '#FFB020' : '#fff' }} />
              </button>
            </div>
          </>
        )}
      </div>
    </div>, document.body);
}

function RiderApp() {
  const C = RIDER_LIGHT;   // the rider pages are light and friendly (the rider pass card stays dark)
  const [sess, setSess] = useState(() => { try { return JSON.parse(localStorage.getItem(RIDER_SESSION_KEY) || 'null'); } catch (e) { return null; } });
  const [me, setMe] = useState(undefined);       // undefined = loading, null = no application yet
  const [view, setView] = useState('home');      // home | auth (when logged out)
  const [authMode, setAuthMode] = useState('signup');
  const [auth, setAuth] = useState({ email: '', password: '', show: false, busy: false, error: '', note: '' });
  const [step, setStep] = useState(0);
  const [f, setF] = useState({});
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const [saved, setSaved] = useState('');
  const [photos, setPhotos] = useState({});      // signed / local previews of the ID and selfie
  const [upBusy, setUpBusy] = useState('');
  const [banks, setBanks] = useState(null);
  const [bank, setBank] = useState({ q: '', code: '', name: '', number: '', busy: false, error: '' });
  const [agree, setAgree] = useState(false);
  const topRef = useRef(null);
  // Rider home page: sections glide in as you scroll, and menu links scroll smoothly
  const riderHomeRef = useRef(null);
  useEffect(() => {
    if (sess || view !== 'home') return undefined;
    const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const html = document.documentElement; const prev = html.style.scrollBehavior; if (!reduce) html.style.scrollBehavior = 'smooth';
    const els = riderHomeRef.current ? [...riderHomeRef.current.querySelectorAll('[data-reveal]')] : [];
    let io = null;
    if (reduce || !('IntersectionObserver' in window)) els.forEach((el) => el.classList.add('lp-in'));
    else { io = new IntersectionObserver((entries) => entries.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('lp-in'); io.unobserve(e.target); } }), { threshold: 0.12, rootMargin: '0px 0px -40px 0px' }); els.forEach((el) => io.observe(el)); }
    return () => { if (io) io.disconnect(); html.style.scrollBehavior = prev; };
  }, [sess, view]);
  useEffect(() => {
    document.title = 'Ride with Xorla';
  }, []);

  const saveSess = (s) => { setSess(s); try { if (s) localStorage.setItem(RIDER_SESSION_KEY, JSON.stringify(s)); else localStorage.removeItem(RIDER_SESSION_KEY); } catch (e) {} };
  // Keep the login fresh (tokens last about an hour)
  const call = useCallback(async (fn, params = {}) => {
    let s = sess;
    if (s && s.expires_at && Date.now() / 1000 > s.expires_at - 120) {
      try { const r = await sbRefresh(s.refresh_token); s = { access_token: r.access_token, refresh_token: r.refresh_token, user_id: r.user.id, expires_at: r.expires_at || Math.floor(Date.now() / 1000) + 3500 }; saveSess(s); }
      catch (e) { saveSess(null); setMe(undefined); throw new Error('Please log in again.'); }
    }
    return sbRpc(fn, s.access_token, params);
  }, [sess]);
  // What the rider typed on this phone but hasn't saved yet (kept in case the phone reloads the page): laid over
  // whatever is loaded, so a late load can never wipe it
  const typedDraft = (r) => {
    if (!sess?.user_id || (r && !['draft', 'needs_fix'].includes(r.status || 'draft'))) return {};
    try {
      const d = JSON.parse(localStorage.getItem(`xorla:rider-draft:${sess.user_id}`) || 'null');
      if (!d || !d.f || Date.now() - (d.at || 0) > 3 * 86400000) return {};
      return Object.fromEntries(Object.entries(d.f).filter(([k, v]) => v !== '' && v != null && !['id_doc', 'selfie_doc'].includes(k) && !(Array.isArray(v) && !v.length)));
    } catch (e) { return {}; }
  };
  const fill = (r) => {
    setMe(r);
    if (!r) return;
    const typed = typedDraft(r);
    setF({ ...typed, ...{ full_name: r.full_name || '', phone: r.phone || '', date_of_birth: r.date_of_birth || '', home_address: r.home_address || '', state: r.state || 'Abia', lga: r.lga || '', areas: r.areas || [],
      vehicle: r.vehicle || '', plate_number: r.plate_number || '', id_type: r.id_type || '', id_number: r.id_number || '', id_doc: r.id_doc || '', selfie_doc: r.selfie_doc || '',
      guarantor_name: r.guarantor_name || '', guarantor_phone: r.guarantor_phone || '', guarantor_relationship: r.guarantor_relationship || '', guarantor_address: r.guarantor_address || '' },
      ...typed });
  };
  const load = useCallback(async () => {
    if (!sess) { setMe(undefined); return; }
    try { const r = await call('rider_me'); fill(r || null); if (!r) setF({ state: 'Abia', areas: [], ...typedDraft(null) }); }
    catch (e) { if (/log in/i.test(e.message || '') || /JWT|expired/i.test(e.message || '')) { saveSess(null); } else { setMe(null); setErr(e.message); } }
  }, [sess, call]);
  useEffect(() => { load(); }, [sess?.user_id]);
  // Show the ID and selfie they already uploaded
  useEffect(() => {
    if (!sess || !me) return;
    ['id_doc', 'selfie_doc'].forEach((k) => {
      if (me[k] && !photos[k]) vaultFileUrl(sess.access_token, 'rider-docs', me[k]).then((u) => setPhotos((p) => ({ ...p, [k]: u }))).catch(() => {});
    });
  }, [me?.id_doc, me?.selfie_doc, sess?.access_token]);
  // Phones often close the page while the camera is open (to free memory), so it reloads when the rider comes back.
  // Keep the step they were on and what they've typed on this phone, and put them straight back there.
  const draftKey = sess?.user_id ? `xorla:rider-draft:${sess.user_id}` : '';
  const [draftReady, setDraftReady] = useState(false);
  const [camBack, setCamBack] = useState('');   // which photo's camera was open when the page reloaded
  const [liveCam, setLiveCam] = useState(false);       // the in-page selfie camera is open
  const [otherWays, setOtherWays] = useState(false);   // the live camera didn't work: offer the phone camera or the gallery
  useEffect(() => {
    if (!draftKey || me === undefined || draftReady) return;
    setDraftReady(true);
    if (me && !['draft', 'needs_fix'].includes(me.status || 'draft')) return;
    try {
      const d = JSON.parse(localStorage.getItem(draftKey) || 'null');
      if (!d || Date.now() - (d.at || 0) > 3 * 86400000) return;
      if (d.f && typeof d.f === 'object') setF((x) => ({ ...x, ...typedDraft(me) }));
      if (Number.isInteger(d.step) && d.step >= 0 && d.step <= 4) setStep(d.step);
      if (d.cam) setCamBack(d.cam);
    } catch (e) {}
  }, [draftKey, me, draftReady]);
  useEffect(() => {
    if (!draftKey || !draftReady) return;
    if (me && !['draft', 'needs_fix'].includes(me.status || 'draft')) { try { localStorage.removeItem(draftKey); } catch (e) {} return; }
    try { localStorage.setItem(draftKey, JSON.stringify({ f, step, at: Date.now() })); } catch (e) {}
  }, [f, step, draftKey, draftReady, me?.status]);
  // Remember that the camera was opened, so if the page reloads we can say what happened and offer the gallery instead
  const markCamera = (k) => { if (!draftKey) return; try { const d = JSON.parse(localStorage.getItem(draftKey) || '{}'); localStorage.setItem(draftKey, JSON.stringify({ ...d, f, step, at: Date.now(), cam: k })); } catch (e) {} };
  const clearCamera = () => { setCamBack(''); if (!draftKey) return; try { const d = JSON.parse(localStorage.getItem(draftKey) || '{}'); delete d.cam; localStorage.setItem(draftKey, JSON.stringify(d)); } catch (e) {} };
  // A fix requested: jump to the right step
  useEffect(() => {
    if (me?.status !== 'needs_fix') return;
    const n = String(me.review_note || '').toLowerCase();
    setStep(/selfie|photo of you|face/.test(n) ? 2 : /\bid\b|nin|licen|passport|voter/.test(n) ? 2 : /guarantor/.test(n) ? 3 : /bank|account/.test(n) ? 4 : /plate|bike|car|area/.test(n) ? 1 : 0);
  }, [me?.status]);
  useEffect(() => {
    if (step === 4 && sess && banks === null) riderBilling(sess.access_token, 'rider_banks').then((b) => setBanks(Array.isArray(b) ? b : [])).catch((e) => { setBanks([]); setBank((x) => ({ ...x, error: e.message })); });
  }, [step, sess]);

  const doAuth = async () => {
    const email = auth.email.trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { setAuth((a) => ({ ...a, error: 'Enter your email address.' })); return; }
    if (authMode !== 'forgot' && auth.password.length < PASSWORD_MIN_LENGTH) { setAuth((a) => ({ ...a, error: `Your password needs at least ${PASSWORD_MIN_LENGTH} characters.` })); return; }
    setAuth((a) => ({ ...a, busy: true, error: '', note: '' }));
    try {
      if (authMode === 'forgot') { await sbRecover(email); setAuth((a) => ({ ...a, busy: false, note: `We've sent a link to ${email} to set a new password.` })); return; }
      let r = authMode === 'signup' ? await sbSignUp(email, auth.password) : await sbSignIn(email, auth.password);
      if (authMode === 'signup' && !r.access_token) {
        try { r = await sbSignIn(email, auth.password); } catch (e) { setAuth((a) => ({ ...a, busy: false, note: `Almost there: we've sent a link to ${email}. Open it to confirm your email, then log in here.` })); setAuthMode('login'); return; }
      }
      saveSess({ access_token: r.access_token, refresh_token: r.refresh_token, user_id: r.user?.id, expires_at: r.expires_at || Math.floor(Date.now() / 1000) + 3500 });
      setAuth({ email: '', password: '', show: false, busy: false, error: '', note: '' });
      window.scrollTo(0, 0);
    } catch (e) { setAuth((a) => ({ ...a, busy: false, error: e.message })); }
  };
  const logout = () => { saveSess(null); setMe(undefined); setView('home'); setStep(0); setPhotos({}); setBanks(null); };

  const set = (patch) => { setF((x) => ({ ...x, ...patch })); setErr(''); };
  const stepFields = [['full_name', 'phone', 'date_of_birth', 'home_address', 'state', 'lga', 'areas'], ['vehicle', 'plate_number', 'areas'], ['id_type', 'id_number', 'id_doc', 'selfie_doc'], ['guarantor_name', 'guarantor_phone', 'guarantor_relationship', 'guarantor_address'], []];
  const stepProblem = (i) => {
    const need = (k, label) => (!String(f[k] || '').trim() ? label : '');
    if (i === 0) return need('full_name', 'your full name') || need('phone', 'your phone number') || need('date_of_birth', 'your date of birth') || need('home_address', 'your home address') || need('lga', 'your local government');
    if (i === 1) return !f.vehicle ? 'how you deliver' : (['bike', 'tricycle', 'car', 'van'].includes(f.vehicle) && !String(f.plate_number || '').trim()) ? 'your plate number' : !(f.areas || []).length ? 'at least one area you cover' : '';
    if (i === 2) return need('id_type', 'your type of ID') || need('id_number', 'your ID number') || need('id_doc', 'a photo of your ID') || need('selfie_doc', 'your selfie');
    if (i === 3) return need('guarantor_name', "your guarantor's name") || need('guarantor_phone', "your guarantor's phone number") || need('guarantor_relationship', 'how you know them') || need('guarantor_address', "your guarantor's address");
    return '';
  };
  const saveStep = async (next) => {
    const p = stepProblem(step);
    if (p && next > step) { setErr(`Please add ${p}.`); return; }
    setBusy(true); setErr('');
    try {
      const payload = Object.fromEntries(stepFields[step].map((k) => [k, f[k] ?? '']));
      if (stepFields[step].length) { const r = await call('rider_save', { p: payload }); fill(r); setSaved('Saved'); setTimeout(() => setSaved(''), 1800); }
      setStep(next); topRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    } catch (e) { setErr(e.message); }
    setBusy(false);
  };
  const pickPhoto = async (k, file, live = false) => {
    clearCamera(); setLiveCam(false);
    if (!file) return;
    setUpBusy(k); setErr('');
    try {
      if (!me) setMe(await call('rider_save', { p: { full_name: f.full_name || '' } }));
      // A selfie taken with the live camera is marked as such, so the Xorla team can tell it from an uploaded picture
      const path = await riderUpload(sess.access_token, sess.user_id, file, k === 'id_doc' ? 'id' : live ? 'selfie-live' : 'selfie');
      // Keep what they've typed on this step (it's saved when they continue); only the photo changes here
      setMe(await call('rider_save', { p: { [k]: path } })); setF((x) => ({ ...x, [k]: path }));
      setPhotos((p) => ({ ...p, [k]: URL.createObjectURL(file) }));
    } catch (e) { setErr(e.message); }
    setUpBusy('');
  };
  const checkBank = async () => {
    if (!bank.code || bank.number.length !== 10) { setBank((b) => ({ ...b, error: 'Choose your bank and enter the 10-digit account number.' })); return; }
    setBank((b) => ({ ...b, busy: true, error: '' }));
    try { await riderBilling(sess.access_token, 'rider_bank', { bank_code: bank.code, bank_name: bank.name, account_number: bank.number }); setMe(await call('rider_me')); setBank({ q: '', code: '', name: '', number: '', busy: false, error: '' }); }
    catch (e) { setBank((b) => ({ ...b, busy: false, error: e.message })); }
  };
  const submit = async () => {
    for (let i = 0; i < 4; i++) { const p = stepProblem(i); if (p) { setStep(i); setErr(`Please add ${p}.`); return; } }
    if (!me?.account_number) { setErr('Add your bank account first.'); return; }
    if (!agree) { setErr('Please tick the box to confirm your details are true.'); return; }
    setBusy(true); setErr('');
    try { const r = await call('rider_submit'); fill(r); window.scrollTo({ top: 0, behavior: 'smooth' }); }
    catch (e) { setErr(e.message); }
    setBusy(false);
  };

  const page = { background: `radial-gradient(700px 420px at 100% 0%, rgba(31,217,196,0.10), transparent 60%), radial-gradient(600px 400px at 0% 20%, rgba(255,176,32,0.08), transparent 60%), ${C.bg}`, color: C.ink, minHeight: '100vh', fontFamily: RIDER_FONT };
  const field = { background: C.field, border: `1.5px solid ${C.field}`, color: C.ink };
  const inputCls = 'w-full rounded-xl px-4 py-3 text-[15px] outline-none focus:ring-2 focus:ring-[#0E9F8E]/40 focus:bg-white';
  const label = (t, hint) => <label className="block text-[13px] font-semibold mb-1.5">{t}{hint ? <span className="font-normal" style={{ color: C.inkFaint }}> {hint}</span> : null}</label>;
  const chip = (on) => ({ background: on ? C.copper : C.surface, color: on ? '#fff' : C.ink, border: `1.5px solid ${on ? C.copper : C.lineStrong}` });
  const header = (
    <header className="max-w-[1280px] mx-auto px-5 sm:px-8 lg:px-10 pb-2 flex items-center justify-between gap-3" style={{ paddingTop: 'max(18px, env(safe-area-inset-top))' }}>
      <a href="/ride" className="flex items-center gap-2.5"><XorlaMark size={28} /><span className="text-[18px] font-bold" style={{ letterSpacing: '-0.03em', fontFamily: RIDER_DISPLAY }}>Xorla</span><span className="text-[11.5px] font-bold px-2.5 py-0.5 rounded-full" style={{ background: C.mint, color: C.sage }}>riders</span></a>
      {sess ? <button onClick={logout} className="flex items-center gap-1.5 text-[13.5px] font-semibold px-3.5 py-2 rounded-full" style={{ color: C.inkDim, background: C.surface, boxShadow: `0 0 0 1px ${C.line}` }}><LogOut size={14} /> Log out</button>
        : view === 'home' ? (
          <nav className="flex items-center gap-1 sm:gap-2">
            <a href="#how" className="hidden sm:block px-3 py-2 text-[14px] font-semibold" style={{ color: C.ink }}>How it works</a>
            <button onClick={() => { setAuthMode('login'); setView('auth'); window.scrollTo(0, 0); }} className="px-3 py-2 text-[14px] font-semibold" style={{ color: C.ink }}>Log in</button>
            <button onClick={() => { setAuthMode('signup'); setView('auth'); window.scrollTo(0, 0); }} className="px-4 py-2 rounded-full text-[14px] font-bold" style={{ background: C.mint, color: C.copper }}>Apply now</button>
          </nav>
        ) : null}
    </header>
  );
  const footer = <footer className="max-w-[1280px] mx-auto px-5 sm:px-8 lg:px-10 py-10 text-[12px] flex flex-wrap gap-x-4 gap-y-1" style={{ color: C.inkFaint }}><span>© Xorla</span><a href="/terms" style={{ color: C.inkDim }}>Terms</a><a href="/privacy" style={{ color: C.inkDim }}>Privacy</a><span>Your ID, selfie and bank details are private. Only the Xorla team can see them.</span></footer>;

  // ---------- Logged out: the welcome page ----------
  if (!sess && view === 'home') {
    const go = (mode) => { setAuthMode(mode); setView('auth'); window.scrollTo(0, 0); };
    const perks = [[RiderSpotMap, 'Pick the jobs you want', 'See deliveries in the areas you choose, and take the ones that suit your day.'], [RiderSpotPay, 'Paid to your bank', 'Your fee goes straight to your own account. No chasing anyone for money.'], [RiderSpotSafe, 'Safe for everyone', 'Every rider is checked: ID, selfie and a guarantor. Customers trust you more.']];
    const how = [['Apply', 'About 10 minutes on your phone'], ['We check you', 'ID, selfie, guarantor and bank. 1 to 3 working days'], ['Get approved', 'Your Xorla Rider Pass turns green'], ['Start delivering', 'Jobs open city by city, from Umuahia and Aba']];
    const need = ['Your phone number', "NIN, driver's licence, voter's card or passport", 'A clear selfie', 'Someone who will stand for you (a guarantor)', 'A bank account in your own name', 'Your plate number (bike, keke, car or van)'];
    return (
      <div style={page} ref={riderHomeRef}>
        <style>{`
          .rd-hero-in > * { opacity: 0; transform: translateY(18px); animation: rdUp .8s cubic-bezier(.2,.7,.2,1) forwards; }
          .rd-hero-in > *:nth-child(2) { animation-delay: .1s; } .rd-hero-in > *:nth-child(3) { animation-delay: .2s; } .rd-hero-in > *:nth-child(4) { animation-delay: .3s; } .rd-hero-in > *:nth-child(5) { animation-delay: .4s; } .rd-hero-in > *:nth-child(6) { animation-delay: .5s; }
          .rd-art-in { opacity: 0; transform: translateX(40px); animation: rdIn 1s cubic-bezier(.2,.7,.2,1) .15s forwards; }
          @keyframes rdUp { to { opacity: 1; transform: none; } }
          @keyframes rdIn { to { opacity: 1; transform: none; } }
          .lp-float { animation: lpFloat 6s ease-in-out infinite; }
          @keyframes lpFloat { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
          .rd-bob { animation: rdBob 3.2s ease-in-out infinite; transform-box: fill-box; }
          .rd-bob2 { animation: rdBob 3.8s ease-in-out .6s infinite; transform-box: fill-box; }
          @keyframes rdBob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-7px); } }
          .rd-speed { animation: rdSpeed 1.1s ease-in-out infinite; }
          @keyframes rdSpeed { 0%,100% { opacity: 1; transform: translateX(0); } 50% { opacity: .35; transform: translateX(-8px); } }
          [data-reveal] { opacity: 0; transform: translateY(26px); transition: opacity .8s cubic-bezier(.2,.7,.2,1), transform .8s cubic-bezier(.2,.7,.2,1), box-shadow .3s ease; transition-delay: var(--d, 0s); }
          [data-reveal].lp-in { opacity: 1; transform: none; }
          .rd-tile.lp-in:hover { transform: translateY(-4px); }
          .lp-line-grow { transform-origin: left; transform: scaleX(0); transition: transform 1.2s cubic-bezier(.2,.7,.2,1) .25s; }
          .lp-in .lp-line-grow { transform: scaleX(1); }
          .rd-pass-tilt { animation: rdTilt 7s ease-in-out infinite; }
          @keyframes rdTilt { 0%,100% { transform: rotate(-1.5deg) translateY(0); } 50% { transform: rotate(1deg) translateY(-6px); } }
          @media (prefers-reduced-motion: reduce) {
            .rd-hero-in > *, .rd-art-in, [data-reveal] { animation: none !important; opacity: 1 !important; transform: none !important; transition: none !important; }
            .lp-float, .rd-bob, .rd-bob2, .rd-speed, .rd-pass-tilt { animation: none !important; }
            .lp-line-grow { transform: none !important; }
          }
        `}</style>
        {header}
        <main>
          <section className="max-w-[1280px] mx-auto px-5 sm:px-8 lg:px-10 grid lg:grid-cols-[1fr_1.05fr] gap-6 lg:gap-10 items-center pt-6 lg:pt-12 pb-10">
            <div className="order-2 lg:order-1 rd-hero-in">
              <div className="text-[18px] sm:text-[20px] font-bold" style={{ color: C.ink, fontFamily: RIDER_FONT }}>Hello, rider!</div>
              <h1 className="mt-1 text-[38px] sm:text-[54px] font-extrabold leading-[1.04]" style={{ letterSpacing: '-0.045em', fontFamily: RIDER_DISPLAY }}>Deliver more.<br /><span style={{ color: C.amber }}>Earn more.</span></h1>
              <div className="mt-4 w-14 h-1.5 rounded-full" style={{ background: C.sage }} />
              <p className="mt-4 text-[16px] leading-relaxed max-w-md" style={{ color: C.inkDim }}>Join the Xorla rider network. Get delivery jobs from shops, restaurants and hotels near you, and get paid straight to your bank.</p>
              <div className="mt-7 rounded-[22px] sm:rounded-full p-2 flex flex-col sm:flex-row sm:items-center gap-2 max-w-lg" style={{ background: C.surface, boxShadow: '0 18px 40px -18px rgba(11,43,38,0.28), 0 0 0 1px rgba(11,43,38,0.06)' }}>
                <div className="flex items-center gap-2 flex-1 min-w-0 pl-3">
                  <MapPin size={18} style={{ color: C.sage }} className="shrink-0" />
                  <BrandSelect palette={RIDER_LIGHT} value={f.state || 'Abia'} onChange={(e) => setF((x) => ({ ...x, state: e.target.value }))} className="flex-1 min-w-0 py-2.5 text-[15px] font-medium" style={{ background: 'transparent', border: 'none', color: C.ink }} aria-label="Where do you ride?">
                    {NG_STATES.map((s) => <option key={s} value={s}>I ride in {s}</option>)}
                  </BrandSelect>
                </div>
                <button onClick={() => go('signup')} className="h-12 px-7 rounded-full text-[15px] font-bold flex items-center justify-center gap-2 shrink-0" style={{ background: C.copper, color: '#fff' }}>Apply now <ArrowRight size={17} /></button>
              </div>
              <div className="mt-4 text-[14px]" style={{ color: C.inkDim }}>Already applied? <button onClick={() => go('login')} className="font-bold underline underline-offset-4" style={{ color: C.copper }}>Log in</button></div>
            </div>
            <div className="order-1 lg:order-2 -mx-2 sm:mx-0 rd-art-in"><div className="lp-float"><RiderHeroArt className="w-full h-auto" /></div></div>
          </section>

          <section className="max-w-[1280px] mx-auto px-5 sm:px-8 lg:px-10 grid sm:grid-cols-3 gap-4">
            {perks.map(([Art, t, d], i) => (
              <div key={t} data-reveal className="rd-tile rounded-[24px] p-5 flex sm:block items-center gap-4" style={{ '--d': `${i * 0.1}s`, background: C.surface, boxShadow: '0 1px 0 rgba(11,43,38,0.04), 0 16px 34px -24px rgba(11,43,38,0.3)' }}>
                <Art className="w-24 sm:w-28 h-auto shrink-0" />
                <div className="min-w-0"><div className="sm:mt-4 text-[17px] font-bold" style={{ fontFamily: RIDER_DISPLAY, letterSpacing: '-0.02em', fontWeight: 600 }}>{t}</div><div className="mt-1 text-[14px] leading-relaxed" style={{ color: C.inkDim }}>{d}</div></div>
              </div>
            ))}
          </section>

          <section id="how" className="max-w-[1280px] mx-auto px-5 sm:px-8 lg:px-10 mt-16 scroll-mt-6">
            <div className="text-center" data-reveal><div className="text-[13px] font-bold uppercase tracking-[0.14em]" style={{ color: C.sage }}>How it works</div><h2 className="mt-2 text-[30px] sm:text-[38px] font-extrabold leading-tight" style={{ letterSpacing: '-0.04em', fontFamily: RIDER_DISPLAY }}>From sign-up to your <span style={{ color: C.amber }}>first delivery</span></h2></div>
            <div className="relative mt-10" data-reveal>
              <svg aria-hidden className="lp-line-grow hidden sm:block absolute left-[12%] right-[12%] top-[26px] w-[76%] h-4" preserveAspectRatio="none" viewBox="0 0 100 4"><path d="M0 2 H100" stroke={C.ink} strokeOpacity="0.25" strokeWidth="0.6" strokeDasharray="1.6 1.6" vectorEffect="non-scaling-stroke" /></svg>
              <ol className="relative grid sm:grid-cols-4 gap-6 sm:gap-4">
                {how.map(([t, d], i) => (
                  <li key={t} className="flex sm:flex-col sm:items-center sm:text-center gap-4 sm:gap-3">
                    <span className="w-[54px] h-[54px] rounded-full flex items-center justify-center shrink-0 text-[18px] font-extrabold" style={{ background: i === 3 ? C.amber : C.surface, color: C.ink, border: `2.5px solid ${C.ink}`, fontFamily: RIDER_DISPLAY, boxShadow: '0 4px 0 rgba(11,43,38,0.9)' }}>{i === 3 ? <Bike size={22} /> : i + 1}</span>
                    <span><span className="block text-[16px] font-bold" style={{ fontFamily: RIDER_DISPLAY, letterSpacing: '-0.02em', fontWeight: 600 }}>{t}</span><span className="block text-[13.5px] mt-0.5" style={{ color: C.inkDim }}>{d}</span></span>
                  </li>
                ))}
              </ol>
            </div>
          </section>

          <section id="need" className="max-w-[1280px] mx-auto px-5 sm:px-8 lg:px-10 mt-16 grid lg:grid-cols-[1.1fr_0.9fr] gap-6 items-center scroll-mt-6">
            <div data-reveal className="rounded-[28px] p-6 sm:p-8" style={{ background: C.mint }}>
              <h2 className="text-[26px] sm:text-[30px] font-extrabold leading-tight" style={{ letterSpacing: '-0.04em', fontFamily: RIDER_DISPLAY }}>What you'll need</h2>
              <ul className="mt-5 grid sm:grid-cols-2 gap-x-6 gap-y-3">
                {need.map((t) => <li key={t} className="flex items-start gap-2.5 text-[14.5px] font-medium"><span className="w-6 h-6 rounded-full flex items-center justify-center shrink-0" style={{ background: C.surface, border: `2px solid ${C.ink}` }}><Check size={13} strokeWidth={3} style={{ color: C.ink }} /></span>{t}</li>)}
              </ul>
              <div className="mt-6 rounded-2xl px-4 py-3 text-[13px] leading-relaxed flex gap-2.5" style={{ background: 'rgba(255,255,255,0.7)', color: C.inkDim }}><Lock size={15} className="shrink-0 mt-0.5" style={{ color: C.sage }} /> Your ID, selfie and bank details stay private. Businesses and customers never see them.</div>
            </div>
            <div data-reveal className="max-w-sm w-full mx-auto" style={{ '--d': '0.12s' }}>
              <div className="rd-pass-tilt"><RiderPass r={{ full_name: 'Chinedu Okafor', vehicle: 'bike', plate_number: 'UMH 482 QK', areas: ['Umuahia North', 'Umuahia South', 'Ikwuano'], status: 'approved' }} /></div>
              <div className="mt-4 text-center text-[13.5px]" style={{ color: C.inkDim }}>Once approved, your <strong style={{ color: C.ink }}>Xorla Rider Pass</strong> turns green.</div>
            </div>
          </section>

          <section className="max-w-[1280px] mx-auto px-5 sm:px-8 lg:px-10 mt-16">
            <div data-reveal className="relative overflow-hidden rounded-[28px] px-6 py-8 sm:px-10 sm:py-10 flex flex-col sm:flex-row sm:items-center gap-6" style={{ background: '#0B3B33', color: '#fff' }}>
              <span aria-hidden className="absolute -right-10 -bottom-16 w-64 h-64 rounded-full" style={{ background: 'rgba(31,217,196,0.18)' }} />
              <span aria-hidden className="absolute right-24 -top-10 w-24 h-24 rounded-full" style={{ background: 'rgba(255,176,32,0.25)' }} />
              <div className="relative flex-1">
                <h2 className="text-[28px] sm:text-[34px] font-extrabold leading-tight" style={{ letterSpacing: '-0.04em', fontFamily: RIDER_DISPLAY }}>Ready to <span style={{ color: '#FFB020' }}>ride?</span></h2>
                <p className="mt-2 text-[14.5px]" style={{ color: 'rgba(255,255,255,0.75)' }}>It's free to join. You must be 18 or older.</p>
              </div>
              <button onClick={() => go('signup')} className="relative h-13 px-8 py-3.5 rounded-full text-[16px] font-bold inline-flex items-center justify-center gap-2" style={{ background: '#FFB020', color: '#0B2B26' }}>Apply now <ArrowRight size={18} /></button>
            </div>
          </section>
        </main>
        {footer}
      </div>
    );
  }

  // ---------- Logged out: create an account or log in ----------
  if (!sess) {
    const t = authMode === 'signup' ? ['Create your rider account', 'Use an email you can open. You\'ll use it to log in and to hear from us.'] : authMode === 'login' ? ['Welcome back', 'Log in to continue your application or see where it is.'] : ['Forgot your password?', "Enter your email and we'll send you a link to set a new one."];
    return (
      <div style={page}>
        {header}
        <main className="max-w-6xl mx-auto px-5 pt-4 pb-10 grid lg:grid-cols-2 gap-8 items-center">
          <div className="hidden lg:block rounded-[32px] p-8" style={{ background: C.mint }}><RiderHeroArt className="w-full h-auto" /><div className="text-center text-[15px] font-semibold mt-2" style={{ color: C.inkDim }}>Deliver more. <span style={{ color: C.ink }}>Earn more.</span></div></div>
          <div className="w-full max-w-md mx-auto lg:mx-0">
          <button onClick={() => setView('home')} className="flex items-center gap-1 text-[13.5px] font-semibold mb-4" style={{ color: C.inkDim }}><ChevronLeft size={17} /> Back</button>
          <div className="lg:hidden -mx-2 mb-2"><RiderHeroArt className="w-full h-auto max-h-[210px]" /></div>
          <div className="rounded-[28px] p-6 sm:p-7" style={{ background: C.surface, boxShadow: '0 1px 0 rgba(11,43,38,0.04), 0 24px 50px -28px rgba(11,43,38,0.35)' }}>
            <h1 className="text-[26px] font-extrabold" style={{ letterSpacing: '-0.03em' }}>{t[0]}</h1>
            <p className="mt-1 text-[14px] leading-relaxed" style={{ color: C.inkDim }}>{t[1]}</p>
            <form className="mt-5 space-y-3" onSubmit={(e) => { e.preventDefault(); doAuth(); }}>
              <div>{label('Email')}<input type="email" autoComplete="email" value={auth.email} onChange={(e) => setAuth({ ...auth, email: e.target.value, error: '' })} placeholder="you@example.com" className={inputCls} style={field} /></div>
              {authMode !== 'forgot' && (
                <div>{label('Password', authMode === 'signup' ? `(at least ${PASSWORD_MIN_LENGTH} characters)` : '')}
                  <div className="relative"><input type={auth.show ? 'text' : 'password'} autoComplete={authMode === 'signup' ? 'new-password' : 'current-password'} value={auth.password} onChange={(e) => setAuth({ ...auth, password: e.target.value, error: '' })} className={`${inputCls} pr-12`} style={field} />
                    <button type="button" onClick={() => setAuth({ ...auth, show: !auth.show })} aria-label={auth.show ? 'Hide password' : 'Show password'} className="absolute right-2 top-1/2 -translate-y-1/2 w-9 h-9 flex items-center justify-center" style={{ color: C.inkFaint }}>{auth.show ? <EyeOff size={17} /> : <Eye size={17} />}</button></div>
                </div>
              )}
              {auth.error && <div className="rounded-xl px-3.5 py-2.5 text-[13px]" style={{ background: C.rustSoft, color: C.rust }}>{auth.error}</div>}
              {auth.note && <div className="rounded-xl px-3.5 py-2.5 text-[13px]" style={{ background: C.sageSoft, color: C.sage }}>{auth.note}</div>}
              <button type="submit" disabled={auth.busy} className="w-full h-12 rounded-xl text-[15px] font-bold flex items-center justify-center gap-2" style={{ background: C.copper, color: C.bg, opacity: auth.busy ? 0.7 : 1 }}>{auth.busy ? <Loader2 size={17} className="animate-spin" /> : null}{authMode === 'signup' ? 'Create account' : authMode === 'login' ? 'Log in' : 'Send the link'}</button>
            </form>
            <div className="mt-4 text-[13.5px] text-center" style={{ color: C.inkDim }}>
              {authMode === 'signup' ? <>Already have an account? <button onClick={() => setAuthMode('login')} className="font-semibold" style={{ color: C.copper }}>Log in</button></>
                : <><button onClick={() => setAuthMode('signup')} className="font-semibold" style={{ color: C.copper }}>Create an account</button>{authMode === 'login' && <> · <button onClick={() => setAuthMode('forgot')} className="font-semibold" style={{ color: C.inkDim }}>Forgot password?</button></>}</>}
            </div>
          </div>
          </div>
        </main>
      </div>
    );
  }

  if (me === undefined) return <div style={page} className="flex items-center justify-center"><Loader2 size={22} className="animate-spin" style={{ color: C.inkFaint }} /></div>;

  // ---------- This login belongs to a business: riders need their own account ----------
  if (me?.status === 'business_account') return (
    <div style={page}>
      {header}
      <main className="max-w-md mx-auto px-5 pt-4 pb-10">
        <RiderHeroArt className="w-full h-auto max-h-[220px]" />
        <div className="rounded-[28px] p-6 mt-2" style={{ background: C.surface, boxShadow: '0 1px 0 rgba(11,43,38,0.04), 0 24px 50px -28px rgba(11,43,38,0.35)' }}>
          <span className="w-12 h-12 rounded-2xl flex items-center justify-center" style={{ background: C.mint }}><Store size={22} style={{ color: C.sage }} /></span>
          <h1 className="mt-3 text-[24px] font-extrabold leading-tight" style={{ letterSpacing: '-0.03em' }}>This email is for a Xorla business</h1>
          <p className="mt-2 text-[14.5px] leading-relaxed" style={{ color: C.inkDim }}>To keep things safe, a rider account and a business account can't share a login. To ride with Xorla, create a rider account with a <strong style={{ color: C.ink }}>different email</strong>. Your business stays exactly as it is.</p>
          <button onClick={() => { logout(); setAuthMode('signup'); setView('auth'); }} className="mt-5 w-full h-12 rounded-full text-[15px] font-bold flex items-center justify-center gap-2" style={{ background: C.copper, color: '#fff' }}>Use a different email <ArrowRight size={17} /></button>
          <a href="/" className="mt-2.5 w-full h-12 rounded-full text-[14.5px] font-semibold flex items-center justify-center" style={{ color: C.ink, boxShadow: `inset 0 0 0 1.5px ${C.lineStrong}` }}>Go to my business</a>
        </div>
      </main>
    </div>
  );

  // ---------- Sent: where their application is ----------
  const status = me?.status || 'draft';
  // Approved: the work itself (jobs near you, the job in hand, earnings)
  if (status === 'approved') {
    return (
      <div style={page}>
        {header}
        <main className="max-w-xl mx-auto px-5 pt-5 pb-10"><RiderWork call={call} me={me} photo={photos.selfie_doc} token={sess?.access_token} /></main>
        {footer}
      </div>
    );
  }
  if (['submitted', 'approved', 'rejected', 'suspended'].includes(status)) {
    const first = String(me.full_name || '').split(' ')[0];
    const card = {
      submitted: [Clock, C.amber, `Thanks, ${first}. We're checking your application`, 'We check your ID and selfie, call your guarantor, and confirm your bank account. This usually takes 1 to 3 working days. We may call you on ' + (me.phone ? formatPhoneDisplay(me.phone) : 'your phone') + '.'],
      approved: [BadgeCheck, C.sage, `You're approved, ${first}!`, `Welcome to the Xorla rider network. Delivery jobs open city by city, starting with Umuahia and Aba. We'll message you on ${me.phone ? formatPhoneDisplay(me.phone) : 'your phone'} as soon as jobs open in ${(me.areas || []).slice(0, 2).join(' and ') || 'your area'}.`],
      rejected: [Ban, C.rust, "Your application wasn't approved", me.review_note || "We couldn't approve your application this time."],
      suspended: [Lock, C.rust, 'Your rider account is paused', me.review_note || 'The Xorla team has paused your account while they look into something.'],
    }[status];
    const Ic = card[0];
    const steps = [['Applied', !!me.submitted_at], ['Checked', status === 'approved'], ['Approved', status === 'approved'], ['Delivering', false]];
    return (
      <div style={page}>
        {header}
        <main className="max-w-xl mx-auto px-5 pt-6 pb-6">
          <RiderPass r={me} photo={photos.selfie_doc} />
          <div className="mt-4 rounded-[22px] p-5" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
            <span className="w-12 h-12 rounded-2xl flex items-center justify-center" style={{ background: `${card[1]}22` }}><Ic size={22} style={{ color: card[1] }} /></span>
            <h1 className="mt-3 text-[22px] font-extrabold leading-tight" style={{ letterSpacing: '-0.02em' }}>{card[2]}</h1>
            <p className="mt-2 text-[14.5px] leading-relaxed" style={{ color: C.inkDim }}>{card[3]}</p>
            {['submitted', 'approved'].includes(status) && (
              <div className="mt-5 flex items-center">
                {steps.map(([t, done], i) => (
                  <React.Fragment key={t}>
                    <div className="flex flex-col items-center gap-1.5 min-w-0">
                      <span className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: done ? C.sage : i === steps.findIndex((s) => !s[1]) ? C.copperSoft : C.chip, border: `1.5px solid ${done ? C.sage : i === steps.findIndex((s) => !s[1]) ? C.copper : C.line}` }}>{done ? <Check size={15} style={{ color: C.bg }} /> : <span className="text-[12px] font-bold" style={{ color: C.inkDim }}>{i + 1}</span>}</span>
                      <span className="text-[11.5px] font-semibold" style={{ color: done ? C.ink : C.inkFaint }}>{t}</span>
                    </div>
                    {i < steps.length - 1 && <span className="flex-1 h-[2px] mx-1.5 -mt-5 rounded-full" style={{ background: done && steps[i + 1][1] ? C.sage : C.line }} />}
                  </React.Fragment>
                ))}
              </div>
            )}
            {status === 'approved' && (
              <div className="mt-5 grid grid-cols-2 gap-2">
                <div className="rounded-xl px-3.5 py-3" style={{ background: C.field }}><div className="text-[11px] font-semibold uppercase tracking-wide" style={{ color: C.inkFaint }}>Paid into</div><div className="text-[13.5px] font-semibold mt-0.5 truncate">{me.bank_name} ····{String(me.account_number || '').slice(-4)}</div></div>
                <div className="rounded-xl px-3.5 py-3" style={{ background: C.field }}><div className="text-[11px] font-semibold uppercase tracking-wide" style={{ color: C.inkFaint }}>Your areas</div><div className="text-[13.5px] font-semibold mt-0.5 truncate">{(me.areas || []).length} chosen</div></div>
              </div>
            )}
            {['rejected', 'suspended'].includes(status) && RIDER_SUPPORT_WHATSAPP && <a href={`https://wa.me/${RIDER_SUPPORT_WHATSAPP}?text=${encodeURIComponent(`Hello Xorla, this is ${me.full_name} (rider, ${me.phone || ''}). About my rider account:`)}`} target="_blank" rel="noopener noreferrer" className="mt-4 h-11 rounded-xl text-[14px] font-semibold flex items-center justify-center gap-2" style={{ background: C.sage, color: C.bg }}><MessageCircle size={16} /> Message the Xorla team</a>}
          </div>
          {status === 'submitted' && (
            <div className="mt-3 rounded-2xl px-4 py-3.5 text-[13px] leading-relaxed flex gap-3" style={{ background: C.surface, border: `1px solid ${C.line}`, color: C.inkDim }}>
              <ShieldCheck size={17} className="shrink-0 mt-0.5" style={{ color: C.sage }} />
              <span>Tell your guarantor, <strong style={{ color: C.ink }}>{me.guarantor_name}</strong>, to expect a call from Xorla. Nobody from Xorla will ever ask you for money to approve you.</span>
            </div>
          )}
        </main>
        {footer}
      </div>
    );
  }

  // ---------- The application, step by step ----------
  const progress = RIDER_STEPS.map((_, i) => !stepProblem(i) && (i < 4 || !!me?.account_number));
  const lgas = NG_LGAS[f.state] || [];
  const motor = ['bike', 'tricycle', 'car', 'van'].includes(f.vehicle);
  const photoTile = (k, title, hint, Ic, capture) => (
    <div>
    {camBack === k && !photos[k] && !f[k] && (
      <div className="rounded-xl px-3.5 py-2.5 mb-2 text-[12.5px] leading-relaxed flex gap-2" style={{ background: C.copperSoft, color: C.ink }}>
        <AlertCircle size={15} className="shrink-0 mt-0.5" style={{ color: C.copper }} />
        <span>Your phone closed this page while the camera was open, so the photo didn't come through. Your details are safe. Try again, or take the photo with your phone's camera app first, then tap <strong>Choose a photo you've taken</strong>.</span>
      </div>
    )}
    <label onClick={(e) => { if (k === 'selfie_doc' && canLiveCamera() && !otherWays && upBusy !== k) { e.preventDefault(); setLiveCam(true); return; } markCamera(k); }} className="relative block rounded-2xl overflow-hidden cursor-pointer" style={{ background: C.field, border: `1.5px dashed ${photos[k] || f[k] ? C.sage : C.lineStrong}` }}>
      <input type="file" accept="image/*" {...(capture ? { capture } : {})} className="sr-only" onChange={(e) => { pickPhoto(k, e.target.files?.[0]); e.target.value = ''; }} aria-label={title} />
      {photos[k] ? (
        <div className="relative">
          <img src={photos[k]} alt="" className={`w-full ${k === 'selfie_doc' ? 'h-56' : 'h-44'} object-cover`} />
          <span className="absolute left-2 top-2 px-2 py-1 rounded-lg text-[11.5px] font-bold flex items-center gap-1" style={{ background: C.sage, color: C.bg }}><Check size={12} /> Added</span>
          <span className="absolute right-2 bottom-2 px-2.5 py-1.5 rounded-lg text-[12px] font-semibold" style={{ background: 'rgba(0,0,0,0.65)', color: '#fff' }}>Change</span>
        </div>
      ) : (
        <div className="px-4 py-6 flex flex-col items-center text-center">
          <span className="w-12 h-12 rounded-2xl flex items-center justify-center" style={{ background: C.copperSoft }}>{upBusy === k ? <Loader2 size={20} className="animate-spin" style={{ color: C.copper }} /> : <Ic size={21} style={{ color: C.copper }} />}</span>
          <span className="mt-2.5 text-[14.5px] font-semibold">{upBusy === k ? 'Uploading…' : title}</span>
          <span className="mt-1 text-[12.5px] leading-snug max-w-[260px]" style={{ color: C.inkFaint }}>{hint}</span>
        </div>
      )}
    </label>
    {capture && upBusy !== k && (k !== 'selfie_doc' || !canLiveCamera() || otherWays || camBack === k) && (
      <label className="mt-2 flex items-center justify-center gap-1.5 py-2 rounded-xl text-[12.5px] font-semibold cursor-pointer" style={{ color: C.sage }}>
        <input type="file" accept="image/*" className="sr-only" onChange={(e) => { pickPhoto(k, e.target.files?.[0]); e.target.value = ''; }} aria-label={`${title}: choose a photo`} />
        <ImagePlus size={14} /> Choose a photo you've taken
      </label>
    )}
    {k === 'selfie_doc' && canLiveCamera() && !otherWays && upBusy !== k && (
      <button type="button" onClick={() => setOtherWays(true)} className="mt-1.5 w-full py-1.5 text-[12px] font-medium" style={{ color: C.inkFaint }}>Camera not working?</button>
    )}
    {k === 'selfie_doc' && liveCam && <LiveSelfie onUse={(file) => pickPhoto('selfie_doc', file, true)} onClose={() => setLiveCam(false)} onFail={() => setOtherWays(true)} />}
    </div>
  );
  const banksMatch = (banks || []).filter((b) => bank.q.trim() && b.name.toLowerCase().includes(bank.q.trim().toLowerCase())).slice(0, 6);
  const stepsBody = [
    // 1. About you
    <div key="you" className="space-y-4">
      <div>{label('Full name', '(as on your ID)')}<input value={f.full_name || ''} onChange={(e) => set({ full_name: e.target.value })} autoComplete="name" placeholder="e.g. Chinedu Okafor" className={inputCls} style={field} /></div>
      <div className="grid sm:grid-cols-2 gap-4">
        <div>{label('Phone number')}<input type="tel" inputMode="tel" value={f.phone || ''} onChange={(e) => set({ phone: e.target.value })} autoComplete="tel" placeholder="0803 123 4567" className={inputCls} style={field} /></div>
        <div>{label('Date of birth')}<input type="date" value={f.date_of_birth || ''} max={new Date(Date.now() - 18 * 365.25 * 86400000).toISOString().slice(0, 10)} onChange={(e) => set({ date_of_birth: e.target.value })} className={inputCls} style={{ ...field, colorScheme: 'light' }} /></div>
      </div>
      <div>{label('Home address')}<textarea rows={2} value={f.home_address || ''} onChange={(e) => set({ home_address: e.target.value })} placeholder="House number, street, area" className={`${inputCls} resize-none`} style={field} /></div>
      <div className="grid grid-cols-2 gap-3">
        <div>{label('State')}<BrandSelect value={f.state || ''} onChange={(e) => set({ state: e.target.value, lga: '', areas: [] })} palette={RIDER_LIGHT} className="w-full rounded-xl px-4 py-3 text-[15px]" style={field} aria-label="State"><option value="">Choose</option>{NG_STATES.map((s) => <option key={s} value={s}>{s}</option>)}</BrandSelect></div>
        <div>{label('Local government')}<BrandSelect value={f.lga || ''} onChange={(e) => set({ lga: e.target.value, areas: (f.areas || []).length ? f.areas : [e.target.value] })} palette={RIDER_LIGHT} className="w-full rounded-xl px-4 py-3 text-[15px]" style={field} aria-label="Local government"><option value="">{f.state ? 'Choose' : 'Choose a state'}</option>{lgas.map((l) => <option key={l} value={l}>{l}</option>)}</BrandSelect></div>
      </div>
    </div>,
    // 2. Your ride and areas
    <div key="ride" className="space-y-5">
      <div>{label('How do you deliver?')}
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-2" role="radiogroup" aria-label="How do you deliver?">
          {RIDER_VEHICLES.map(([k, l, d, Ic]) => { const on = f.vehicle === k; return (
            <button key={k} type="button" role="radio" aria-checked={on} onClick={() => set({ vehicle: k })} className="rounded-2xl px-3.5 py-3 text-left transition-colors" style={{ background: on ? C.copperSoft : C.field, border: `1.5px solid ${on ? C.copper : C.lineStrong}` }}>
              <Ic size={20} style={{ color: on ? C.copper : C.inkDim }} />
              <span className="block mt-1.5 text-[14px] font-semibold">{l}</span><span className="block text-[11.5px]" style={{ color: C.inkFaint }}>{d}</span>
            </button>
          ); })}
        </div>
      </div>
      {motor && <div>{label('Plate number')}<input value={f.plate_number || ''} onChange={(e) => set({ plate_number: e.target.value.toUpperCase() })} placeholder="e.g. UMH 482 QK" className={`${inputCls} cx-mono tracking-wider`} style={field} /></div>}
      <div>
        <div className="flex items-baseline justify-between">{label('Where will you deliver?')}<span className="text-[12px]" style={{ color: C.inkFaint }}>{(f.areas || []).length}/12 chosen</span></div>
        {!f.state ? <div className="text-[13px]" style={{ color: C.inkFaint }}>Choose your state in step 1 first.</div> : (
          <div className="flex flex-wrap gap-2">
            {lgas.map((l) => { const on = (f.areas || []).includes(l); return (
              <button key={l} type="button" aria-pressed={on} onClick={() => set({ areas: on ? f.areas.filter((x) => x !== l) : (f.areas || []).length >= 12 ? f.areas : [...(f.areas || []), l] })} className="px-3 py-2 rounded-full text-[13px] font-semibold flex items-center gap-1.5" style={chip(on)}>{on && <Check size={13} />}{l}</button>
            ); })}
          </div>
        )}
        <div className="text-[12px] mt-2" style={{ color: C.inkFaint }}>You'll only see jobs in these areas. You can change them later.</div>
      </div>
    </div>,
    // 3. ID and selfie
    <div key="id" className="space-y-5">
      <div>{label('Your ID')}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2" role="radiogroup" aria-label="Your ID">
          {RIDER_ID_TYPES.map(([k, l, d]) => { const on = f.id_type === k; return (
            <button key={k} type="button" role="radio" aria-checked={on} onClick={() => set({ id_type: k })} className="rounded-xl px-3 py-2.5 text-left" style={{ background: on ? C.copperSoft : C.field, border: `1.5px solid ${on ? C.copper : C.lineStrong}` }}>
              <span className="block text-[13.5px] font-semibold">{l}</span>{d && <span className="block text-[11px]" style={{ color: C.inkFaint }}>{d}</span>}
            </button>
          ); })}
        </div>
      </div>
      {f.id_type && <div>{label(f.id_type === 'nin' ? 'NIN' : 'ID number', f.id_type === 'nin' ? '(11 digits)' : '')}<input value={f.id_number || ''} inputMode={f.id_type === 'nin' ? 'numeric' : 'text'} onChange={(e) => set({ id_number: e.target.value })} placeholder={f.id_type === 'nin' ? '12345678901' : 'As printed on the ID'} className={`${inputCls} cx-mono tracking-wider`} style={field} /></div>}
      <div className="grid sm:grid-cols-2 gap-3">
        {photoTile('id_doc', 'Photo of your ID', 'The front, flat on a table. All four corners and every word clear.', Contact, 'environment')}
        {photoTile('selfie_doc', 'Take a selfie', 'Face the light. No cap, no sunglasses, nobody else in the photo.', ScanFace, 'user')}
      </div>
      <div className="rounded-xl px-3.5 py-3 text-[12.5px] leading-relaxed flex gap-2.5" style={{ background: C.field, color: C.inkDim }}><Lock size={15} className="shrink-0 mt-0.5" style={{ color: C.sage }} /> We check that your face matches your ID. Only the Xorla team can see these photos.</div>
    </div>,
    // 4. Guarantor
    <div key="guarantor" className="space-y-4">
      <div className="rounded-xl px-3.5 py-3 text-[13px] leading-relaxed" style={{ background: C.copperSoft, color: C.ink }}>A guarantor is someone who knows you well and will stand for you. <span style={{ color: C.inkDim }}>We'll call them to confirm. Not a friend you just met, and not yourself.</span></div>
      <div>{label('Their full name')}<input value={f.guarantor_name || ''} onChange={(e) => set({ guarantor_name: e.target.value })} className={inputCls} style={field} /></div>
      <div>{label('Their phone number')}<input type="tel" inputMode="tel" value={f.guarantor_phone || ''} onChange={(e) => set({ guarantor_phone: e.target.value })} placeholder="0803 123 4567" className={inputCls} style={field} /></div>
      <div>{label('How do you know them?')}
        <div className="flex flex-wrap gap-2">{RIDER_RELATIONS.map((x) => <button key={x} type="button" aria-pressed={f.guarantor_relationship === x} onClick={() => set({ guarantor_relationship: x })} className="px-3 py-2 rounded-full text-[13px] font-semibold" style={chip(f.guarantor_relationship === x)}>{x}</button>)}</div>
      </div>
      <div>{label('Their address')}<textarea rows={2} value={f.guarantor_address || ''} onChange={(e) => set({ guarantor_address: e.target.value })} className={`${inputCls} resize-none`} style={field} /></div>
    </div>,
    // 5. Bank, review and send
    <div key="bank" className="space-y-5">
      <div>
        <div className="text-[15px] font-bold">Where we pay you</div>
        <div className="text-[13px] mt-0.5 mb-3" style={{ color: C.inkDim }}>Use an account in your own name. We check the name with your bank.</div>
        {me?.account_number ? (
          <div className="rounded-2xl p-4 flex items-center gap-3" style={{ background: C.sageSoft, border: '1px solid rgba(31,217,196,0.35)' }}>
            <span className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0" style={{ background: C.sage }}><Landmark size={18} style={{ color: C.bg }} /></span>
            <span className="flex-1 min-w-0"><span className="block text-[15px] font-bold break-words">{me.account_name}</span><span className="block text-[12.5px]" style={{ color: C.inkDim }}>{me.bank_name} · <span className="cx-mono">{me.account_number}</span></span>
              <span className="flex items-center gap-1 mt-0.5 text-[11.5px] font-semibold" style={{ color: me.bank_verified ? C.sage : C.copper }}>{me.bank_verified ? <><BadgeCheck size={12} /> Name confirmed by your bank</> : 'Test mode: name not checked'}</span></span>
            <button onClick={() => setMe({ ...me, account_number: null })} className="shrink-0 text-[12.5px] font-semibold" style={{ color: C.copper }}>Change</button>
          </div>
        ) : (
          <div className="space-y-2.5">
            {bank.code ? (
              <button type="button" onClick={() => setBank({ ...bank, code: '', name: '', q: '' })} className="w-full rounded-xl px-4 py-3 text-[15px] flex items-center justify-between text-left" style={field}><span className="font-semibold">{bank.name}</span><span className="text-[12.5px] font-semibold" style={{ color: C.copper }}>Change</span></button>
            ) : (
              <div>
                <div className="relative"><Search size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2" style={{ color: C.inkFaint }} /><input value={bank.q} onChange={(e) => setBank({ ...bank, q: e.target.value, error: '' })} placeholder={banks === null ? 'Loading banks…' : 'Type your bank, e.g. Opay, GTBank, Moniepoint'} className={`${inputCls} pl-10`} style={field} /></div>
                {banksMatch.length > 0 && <div className="mt-1.5 rounded-xl overflow-hidden" style={{ border: `1px solid ${C.lineStrong}` }}>{banksMatch.map((b) => <button key={b.code} type="button" onClick={() => setBank({ ...bank, code: b.code, name: b.name, q: '' })} className="w-full px-4 py-2.5 text-left text-[14px]" style={{ background: C.surfaceRaised, borderBottom: `1px solid ${C.line}` }}>{b.name}</button>)}</div>}
              </div>
            )}
            <input inputMode="numeric" maxLength={10} value={bank.number} onChange={(e) => setBank({ ...bank, number: e.target.value.replace(/\D/g, '').slice(0, 10), error: '' })} placeholder="10-digit account number" className={`${inputCls} cx-mono tracking-wider`} style={field} />
            {bank.error && <div className="rounded-xl px-3.5 py-2.5 text-[13px]" style={{ background: C.rustSoft, color: C.rust }}>{bank.error}</div>}
            <button type="button" onClick={checkBank} disabled={bank.busy} className="w-full h-12 rounded-xl text-[14.5px] font-bold flex items-center justify-center gap-2" style={{ background: C.sage, color: C.bg, opacity: bank.busy ? 0.7 : 1 }}>{bank.busy ? <><Loader2 size={16} className="animate-spin" /> Checking with your bank…</> : 'Check and save account'}</button>
          </div>
        )}
      </div>
      <div className="rounded-2xl overflow-hidden" style={{ border: `1px solid ${C.line}` }}>
        {[[0, 'You', [f.full_name, f.phone && formatPhoneDisplay(f.phone), [f.lga, f.state].filter(Boolean).join(', ')]], [1, 'Your ride', [(RIDER_VEHICLES.find(([k]) => k === f.vehicle) || [])[1], f.plate_number, `${(f.areas || []).length} area${(f.areas || []).length !== 1 ? 's' : ''}`]], [2, 'ID & selfie', [(RIDER_ID_TYPES.find(([k]) => k === f.id_type) || [])[1], f.id_doc ? 'ID photo added' : '', f.selfie_doc ? 'selfie added' : '']], [3, 'Guarantor', [f.guarantor_name, f.guarantor_relationship]]].map(([i, t, bits]) => (
          <button key={t} type="button" onClick={() => setStep(i)} className="w-full flex items-center gap-3 px-4 py-3 text-left" style={{ background: C.field, borderBottom: `1px solid ${C.line}` }}>
            <span className="w-6 h-6 rounded-full flex items-center justify-center shrink-0" style={{ background: progress[i] ? C.sage : C.rustSoft }}>{progress[i] ? <Check size={13} style={{ color: C.bg }} /> : <X size={13} style={{ color: C.rust }} />}</span>
            <span className="flex-1 min-w-0"><span className="block text-[13.5px] font-semibold">{t}</span><span className="block text-[12px] truncate" style={{ color: C.inkFaint }}>{bits.filter(Boolean).join(' · ') || 'Not filled in'}</span></span>
            <span className="text-[12.5px] font-semibold" style={{ color: C.copper }}>Edit</span>
          </button>
        ))}
      </div>
      <label className="flex items-start gap-3 cursor-pointer rounded-2xl p-4" style={{ background: C.field, border: `1px solid ${agree ? C.copper : C.line}` }}>
        <input type="checkbox" checked={agree} onChange={(e) => { setAgree(e.target.checked); setErr(''); }} className="mt-1 w-5 h-5 accent-[#FFB020] shrink-0" />
        <span className="text-[13px] leading-relaxed" style={{ color: C.inkDim }}><strong style={{ color: C.ink }}>My details are true.</strong> I'll treat every delivery with care, never ask a customer for extra money, and I understand Xorla can pause riders after complaints. I agree that Xorla may check my ID with NIMC and compare my selfie with my ID photo. I agree to the <a href="/terms" target="_blank" rel="noopener noreferrer" style={{ color: C.copper }}>terms</a>.</span>
      </label>
    </div>,
  ];
  return (
    <div style={page}>
      {header}
      <main className="max-w-5xl mx-auto px-5 pt-4 pb-28 grid grid-cols-1 lg:grid-cols-[340px_minmax(0,1fr)] gap-6 items-start" ref={topRef}>
        <aside className="lg:sticky lg:top-6 space-y-3 min-w-0">
          <div className="hidden lg:block"><RiderPass r={{ ...me, ...f, status }} photo={photos.selfie_doc} /></div>
          <div className="lg:hidden"><RiderPass r={{ ...me, ...f, status }} photo={photos.selfie_doc} compact /></div>
          <div className="hidden lg:block rounded-2xl p-4 text-[12.5px] leading-relaxed" style={{ background: C.surface, border: `1px solid ${C.line}`, color: C.inkDim }}><div className="flex items-center gap-2 font-semibold mb-1" style={{ color: C.ink }}><ShieldCheck size={15} style={{ color: C.sage }} /> Private and safe</div>Your details are saved as you go, so you can stop and come back. Only the Xorla team sees your ID, selfie and bank details.</div>
        </aside>
        <section className="min-w-0">
          {status === 'needs_fix' && me?.review_note && (
            <div className="mb-4 rounded-2xl p-4 flex gap-3" style={{ background: C.rustSoft, border: '1px solid rgba(226,98,75,0.35)' }}>
              <Pencil size={18} className="shrink-0 mt-0.5" style={{ color: C.rust }} />
              <span><span className="block text-[14.5px] font-bold">Please fix this, then send it again</span><span className="block text-[13.5px] mt-0.5 leading-relaxed" style={{ color: C.ink }}>{me.review_note}</span></span>
            </div>
          )}
          <div className="flex items-center justify-between mb-3">
            <div className="text-[13px] font-semibold" style={{ color: C.inkDim }}>Step {step + 1} of {RIDER_STEPS.length}</div>
            {saved && <div className="text-[12.5px] font-semibold flex items-center gap-1" style={{ color: C.sage }}><Check size={13} /> {saved}</div>}
          </div>
          <div className="flex gap-1.5 mb-5" role="tablist" aria-label="Application steps">
            {RIDER_STEPS.map(([k, l], i) => (
              <button key={k} role="tab" aria-selected={step === i} onClick={() => (i < step || progress.slice(0, i).every(Boolean)) && setStep(i)} className="flex-1 min-w-0 text-left">
                <span className="block h-1.5 rounded-full" style={{ background: i === step ? C.copper : progress[i] ? C.sage : C.track }} />
                <span className="hidden sm:block mt-1.5 text-[11.5px] font-semibold truncate" style={{ color: i === step ? C.ink : C.inkFaint }}>{l}</span>
              </button>
            ))}
          </div>
          <div className="rounded-[24px] p-5 sm:p-6" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
            <h1 className="text-[22px] font-extrabold mb-1" style={{ letterSpacing: '-0.02em' }}>{['About you', 'Your ride and areas', 'Your ID and a selfie', 'Your guarantor', 'Bank account, then send'][step]}</h1>
            <p className="text-[13.5px] mb-5" style={{ color: C.inkDim }}>{['Use your real details, exactly as on your ID.', 'Tell us what you ride and where you can deliver.', 'This keeps customers and riders safe.', 'Someone who knows you well and will stand for you.', 'Check everything, then send it to the Xorla team.'][step]}</p>
            {stepsBody[step]}
            {err && <div className="mt-4 rounded-xl px-3.5 py-2.5 text-[13px]" style={{ background: C.rustSoft, color: C.rust }}>{err}</div>}
          </div>
        </section>
      </main>
      <div className="fixed left-0 right-0 bottom-0 z-30" style={{ background: 'rgba(255,255,255,0.94)', backdropFilter: 'blur(10px)', borderTop: `1px solid ${C.line}`, paddingBottom: 'env(safe-area-inset-bottom)' }}>
        <div className="max-w-5xl mx-auto px-5 py-3 flex gap-2.5 lg:pl-[calc(340px+44px)]">
          {step > 0 && <button onClick={() => saveStep(step - 1)} disabled={busy} className="h-12 px-5 rounded-xl text-[14.5px] font-semibold" style={{ color: C.ink, border: `1px solid ${C.lineStrong}` }}>Back</button>}
          {step < 4
            ? <button onClick={() => saveStep(step + 1)} disabled={busy || !!upBusy} className="flex-1 h-12 rounded-xl text-[15px] font-bold flex items-center justify-center gap-2" style={{ background: C.copper, color: C.bg, opacity: busy || upBusy ? 0.7 : 1 }}>{busy ? <Loader2 size={17} className="animate-spin" /> : null}Save and continue <ArrowRight size={17} /></button>
            : <button onClick={submit} disabled={busy} className="flex-1 h-12 rounded-xl text-[15px] font-bold flex items-center justify-center gap-2" style={{ background: progress.every(Boolean) && agree ? C.copper : 'rgba(255,176,32,0.35)', color: C.bg }}>{busy ? <Loader2 size={17} className="animate-spin" /> : <Check size={17} />}{status === 'needs_fix' ? 'Send it again' : 'Send my application'}</button>}
        </div>
      </div>
    </div>
  );
}

// ============ Founder / support: checking rider applications ============
const RIDER_ADMIN_STATUS = {
  submitted: ['To check', C.copper], needs_fix: ['Waiting for a fix', C.inkDim], approved: ['Approved', C.sage], suspended: ['Paused', C.rust], rejected: ['Turned down', C.rust], draft: ['Still filling in', C.inkFaint],
};
const RIDER_CHECKS = [
  ['face', 'Face matches the ID photo', 'Same person, clear photo, not a photo of a photo.'],
  ['id', 'ID number checked', 'The number is real and the name on it matches.'],
  ['guarantor', 'Guarantor called', 'They know the rider and agreed to stand for them.'],
  ['bank', 'Bank name matches', 'The name the bank gave matches the rider.'],
];
const RIDER_FIX_SUGGEST = [
  'Your selfie is not clear. Please take it again in good light, facing the camera, with no cap or glasses.',
  'Your ID photo is not clear. Please take it again, flat on a table, with all four corners showing.',
  "We couldn't reach your guarantor. Please check their phone number, or add someone else.",
  "The name on your bank account doesn't match your name. Please use an account in your own name.",
  'Your plate number looks wrong. Please check it.',
];
const riderAgo = (t) => { if (!t) return ''; const m = Math.round((Date.now() - new Date(t).getTime()) / 60000); return m < 60 ? `${Math.max(1, m)} min ago` : m < 1440 ? `${Math.round(m / 60)}h ago` : `${Math.round(m / 1440)} day${Math.round(m / 1440) !== 1 ? 's' : ''} ago`; };
const namesClose = (a, b) => { const w = (s) => String(s || '').toLowerCase().split(/[^a-z]+/).filter((x) => x.length >= 3); const x = w(a), y = w(b); if (!x.length || !y.length) return 0; return x.filter((t) => y.includes(t)).length / Math.min(x.length, y.length); };

function RiderAdmin({ call, token, isFounder = true, initialId = null, onCounts }) {
  const [counts, setCounts] = useState(null);
  const [tab, setTab] = useState('submitted');
  const [q, setQ] = useState('');
  const [list, setList] = useState(null);
  const [thumbs, setThumbs] = useState({});
  const [open, setOpen] = useState(null);
  const [pics, setPics] = useState({});
  const [act, setAct] = useState({ mode: '', note: '', busy: false, error: '' });
  const [zoom, setZoom] = useState('');
  const [nin, setNin] = useState({ busy: false, error: '' });
  const field = { background: C.surfaceRaised, border: `1px solid ${C.line}`, color: C.ink };
  // Ask NIMC (through Dojah, in the billing function) whether the NIN is real, whose it is, and whether the selfie matches its photo
  const checkNin = async () => {
    if (!open) return;
    setNin({ busy: true, error: '' });
    try { await riderBilling(token(), 'admin_rider_nin', { rider_id: open.id }); const r = await call('admin_rider', { p_id: open.id }); setOpen(r); setNin({ busy: false, error: '' }); }
    catch (e) { setNin({ busy: false, error: e.message }); }
  };
  const loadCounts = useCallback(() => call('admin_rider_counts', {}).then((c) => { setCounts(c); onCounts && onCounts(c); }).catch(() => {}), [call, onCounts]);
  const loadList = useCallback(async () => { try { setList(await call('admin_riders', { p_status: tab, p_search: q || null })); } catch (e) { setList([]); } }, [call, tab, q]);
  useEffect(() => { loadList(); }, [tab]);
  useEffect(() => { const t = setTimeout(loadList, 300); return () => clearTimeout(t); }, [q]);
  useEffect(() => { loadCounts(); if (initialId) show(initialId); }, []);
  // Stay up to date on its own while on screen
  useEffect(() => {
    const tick = () => { if (document.visibilityState === 'visible') { loadCounts(); loadList(); } };
    const t = setInterval(tick, 30000); document.addEventListener('visibilitychange', tick);
    return () => { clearInterval(t); document.removeEventListener('visibilitychange', tick); };
  }, [loadCounts, loadList]);
  // Selfie thumbnails for the list
  useEffect(() => {
    (list || []).forEach((r) => { if (r.selfie_doc && !thumbs[r.id]) vaultFileUrl(token(), 'rider-docs', r.selfie_doc).then((u) => setThumbs((x) => ({ ...x, [r.id]: u }))).catch(() => {}); });
  }, [list]);
  const show = async (id) => {
    setAct({ mode: '', note: '', busy: false, error: '' }); setPics({}); setNin({ busy: false, error: '' });
    try {
      const r = await call('admin_rider', { p_id: id }); setOpen(r);
      ['id_doc', 'selfie_doc'].forEach((k) => { if (r[k]) vaultFileUrl(token(), 'rider-docs', r[k]).then((u) => setPics((p) => ({ ...p, [k]: u }))).catch(() => {}); });
    } catch (e) { brandAlert(e.message); }
  };
  const tick = async (k, v) => {
    setOpen((r) => ({ ...r, checks: { ...(r.checks || {}), [k]: v } }));
    try { const r = await call('admin_rider_review', { p_id: open.id, p_action: 'checks', p_checks: { [k]: v } }); setOpen(r); } catch (e) { brandAlert(e.message); }
  };
  const wa = (r, kind, note) => {
    const first = String(r.full_name || '').split(' ')[0];
    const text = kind === 'approve' ? `Hello ${first}, this is the Xorla team. Good news: your rider application is approved! Your Xorla rider pass is now verified. We'll message you as soon as delivery jobs open in your area. Log in any time at ${window.location.origin}/ride`
      : kind === 'fix' ? `Hello ${first}, this is the Xorla team. We checked your rider application and need one thing fixed: ${note} Please log in at ${window.location.origin}/ride to fix it and send it again.`
      : kind === 'reject' ? `Hello ${first}, this is the Xorla team. Thank you for applying to ride with Xorla. We're sorry, we can't approve your application: ${note}`
      : kind === 'suspend' ? `Hello ${first}, this is the Xorla team. Your rider account is paused while we look into something: ${note} We'll be in touch.`
      : `Hello ${first}, this is the Xorla team. Your rider account is active again.`;
    return `https://wa.me/${toWhatsAppNumber(r.phone)}?text=${encodeURIComponent(text)}`;
  };
  const decide = async (mode) => {
    const note = act.note.trim();
    if (['fix', 'reject', 'suspend'].includes(mode) && !note) { setAct((a) => ({ ...a, error: mode === 'fix' ? 'Say what they need to fix.' : 'Give a short reason.' })); return; }
    setAct((a) => ({ ...a, busy: true, error: '' }));
    try {
      const r = await call('admin_rider_review', { p_id: open.id, p_action: mode, p_note: note || null });
      setOpen(r); setAct({ mode: '', note: '', busy: false, error: '' }); loadList(); loadCounts();
      if (r.phone) offerWhatsApp(r, mode, note);
    } catch (e) { setAct((a) => ({ ...a, busy: false, error: e.message })); }
  };
  const offerWhatsApp = async (r, mode, note) => {
    const ok = await brandConfirm(`Send ${String(r.full_name).split(' ')[0]} a WhatsApp message to let them know?`, { title: mode === 'approve' ? 'Approved' : mode === 'fix' ? 'Sent back for a fix' : mode === 'reject' ? 'Turned down' : mode === 'suspend' ? 'Paused' : 'Active again', confirm: 'Open WhatsApp', cancel: 'Not now' });
    if (ok) window.open(wa(r, mode, note), '_blank');
  };

  // ---------- One application ----------
  if (open) {
    const r = open; const checks = r.checks || {}; const allChecked = RIDER_CHECKS.every(([k]) => checks[k]);
    const st = RIDER_ADMIN_STATUS[r.status] || ['', C.inkDim];
    const veh = RIDER_VEHICLES.find(([k]) => k === r.vehicle);
    const idType = (RIDER_ID_TYPES.find(([k]) => k === r.id_type) || [])[1];
    const bankClose = namesClose(r.account_name, r.full_name);
    const row = (l, v, mono) => <div className="flex items-start justify-between gap-4 py-2" style={{ borderBottom: `1px solid ${C.line}` }}><span className="text-[12.5px] shrink-0" style={{ color: C.inkFaint }}>{l}</span><span className={`text-[13.5px] text-right font-medium break-words min-w-0 ${mono ? 'cx-mono' : ''}`}>{v || '—'}</span></div>;
    const canDecide = r.status === 'submitted';
    return (
      <div className="max-w-5xl">
        <button onClick={() => { setOpen(null); loadList(); }} className="flex items-center gap-1 text-[13px] font-semibold mb-4" style={{ color: C.inkDim }}><ChevronLeft size={16} /> All riders</button>
        <div className="flex flex-wrap items-center gap-3 mb-5">
          <div className="w-14 h-14 rounded-2xl overflow-hidden shrink-0 flex items-center justify-center" style={{ background: C.surfaceRaised }}>{pics.selfie_doc ? <img src={pics.selfie_doc} alt="" className="w-full h-full object-cover" /> : <span className="text-[18px] font-bold" style={{ color: C.inkDim }}>{riderInitials(r.full_name)}</span>}</div>
          <div className="min-w-0 flex-1">
            <div className="text-[22px] font-extrabold leading-tight" style={{ letterSpacing: '-0.02em' }}>{r.full_name || 'No name yet'}</div>
            <div className="text-[13px] mt-0.5" style={{ color: C.inkDim }}>{veh ? veh[1] : '—'}{r.plate_number ? ` · ${r.plate_number}` : ''} · {[r.lga, r.state].filter(Boolean).join(', ')}{r.age ? ` · ${r.age} years old` : ''}</div>
          </div>
          <span className="px-3 py-1.5 rounded-full text-[12px] font-bold" style={{ background: `${st[1]}22`, color: st[1] }}>{st[0]}</span>
        </div>
        <div className="grid lg:grid-cols-[1.15fr_0.85fr] gap-4 items-start">
          <div className="space-y-4 min-w-0">
            {/* Side by side: does the face match the ID? */}
            <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
              <div className="text-[14px] font-semibold mb-3 flex items-center gap-2"><ScanFace size={16} style={{ color: C.copper }} /> Does the face match the ID?</div>
              <div className="grid grid-cols-2 gap-3">
                {[['selfie_doc', 'Selfie'], ['id_doc', `ID${idType ? ` · ${idType}` : ''}`]].map(([k, l]) => (
                  <button key={k} type="button" onClick={() => pics[k] && setZoom(pics[k])} className="rounded-xl overflow-hidden text-left" style={{ background: C.surfaceRaised, border: `1px solid ${C.line}` }}>
                    <div className="aspect-[4/5] flex items-center justify-center">{pics[k] ? <img src={pics[k]} alt={l} className={`w-full h-full ${k === 'id_doc' ? 'object-contain' : 'object-cover'}`} /> : r[k] ? <Loader2 size={18} className="animate-spin" style={{ color: C.inkFaint }} /> : <span className="text-[12px]" style={{ color: C.inkFaint }}>Not added</span>}</div>
                    <div className="px-3 py-2 text-[12px] font-semibold flex items-center justify-between gap-2" style={{ color: C.inkDim }}>
                      <span className="flex items-center gap-1.5 min-w-0">{l}{k === 'selfie_doc' && r.selfie_doc && (/selfie-live-/.test(r.selfie_doc)
                        ? <span className="px-1.5 py-0.5 rounded-md text-[10.5px] font-bold" style={{ background: C.sageSoft, color: C.sage }}>Live</span>
                        : <span className="px-1.5 py-0.5 rounded-md text-[10.5px] font-bold" style={{ background: C.copperSoft, color: C.copper }}>Uploaded</span>)}</span>
                      {pics[k] && <span style={{ color: C.copper }}>Open</span>}
                    </div>
                  </button>
                ))}
              </div>
            </div>
            {/* NIN: confirmed with NIMC, and the selfie compared with the NIN photo */}
            <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
              <div className="text-[14px] font-semibold mb-1 flex items-center gap-2"><BadgeCheck size={16} style={{ color: C.copper }} /> NIN check with NIMC</div>
              {r.id_type !== 'nin' ? (
                <div className="text-[12.5px] leading-relaxed" style={{ color: C.inkDim }}>This rider used {idType ? `a ${idType.toLowerCase()}` : 'another ID'}. Only a NIN can be checked automatically, so check the ID photo by eye. You can ask them for their NIN instead.</div>
              ) : (() => {
                const k = r.nin_check; const used = r.nin_checks_used || 0;
                const tone = !k ? C.inkDim : k.status === 'match' ? C.sage : k.status === 'mismatch' ? C.copper : C.rust;
                const yes = (ok, text) => <span style={{ color: ok === false ? C.rust : ok ? C.sage : C.inkDim }}>{ok === false ? <X size={13} className="inline -mt-0.5 mr-1" /> : ok ? <Check size={13} className="inline -mt-0.5 mr-1" /> : null}{text}</span>;
                return (
                  <>
                    {!k && <div className="text-[12.5px] leading-relaxed mb-3" style={{ color: C.inkDim }}>Confirms the NIN is real, shows the name and date of birth NIMC holds, and compares the selfie with the photo on the NIN. Each check is paid from the Dojah wallet.</div>}
                    {k && (
                      <div className="mt-2 mb-3">
                        <div className="rounded-xl px-3.5 py-2.5 text-[13px] font-semibold flex items-start gap-2" style={{ background: `${tone === C.sage ? C.sageSoft : tone === C.copper ? C.copperSoft : C.rustSoft}`, color: tone }}>
                          {k.status === 'match' ? <ShieldCheck size={16} className="shrink-0 mt-0.5" /> : <AlertCircle size={16} className="shrink-0 mt-0.5" />}
                          <span>{k.status === 'match' ? 'NIN confirmed and the face matches' : k.status === 'mismatch' ? 'NIN found, but something doesn\'t match' : 'NIMC has no record of this NIN'}</span>
                        </div>
                        {k.status !== 'not_found' && <>
                          {row('Name on the NIN', yes(k.name_match === 'full' ? true : k.name_match === 'none' ? false : null, `${k.nimc_name || '—'}${k.name_match === 'partial' ? ' (part match)' : ''}`))}
                          {row('Date of birth on the NIN', yes(k.dob_match, k.nimc_dob ? new Date(k.nimc_dob + 'T12:00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : '—'))}
                          <div className="py-2.5" style={{ borderBottom: `1px solid ${C.line}` }}>
                            <div className="flex items-center justify-between text-[12.5px] mb-1.5"><span style={{ color: C.inkFaint }}>Selfie vs NIN photo{k.live === false ? ' (uploaded photo)' : ''}</span><span className="text-[13.5px] font-bold" style={{ color: k.face_match ? C.sage : C.rust }}>{k.face_score != null ? `${k.face_score}%` : '—'} {k.face_match ? 'match' : 'no match'}</span></div>
                            <div className="h-1.5 rounded-full overflow-hidden" style={{ background: C.surfaceRaised }}><div className="h-full rounded-full" style={{ width: `${Math.max(2, Math.min(100, k.face_score || 0))}%`, background: k.face_match ? C.sageFill : C.rustFill }} /></div>
                          </div>
                        </>}
                        <div className="text-[11.5px] mt-2" style={{ color: C.inkFaint }}>Checked {riderAgo(k.at)}{k.by ? ` by ${k.by}` : ''}</div>
                      </div>
                    )}
                    {nin.error && <div className="rounded-xl px-3 py-2 mb-2.5 text-[12.5px]" style={{ background: C.rustSoft, color: C.rust }}>{nin.error}</div>}
                    <button onClick={checkNin} disabled={nin.busy} className="w-full h-10 rounded-xl text-[13px] font-semibold flex items-center justify-center gap-1.5" style={k ? { border: `1px solid ${C.lineStrong}`, color: C.ink } : { background: C.copperFill, color: C.onAccent }}>
                      {nin.busy ? <><Loader2 size={15} className="animate-spin" /> Checking with NIMC…</> : k ? `Check again (${used} of 3 used)` : <><BadgeCheck size={15} /> Check NIN</>}
                    </button>
                  </>
                );
              })()}
            </div>
            <div className="rounded-2xl px-4 py-2" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
              <div className="text-[14px] font-semibold pt-2 pb-1">Details</div>
              {row('Phone', r.phone ? formatPhoneDisplay(r.phone) : '')}
              {row('Email', r.email)}
              {row('Date of birth', r.date_of_birth ? `${new Date(r.date_of_birth + 'T12:00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })} (${r.age})` : '')}
              {row('Home address', r.home_address)}
              {row(idType || 'ID', r.id_number, true)}
              {row('Delivers in', (r.areas || []).join(', '))}
              {row('Applied', r.submitted_at ? `${new Date(r.submitted_at).toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit', hour12: true })} · ${riderAgo(r.submitted_at)}` : 'Not sent yet')}
            </div>
            <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
              <div className="text-[14px] font-semibold mb-2 flex items-center gap-2"><Users size={16} style={{ color: C.copper }} /> Guarantor</div>
              <div className="text-[15px] font-semibold">{r.guarantor_name || '—'}</div>
              <div className="text-[12.5px] mt-0.5" style={{ color: C.inkDim }}>{r.guarantor_relationship}{r.guarantor_address ? ` · ${r.guarantor_address}` : ''}</div>
              {r.guarantor_phone && <div className="flex gap-2 mt-3">
                <a href={`tel:${r.guarantor_phone}`} className="flex-1 h-10 rounded-xl text-[13px] font-semibold flex items-center justify-center gap-1.5" style={{ background: C.sageFill, color: C.onAccent }}><Phone size={14} /> Call {formatPhoneDisplay(r.guarantor_phone)}</a>
                <a href={`https://wa.me/${toWhatsAppNumber(r.guarantor_phone)}?text=${encodeURIComponent(`Hello ${String(r.guarantor_name || '').split(' ')[0]}, this is the Xorla team. ${r.full_name} has applied to deliver for businesses with Xorla, and named you as their guarantor. Do you know them, and do you agree to stand for them?`)}`} target="_blank" rel="noopener noreferrer" className="h-10 px-3.5 rounded-xl text-[13px] font-semibold flex items-center justify-center gap-1.5" style={{ color: C.sage, border: '1px solid rgba(31,217,196,0.35)' }}><MessageCircle size={14} /> WhatsApp</a>
              </div>}
            </div>
            <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
              <div className="text-[14px] font-semibold mb-2 flex items-center gap-2"><Landmark size={16} style={{ color: C.copper }} /> Bank account</div>
              {r.account_number ? <>
                <div className="text-[15px] font-semibold break-words">{r.account_name}</div>
                <div className="text-[12.5px] mt-0.5" style={{ color: C.inkDim }}>{r.bank_name} · <span className="cx-mono">{r.account_number}</span></div>
                <div className="flex flex-wrap gap-2 mt-2.5">
                  <span className="px-2 py-1 rounded-lg text-[11.5px] font-semibold flex items-center gap-1" style={{ background: r.bank_verified ? C.sageSoft : C.copperSoft, color: r.bank_verified ? C.sage : C.copper }}>{r.bank_verified ? <><BadgeCheck size={12} /> Name from the bank</> : 'Not checked with the bank (test mode)'}</span>
                  <span className="px-2 py-1 rounded-lg text-[11.5px] font-semibold" style={{ background: bankClose >= 0.66 ? C.sageSoft : C.rustSoft, color: bankClose >= 0.66 ? C.sage : C.rust }}>{bankClose >= 0.66 ? 'Matches the rider\'s name' : bankClose > 0 ? 'Only partly matches the rider\'s name' : 'Different from the rider\'s name'}</span>
                </div>
              </> : <div className="text-[13px]" style={{ color: C.inkFaint }}>Not added yet.</div>}
            </div>
          </div>
          <div className="space-y-4 lg:sticky lg:top-24 min-w-0">
            <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${allChecked && canDecide ? 'rgba(31,217,196,0.4)' : C.line}` }}>
              <div className="text-[14px] font-semibold mb-1">Checks</div>
              <div className="text-[12px] mb-3" style={{ color: C.inkFaint }}>Tick each one as you do it. All four are needed to approve.</div>
              <div className="space-y-2">
                {RIDER_CHECKS.map(([k, t, d]) => { const on = !!checks[k]; return (
                  <button key={k} type="button" disabled={!['submitted'].includes(r.status)} onClick={() => tick(k, !on)} className="w-full flex items-start gap-3 rounded-xl px-3 py-2.5 text-left" style={{ background: on ? C.sageSoft : C.surfaceRaised, border: `1px solid ${on ? 'rgba(31,217,196,0.35)' : C.line}` }}>
                    <span className="w-5 h-5 rounded-md flex items-center justify-center shrink-0 mt-0.5" style={{ background: on ? C.sageFill : 'transparent', border: `1.5px solid ${on ? C.sage : C.inkFaint}` }}>{on && <Check size={13} style={{ color: C.onAccent }} />}</span>
                    <span><span className="block text-[13.5px] font-semibold">{t}</span><span className="block text-[11.5px]" style={{ color: C.inkFaint }}>{d}</span></span>
                  </button>
                ); })}
              </div>
              {canDecide && !act.mode && (
                <div className="mt-4 space-y-2">
                  <button onClick={() => decide('approve')} disabled={!allChecked || act.busy} className="w-full h-11 rounded-xl text-[14px] font-bold flex items-center justify-center gap-2" style={{ background: allChecked ? C.sageFill : 'rgba(31,217,196,0.2)', color: allChecked ? C.onAccent : C.inkFaint }}><BadgeCheck size={16} /> Approve {String(r.full_name || '').split(' ')[0]}</button>
                  <div className="grid grid-cols-2 gap-2">
                    <button onClick={() => setAct({ mode: 'fix', note: '', busy: false, error: '' })} className="h-10 rounded-xl text-[13px] font-semibold" style={{ color: C.copper, border: `1px solid ${C.line}` }}>Ask for a fix</button>
                    <button onClick={() => setAct({ mode: 'reject', note: '', busy: false, error: '' })} className="h-10 rounded-xl text-[13px] font-semibold" style={{ color: C.rust, border: `1px solid ${C.line}` }}>Turn down</button>
                  </div>
                </div>
              )}
              {r.status === 'approved' && !act.mode && <button onClick={() => setAct({ mode: 'suspend', note: '', busy: false, error: '' })} className="mt-4 w-full h-10 rounded-xl text-[13px] font-semibold flex items-center justify-center gap-1.5" style={{ color: C.rust, border: `1px solid ${C.line}` }}><Lock size={14} /> Pause this rider</button>}
              {r.status === 'suspended' && isFounder && !act.mode && <button onClick={() => decide('reinstate')} className="mt-4 w-full h-10 rounded-xl text-[13px] font-semibold" style={{ background: C.sageFill, color: C.onAccent }}>Make active again</button>}
              {act.mode && (
                <div className="mt-4">
                  <div className="text-[13px] font-semibold mb-1.5">{act.mode === 'fix' ? 'What do they need to fix?' : act.mode === 'reject' ? 'Why are you turning them down?' : 'Why are you pausing them?'}</div>
                  {act.mode === 'fix' && <div className="flex flex-wrap gap-1.5 mb-2">{RIDER_FIX_SUGGEST.map((x) => <button key={x} type="button" onClick={() => setAct((a) => ({ ...a, note: x, error: '' }))} className="px-2.5 py-1.5 rounded-lg text-[11.5px] text-left" style={{ background: C.surfaceRaised, color: C.inkDim, border: `1px solid ${C.line}` }}>{x.split('.')[0]}</button>)}</div>}
                  <textarea rows={3} value={act.note} onChange={(e) => setAct({ ...act, note: e.target.value, error: '' })} placeholder={act.mode === 'fix' ? 'They see this, so write it to them.' : 'They see this.'} className="w-full rounded-xl px-3.5 py-2.5 text-[13.5px] outline-none resize-none" style={field} />
                  {act.error && <div className="mt-2 rounded-xl px-3 py-2 text-[12.5px]" style={{ background: C.rustSoft, color: C.rust }}>{act.error}</div>}
                  <div className="grid grid-cols-2 gap-2 mt-2">
                    <button onClick={() => setAct({ mode: '', note: '', busy: false, error: '' })} className="h-10 rounded-xl text-[13px] font-semibold" style={{ color: C.inkDim, border: `1px solid ${C.line}` }}>Back</button>
                    <button onClick={() => decide(act.mode)} disabled={act.busy} className="h-10 rounded-xl text-[13px] font-bold" style={{ background: act.mode === 'fix' ? C.copperFill : C.rustFill, color: act.mode === 'fix' ? C.onAccent : '#fff', opacity: act.busy ? 0.6 : 1 }}>{act.busy ? 'Saving…' : act.mode === 'fix' ? 'Send back' : act.mode === 'reject' ? 'Turn down' : 'Pause'}</button>
                  </div>
                </div>
              )}
              {r.review_note && !act.mode && r.status !== 'submitted' && <div className="mt-3 rounded-xl px-3 py-2 text-[12.5px]" style={{ background: C.surfaceRaised, color: C.inkDim }}>Note to rider: {r.review_note}</div>}
              {r.phone && <a href={wa(r, r.status === 'approved' ? 'approve' : r.status === 'needs_fix' ? 'fix' : r.status === 'rejected' ? 'reject' : r.status === 'suspended' ? 'suspend' : 'approve', r.review_note || '')} target="_blank" rel="noopener noreferrer" className="mt-3 flex items-center justify-center gap-1.5 text-[12.5px] font-semibold" style={{ color: C.sage }}><MessageCircle size={13} /> WhatsApp {String(r.full_name || '').split(' ')[0]}</a>}
            </div>
            <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
              <div className="text-[14px] font-semibold mb-3">History</div>
              <ol className="space-y-2.5">
                {(r.history || []).slice().reverse().map((h, i) => (
                  <li key={i} className="flex gap-2.5 text-[12.5px]">
                    <span className="w-2 h-2 rounded-full mt-1.5 shrink-0" style={{ background: h.by_team ? C.copperFill : C.sageFill }} />
                    <span className="min-w-0"><span className="font-semibold">{{ started: 'Started applying', submitted: 'Sent the application', nin_checked: 'Checked the NIN with NIMC', resubmitted: 'Fixed it and sent it again', approve: 'Approved', fix: 'Sent back for a fix', reject: 'Turned down', suspend: 'Paused', reinstate: 'Made active again' }[h.action] || h.action}</span>{h.by_team && h.by_name ? <span style={{ color: C.inkFaint }}> · {h.by_name}</span> : null}
                      <span className="block" style={{ color: C.inkFaint }}>{new Date(h.at).toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit', hour12: true })}</span>
                      {h.note && <span className="block mt-0.5" style={{ color: C.inkDim }}>"{h.note}"</span>}</span>
                  </li>
                ))}
              </ol>
            </div>
          </div>
        </div>
        {zoom && createPortal(<div className="fixed inset-0 z-[150] flex items-center justify-center p-4" style={{ background: 'rgba(0,0,0,0.85)' }} onClick={() => setZoom('')}><img src={zoom} alt="" className="max-w-full max-h-full rounded-xl" /><button aria-label="Close" className="absolute top-4 right-4 w-10 h-10 rounded-full flex items-center justify-center" style={{ background: 'rgba(255,255,255,0.12)', color: '#fff' }}><X size={18} /></button></div>, document.body)}
      </div>
    );
  }

  // ---------- The list ----------
  const tabs = [['submitted', 'To check', counts?.to_check], ['needs_fix', 'Waiting for a fix', counts?.needs_fix], ['approved', 'Approved', counts?.approved], ['suspended', 'Paused', counts?.suspended], ['draft', 'Still filling in', counts?.started]];
  return (
    <div>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-4">
        {[['To check', counts?.to_check, C.copper, Clock], ['Approved riders', counts?.approved, C.sage, BadgeCheck], ['Waiting for a fix', counts?.needs_fix, C.inkDim, Pencil], ['Still filling in', counts?.started, C.inkFaint, Bike]].map(([l, n, col, Ic]) => (
          <div key={l} className="rounded-2xl px-4 py-3" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
            <div className="flex items-center gap-1.5 text-[11.5px] font-semibold" style={{ color: C.inkFaint }}><Ic size={13} style={{ color: col }} />{l}</div>
            <div className="text-[24px] font-bold cx-mono mt-0.5" style={{ color: n ? col : C.inkFaint }}>{n ?? '–'}</div>
          </div>
        ))}
      </div>
      <div className="flex flex-col sm:flex-row gap-2 mb-4">
        <div className="flex gap-1 p-1 rounded-xl overflow-x-auto" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
          {tabs.map(([k, l, n]) => <button key={k} onClick={() => setTab(k)} className="shrink-0 px-3 py-1.5 rounded-lg text-[12.5px] font-semibold whitespace-nowrap" style={tab === k ? { background: C.copperFill, color: C.onAccent } : { color: C.inkDim }}>{l}{n ? ` ${n}` : ''}</button>)}
        </div>
        <div className="relative flex-1"><Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: C.inkFaint }} /><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Name, phone or area" className="w-full rounded-xl pl-9 pr-3 py-2.5 text-[13.5px] outline-none" style={field} /></div>
      </div>
      {list === null ? <div className="py-12 flex justify-center"><Loader2 size={18} className="animate-spin" style={{ color: C.inkFaint }} /></div>
        : !list.length ? (
          <div className="rounded-2xl py-12 px-6 text-center" style={{ border: `1px dashed ${C.lineStrong}` }}>
            <Bike size={26} className="mx-auto" style={{ color: C.inkFaint }} />
            <div className="text-[14.5px] font-semibold mt-2">{tab === 'submitted' ? 'No applications waiting' : 'Nobody here'}</div>
            <div className="text-[12.5px] mt-1" style={{ color: C.inkFaint }}>Riders apply at <span className="cx-mono" style={{ color: C.inkDim }}>{typeof window !== 'undefined' ? window.location.host : ''}/ride</span>. Share the link with dispatch riders you trust.</div>
          </div>
        ) : (
          <div className="grid sm:grid-cols-2 gap-2.5">
            {list.map((r) => { const st = RIDER_ADMIN_STATUS[r.status] || ['', C.inkDim]; const v = RIDER_VEHICLES.find(([k]) => k === r.vehicle); return (
              <button key={r.id} onClick={() => show(r.id)} className="rounded-2xl p-3.5 flex items-center gap-3 text-left transition-colors" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
                <span className="w-12 h-12 rounded-xl overflow-hidden shrink-0 flex items-center justify-center" style={{ background: C.surfaceRaised }}>{thumbs[r.id] ? <img src={thumbs[r.id]} alt="" className="w-full h-full object-cover" /> : <span className="text-[14px] font-bold" style={{ color: C.inkDim }}>{riderInitials(r.full_name)}</span>}</span>
                <span className="flex-1 min-w-0">
                  <span className="block text-[14px] font-semibold truncate">{r.full_name || 'No name yet'}</span>
                  <span className="block text-[12px] truncate" style={{ color: C.inkDim }}>{v ? v[1] : '—'} · {r.lga || r.state || '—'}{(r.areas || []).length > 1 ? ` +${r.areas.length - 1}` : ''}</span>
                  <span className="block text-[11.5px]" style={{ color: C.inkFaint }}>{r.submitted_at ? `Sent ${riderAgo(r.submitted_at)}` : `Started ${riderAgo(r.created_at)}`}</span>
                </span>
                <span className="shrink-0 px-2 py-1 rounded-full text-[10.5px] font-bold" style={{ background: `${st[1]}22`, color: st[1] }}>{st[0]}</span>
              </button>
            ); })}
          </div>
        )}
    </div>
  );
}

// ============ The Xorla home page (what new visitors see at xorla.vercel.app) ============
// Logged-in owners and staff never see it: they go straight to their dashboard.
// Light and dark: follows the phone's setting until the visitor picks one. Colours are CSS variables, so one switch re-colours everything.
const LP_THEMES = {
  light: { bg: '#FFFFFF', bg2: '#F4F8F6', card: '#FFFFFF', tint: '#E3F4EF', deep: '#0B3B33', ink: '#0B2B26', dim: '#4A5E59', faint: '#7F918C', line: 'rgba(11,43,38,0.10)', btn: '#0B3B33', btnInk: '#FFFFFF', accent: '#0E9F8E', nav: 'rgba(255,255,255,0.78)', wa: '#DCF8C6', waInk: '#0B2B26', dots: 'rgba(11,43,38,0.09)', shadow: 'rgba(11,43,38,0.45)', glow: 'rgba(31,217,196,0)' },
  dark: { bg: '#071A17', bg2: '#0B221E', card: '#0F2925', tint: '#12352F', deep: '#0F3A33', ink: '#EAF6F2', dim: '#A6C0BA', faint: '#6E8B85', line: 'rgba(255,255,255,0.09)', btn: '#1FD9C4', btnInk: '#062520', accent: '#1FD9C4', nav: 'rgba(7,26,23,0.72)', wa: '#005C4B', waInk: '#E9FFF6', dots: 'rgba(255,255,255,0.06)', shadow: 'rgba(0,0,0,0.75)', glow: 'rgba(31,217,196,0.22)' },
};
const LP = Object.fromEntries(Object.keys(LP_THEMES.light).map((k) => [k, `var(--lp-${k})`]));
Object.assign(LP, { amber: '#FFB020', teal: '#1FD9C4', coral: '#F4845F', paper: '#FFFDF6', forest: '#0B3B33', inkFixed: '#0B2B26' });
const LP_DISPLAY = "'Unbounded', 'Inter', system-ui, sans-serif";
const LP_BODY = "'Poppins', 'Inter', system-ui, sans-serif";
const LP_MONO = "'IBM Plex Mono', ui-monospace, Menlo, monospace";

// Numbers that count up when they come into view (or when they change)
function LpCount({ value, prefix = '₦', ms = 900 }) {
  const ref = useRef(null);
  const [shown, setShown] = useState(0);
  const [seen, setSeen] = useState(false);
  const from = useRef(0);
  useEffect(() => {
    const el = ref.current; if (!el) return undefined;
    if (!('IntersectionObserver' in window)) { setSeen(true); return undefined; }
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setSeen(true); io.disconnect(); } }, { threshold: 0.4 });
    io.observe(el); return () => io.disconnect();
  }, []);
  useEffect(() => {
    if (!seen) return undefined;
    const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduce) { setShown(value); from.current = value; return undefined; }
    const a = from.current, t0 = performance.now(); let raf;
    const step = (t) => { const k = Math.min(1, (t - t0) / ms); const e = 1 - Math.pow(1 - k, 3); setShown(Math.round(a + (value - a) * e)); if (k < 1) raf = requestAnimationFrame(step); else from.current = value; };
    raf = requestAnimationFrame(step); return () => cancelAnimationFrame(raf);
  }, [value, seen]);
  return <span ref={ref} style={{ fontVariantNumeric: 'tabular-nums' }}>{prefix}{shown.toLocaleString('en-NG')}</span>;
}

// The last word of the headline keeps changing: wahala, stress, headache...
const LP_WORDS = ['wahala.', 'stress.', 'headache.', 'guesswork.', 'palava.'];
function LpRotate({ words, still }) {
  const [i, setI] = useState(0);
  useEffect(() => {
    if (still) return undefined;
    const t = setInterval(() => setI((x) => (x + 1) % words.length), 2400);
    return () => clearInterval(t);
  }, [still, words.length]);
  return (
    <span className="lp-rot" style={{ display: 'inline-grid', verticalAlign: 'bottom', overflow: 'hidden', paddingBottom: '0.08em', marginBottom: '-0.08em' }}>
      {/* the longest word sets the width, so nothing around it jumps */}
      <span style={{ gridArea: '1 / 1', visibility: 'hidden' }}>{words.reduce((a, w) => (w.length > a.length ? w : a), '')}</span>
      <span key={i} className="lp-rot-word" style={{ gridArea: '1 / 1', color: LP.accent }}>{words[i]}</span>
    </span>
  );
}

const LP_RECEIPT = [['Indomie Super Pack ×2', 1900], ['Peak Milk tin ×3', 1950], ['Hair braiding (Ada)', 15000], ['Room 204, 2 nights', 70000], ['Delivery to Aba Road', 1500]];
function LandingReceipt({ still }) {
  const total = LP_RECEIPT.reduce((a, [, v]) => a + v, 0);
  return (
    <div className={`lp-receipt ${still ? 'lp-still' : ''}`} style={{ fontFamily: LP_MONO }} aria-label={`A receipt for today: total ${fmt(total)}, profit ${fmt(42500)}`}>
      <div className="text-center">
        <div className="text-[13px] font-semibold tracking-wide">AMAKA STORES</div>
        <div className="text-[10.5px]" style={{ color: '#7F918C' }}>Ikot Ekpene Road, Umuahia</div>
        <div className="lp-dash my-2.5" />
      </div>
      {LP_RECEIPT.map(([d, v], i) => (
        <div key={d} className="lp-line flex justify-between gap-3 text-[11.5px] leading-[1.9]" style={{ animationDelay: `${0.6 + i * 0.3}s` }}><span className="truncate">{d}</span><span className="shrink-0">{fmt(v)}</span></div>
      ))}
      <div className="lp-line lp-dash my-2" style={{ animationDelay: `${0.6 + LP_RECEIPT.length * 0.3}s` }} />
      <div className="lp-line flex justify-between text-[12.5px] font-semibold" style={{ animationDelay: `${0.72 + LP_RECEIPT.length * 0.3}s` }}><span>Sales today</span><span>{fmt(total)}</span></div>
      <div className="lp-stamp mt-3 rounded-lg px-3 py-2 text-center" style={{ animationDelay: `${1.05 + LP_RECEIPT.length * 0.3}s` }}>
        <div className="text-[10px]">PROFIT TODAY</div>
        <div className="text-[19px] font-semibold leading-tight">{fmt(42500)}</div>
      </div>
      <div className="text-center text-[10px] mt-2.5" style={{ color: '#7F918C' }}>Recorded on Xorla</div>
    </div>
  );
}

function LandingPhone() {
  const bars = [38, 52, 44, 68, 58, 80, 92];
  return (
    <div className="lp-phone" aria-hidden>
      <div className="lp-phone-screen" style={{ fontFamily: "'Poppins', 'Inter', sans-serif" }}>
        <div className="flex items-center justify-between px-4 pt-5">
          <div className="flex items-center gap-1.5"><XorlaMark size={16} /><span className="text-[11px] font-bold text-white">Xorla</span></div>
          <span className="w-6 h-6 rounded-full flex items-center justify-center text-[9px] font-bold" style={{ background: 'rgba(255,255,255,0.08)', color: '#EAF6F2' }}>AO</span>
        </div>
        <div className="px-4 mt-3 text-[10.5px]" style={{ color: '#93B0AA' }}>Good evening, Amaka</div>
        <div className="mx-3 mt-2 rounded-2xl p-3.5" style={{ background: 'linear-gradient(160deg, #164A41, #0F2925)', border: '1px solid rgba(255,255,255,0.07)' }}>
          <div className="text-[9.5px]" style={{ color: '#93B0AA' }}>Profit today</div>
          <div className="text-[22px] font-bold leading-tight" style={{ color: '#1FD9C4' }}>{fmt(42500)}</div>
          <div className="text-[9px] mt-0.5" style={{ color: '#93B0AA' }}>Up {fmt(6100)} on yesterday</div>
          <div className="flex items-end gap-1 h-12 mt-2.5">{bars.map((h, i) => <span key={i} className="lp-bar flex-1 rounded-sm" style={{ height: `${h}%`, background: i === bars.length - 1 ? '#FFB020' : 'rgba(31,217,196,0.35)', animationDelay: `${0.3 + i * 0.08}s` }} />)}</div>
        </div>
        <div className="grid grid-cols-2 gap-2 mx-3 mt-2">
          <div className="rounded-xl p-2.5" style={{ background: '#13322C' }}><div className="text-[8.5px]" style={{ color: '#93B0AA' }}>Owed to you</div><div className="text-[12px] font-bold text-white">{fmt(18200)}</div></div>
          <div className="rounded-xl p-2.5" style={{ background: '#13322C' }}><div className="text-[8.5px]" style={{ color: '#93B0AA' }}>Low stock</div><div className="text-[12px] font-bold" style={{ color: '#FFB020' }}>3 items</div></div>
        </div>
        <div className="mx-3 mt-2 rounded-xl overflow-hidden" style={{ background: '#13322C' }}>
          {[['Hair braiding', 'Ada', 15000], ['Peak Milk ×3', 'Tolu', 1950], ['Indomie ×2', 'Tolu', 1900]].map(([d, w, v], i) => (
            <div key={d} className="flex items-center justify-between px-3 py-2" style={{ borderTop: i ? '1px solid rgba(255,255,255,0.06)' : 'none' }}>
              <span><span className="block text-[10px] font-semibold text-white">{d}</span><span className="block text-[8.5px]" style={{ color: '#54706A' }}>by {w}</span></span>
              <span className="text-[10px] font-semibold text-white">{fmt(v)}</span>
            </div>
          ))}
        </div>
        <div className="absolute left-0 right-0 bottom-0 h-12 flex items-center justify-around px-4" style={{ background: '#0F2925', borderTop: '1px solid rgba(255,255,255,0.06)' }}>
          {[TrendingUp, ShoppingBag, CalendarClock, Package].map((Ic, i) => <Ic key={i} size={15} style={{ color: i === 0 ? '#FFB020' : '#54706A' }} />)}
        </div>
      </div>
    </div>
  );
}

// Try it: tap products to record sales, and watch the day add up (nothing is saved; it's a demo)
const LP_DEMO = [['Indomie', 950, 720, '🍜'], ['Peak Milk', 650, 520, '🥛'], ['Coke 50cl', 400, 300, '🥤'], ['Bread', 1200, 950, '🍞'], ['Eggs, crate', 4800, 4200, '🥚'], ['Sugar 1kg', 1500, 1180, '🧂']];
function LandingDemo() {
  const [sales, setSales] = useState([]);
  const [receipt, setReceipt] = useState(false);
  const total = sales.reduce((a, s) => a + s.price, 0);
  const profit = sales.reduce((a, s) => a + s.price - s.cost, 0);
  const add = ([name, price, cost, icon]) => { setReceipt(false); setSales((x) => [{ id: Date.now() + Math.random(), name, price, cost, icon }, ...x].slice(0, 30)); };
  return (
    <div className="grid lg:grid-cols-[1fr_1fr] gap-4 items-stretch">
      <div className="rounded-[28px] p-5 sm:p-6" style={{ background: LP.card, border: `1px solid ${LP.line}` }}>
        <div className="flex items-center justify-between"><span className="text-[15px] font-bold">Tap what you sold</span><span className="text-[12.5px]" style={{ color: LP.faint }}>Price is filled in</span></div>
        <div className="mt-4 grid grid-cols-2 sm:grid-cols-3 gap-2.5">
          {LP_DEMO.map((p) => (
            <button key={p[0]} onClick={() => add(p)} className="lp-focus lp-press rounded-2xl p-3.5 text-left" style={{ background: LP.bg2, border: `1px solid ${LP.line}` }}>
              <span className="text-[24px] leading-none" aria-hidden>{p[3]}</span>
              <span className="block mt-2 text-[14px] font-semibold">{p[0]}</span>
              <span className="block text-[13px]" style={{ color: LP.dim }}>{fmt(p[1])}</span>
            </button>
          ))}
        </div>
        {/* Phones: see the totals change right under your thumb */}
        <div className="lg:hidden mt-3 grid grid-cols-2 gap-2" aria-live="polite">
          <div className="rounded-xl px-3.5 py-2.5" style={{ background: LP.bg2 }}><div className="text-[11.5px]" style={{ color: LP.faint }}>Sales today</div><div className="text-[18px] font-bold" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.03em' }}><LpCount value={total} ms={400} /></div></div>
          <div className="rounded-xl px-3.5 py-2.5" style={{ background: LP.tint }}><div className="text-[11.5px]" style={{ color: LP.faint }}>Profit today</div><div className="text-[18px] font-bold" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.03em', color: LP.accent }}><LpCount value={profit} ms={400} /></div></div>
        </div>
        <p className="mt-4 text-[13px]" style={{ color: LP.faint }}>This is a demo. Nothing you tap here is saved.</p>
      </div>
      <div className="rounded-[28px] p-5 sm:p-6 flex flex-col" style={{ background: '#0A1F1C', color: '#EAF6F2', minHeight: 360, border: `1px solid ${LP.line}` }}>
        <div className="grid grid-cols-2 gap-3">
          <div className="rounded-2xl p-4" style={{ background: '#13322C' }}><div className="text-[12px]" style={{ color: '#93B0AA' }}>Sales today</div><div className="text-[26px] font-bold mt-0.5" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.03em' }}><LpCount value={total} ms={450} /></div></div>
          <div className="rounded-2xl p-4" style={{ background: 'rgba(31,217,196,0.12)', border: '1px solid rgba(31,217,196,0.3)' }}><div className="text-[12px]" style={{ color: '#93B0AA' }}>Profit today</div><div className="text-[26px] font-bold mt-0.5" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.03em', color: '#1FD9C4' }}><LpCount value={profit} ms={450} /></div></div>
        </div>
        <div className="mt-3 flex-1 rounded-2xl overflow-hidden" style={{ background: '#13322C' }}>
          {sales.length === 0 ? (
            <div className="h-full min-h-[160px] flex flex-col items-center justify-center text-center px-6 gap-2" style={{ color: '#93B0AA' }}><MousePointerClick size={22} /><span className="text-[14px]">Tap a product to record your first sale</span></div>
          ) : (
            <div className="max-h-[210px] overflow-y-auto">
              {sales.map((s, i) => (
                <div key={s.id} className={`flex items-center justify-between px-4 py-2.5 text-[14px] ${i === 0 ? 'lp-new' : ''}`} style={{ borderTop: i ? '1px solid rgba(255,255,255,0.06)' : 'none' }}>
                  <span className="flex items-center gap-2.5"><span aria-hidden>{s.icon}</span>{s.name}</span><span className="font-semibold">{fmt(s.price)}</span>
                </div>
              ))}
            </div>
          )}
        </div>
        {receipt && sales.length > 0 && (
          <div className="lp-new mt-3 rounded-2xl rounded-tl-md px-4 py-3 text-[13px] leading-relaxed" style={{ background: '#005C4B', color: '#E9FFF6' }}>
            Thank you for shopping at Amaka Stores! {sales.length} item{sales.length !== 1 ? 's' : ''}, total {fmt(total)}. See you again soon.
          </div>
        )}
        <div className="mt-3 grid grid-cols-2 gap-2">
          <button onClick={() => setReceipt(true)} disabled={!sales.length} className="lp-focus h-11 rounded-full text-[14px] font-semibold flex items-center justify-center gap-2" style={{ background: sales.length ? '#25D366' : 'rgba(255,255,255,0.08)', color: sales.length ? '#062520' : '#6E8B85' }}><MessageCircle size={16} /> Send receipt</button>
          <button onClick={() => { setSales([]); setReceipt(false); }} disabled={!sales.length} className="lp-focus h-11 rounded-full text-[14px] font-semibold" style={{ color: sales.length ? '#EAF6F2' : '#6E8B85', boxShadow: 'inset 0 0 0 1.5px rgba(255,255,255,0.14)' }}>Start again</button>
        </div>
      </div>
    </div>
  );
}

const LP_KINDS = [
  [ShoppingBasket, 'Provision stores'], [Shirt, 'Boutiques'], [Pill, 'Pharmacies'], [Scissors, 'Salons and barbers'], [UtensilsCrossed, 'Restaurants'],
  [Hotel, 'Hotels and shortlets'], [PartyPopper, 'Event halls'], [Car, 'Car rentals'], [Wrench, 'Repairs and services'], [Boxes, 'Wholesalers'],
];
const LP_TYPES = {
  shops: { label: 'Shops', title: 'For shops and stores',
    points: ['Record a sale in seconds, with the price filled in', 'Stock goes down by itself, and you get warned before you run out', 'Your own online shop link: customers order and pay, you deliver', 'Know who owes you, and send them a reminder on WhatsApp'],
    screen: { head: 'Today at Amaka Stores', rows: [['Mama Gold Rice 50kg', '₦78,000'], ['Kings Oil 5L ×2', '₦29,000'], ['Indomie (carton)', '₦9,800']], note: 'Indomie: 3 cartons left', tone: 'amber' } },
  services: { label: 'Services', title: 'For salons, repairers and every service',
    points: ['Customers book a time on your page, only when you\'re free', 'Customers can choose who they want, and each staff member gets their own login', 'Reminders go out so fewer people forget their appointment', 'See what every service brings in, not just the total'],
    screen: { head: 'Bookings today', rows: [['10:00, Braids', 'Ada'], ['12:30, Haircut', 'Chidi'], ['3:00, Nails', 'Ada']], note: 'Next: braids at 10:00', tone: 'teal' } },
  hotels: { label: 'Hotels', title: 'For hotels, shortlets and event halls',
    points: ['Guests book rooms and pay a deposit online', 'A room board shows who is in, arriving and leaving', 'Extras like water, laundry and airport pickup go on the room bill', 'Check out with one total: the stay and every extra'],
    screen: { head: 'Rooms tonight', rows: [['Room 101', 'In house'], ['Room 204', 'Arriving 2pm'], ['Room 305', 'Free']], note: '2 of 3 rooms booked', tone: 'teal' } },
};
const LP_FAQ = [
  ['Do I need a computer?', 'No. Xorla works on any smartphone, in the browser. You can also add it to your home screen like an app. If you have a laptop, it works there too.'],
  ['Is it really free?', 'Yes. The Free plan is free for as long as you use it, for up to 20 products or services. Pro and Business come with a 30-day free trial, and you only pay if you decide to keep them.'],
  ['What happens to my records if I stop paying?', 'Nothing is deleted. You move to the Free plan, and every sale, invoice and customer is still there.'],
  ['Can my staff use it without seeing everything?', 'Yes. Staff get their own login and only see what you allow. You approve everyone before they can start, and you can remove them any time.'],
  ['Does it work when there is no network?', 'Yes. Once Xorla has opened on your phone with internet, it opens without it too. Keep recording sales and expenses with no data or no signal. They are kept safely on the phone and sent to Xorla by themselves when you are back online. Nothing is counted twice.'],
  ['What if I lose my phone?', 'Your records are kept safely online, not on the phone. Log in on another phone and everything is there. You can also lock Xorla with a PIN.'],
  ['Can customers pay me online?', 'Yes. Customers pay by card, transfer or USSD through Paystack, and the money goes straight to your bank account. Xorla never sees their card details.'],
];

function LandingPage() {
  const rootRef = useRef(null);
  const [theme, setTheme] = useState(() => {
    try { const t = localStorage.getItem('xorla:lp-theme'); if (t === 'light' || t === 'dark') return t; } catch (e) {}
    try { return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'; } catch (e) { return 'light'; }
  });
  const [tab, setTab] = useState('shops');
  const [faq, setFaq] = useState(0);
  const [menu, setMenu] = useState(false);
  const [yearly, setYearly] = useState(false);
  // Early-supporter places left (the first 100 paying businesses get a lower price for 12 months)
  const [spots, setSpots] = useState(null);
  useEffect(() => { sbRpc('early_supporter_spots', SB_KEY, {}).then((n) => setSpots(typeof n === 'number' ? n : null)).catch(() => {}); }, []);
  useEffect(() => {
    if (!menu) return undefined;
    const prev = document.body.style.overflow; document.body.style.overflow = 'hidden';
    const onKey = (e) => { if (e.key === 'Escape') setMenu(false); };
    window.addEventListener('keydown', onKey);
    return () => { document.body.style.overflow = prev; window.removeEventListener('keydown', onKey); };
  }, [menu]);
  const [scrolled, setScrolled] = useState(0);   // 0..1 how far down the page
  const [pastHero, setPastHero] = useState(false);
  const still = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const flip = () => setTheme((t) => { const n = t === 'dark' ? 'light' : 'dark'; try { localStorage.setItem('xorla:lp-theme', n); } catch (e) {} return n; });
  useEffect(() => {
    document.title = 'Xorla: run your business without wahala';
    const html = document.documentElement; const prev = html.style.scrollBehavior;
    if (!still) html.style.scrollBehavior = 'smooth';
    return () => { html.style.scrollBehavior = prev; };
  }, []);
  // The browser bar and page background follow the theme
  useEffect(() => {
    const m = document.querySelector('meta[name="theme-color"]'); const prev = m && m.getAttribute('content');
    if (m) m.setAttribute('content', LP_THEMES[theme].bg);
    document.body.style.background = LP_THEMES[theme].bg;
    return () => { if (m && prev) m.setAttribute('content', prev); document.body.style.background = ''; };
  }, [theme]);
  // Scroll: the progress line, the top bar, and the phone's sticky button
  useEffect(() => {
    let raf = 0;
    const on = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(() => { const h = document.documentElement.scrollHeight - window.innerHeight; setScrolled(h > 0 ? Math.min(1, window.scrollY / h) : 0); setPastHero(window.scrollY > 640); }); };
    on(); window.addEventListener('scroll', on, { passive: true }); window.addEventListener('resize', on);
    return () => { cancelAnimationFrame(raf); window.removeEventListener('scroll', on); window.removeEventListener('resize', on); };
  }, []);
  // Sections glide in as they come into view
  useEffect(() => {
    const els = rootRef.current ? [...rootRef.current.querySelectorAll('[data-reveal]')] : [];
    if (still || !('IntersectionObserver' in window)) { els.forEach((el) => el.classList.add('lp-in')); return undefined; }
    const io = new IntersectionObserver((entries) => entries.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('lp-in'); io.unobserve(e.target); } }), { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
    els.forEach((el) => io.observe(el)); return () => io.disconnect();
  }, []);

  const t = LP_TYPES[tab];
  const start = '/login?start=signup';
  const vars = Object.fromEntries(Object.entries(LP_THEMES[theme]).map(([k, v]) => [`--lp-${k}`, v]));
  const wrap = 'max-w-[1280px] mx-auto px-5 sm:px-8 lg:px-10';
  const H = (size, extra = {}) => ({ fontFamily: LP_DISPLAY, fontSize: size, lineHeight: 1.06, letterSpacing: '-0.035em', fontWeight: 700, ...extra });
  const btn = 'lp-focus lp-press inline-flex items-center justify-center gap-2 h-[52px] px-7 rounded-full text-[15.5px] font-bold';
  const head = (text, sub, light) => (
    <div className="max-w-[720px]" data-reveal>
      <h2 style={H('clamp(28px, 3.6vw, 46px)', { color: light ? '#fff' : LP.ink })}>{text}</h2>
      {sub && <p className="mt-4 text-[17px] leading-relaxed max-w-[600px]" style={{ color: light ? 'rgba(255,255,255,0.74)' : LP.dim }}>{sub}</p>}
    </div>
  );
  const tile = (bg, children, cls = '', d = 0, extra = {}) => <div data-reveal className={`lp-tile rounded-[28px] p-6 sm:p-7 overflow-hidden relative ${cls}`} style={{ background: bg, '--d': `${d}s`, ...extra }}>{children}</div>;
  const tt = (a, b, onDark, onBright) => <><h3 className="text-[18px] sm:text-[19px] font-semibold leading-snug" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.02em', color: onDark ? '#fff' : onBright ? LP.inkFixed : LP.ink }}>{a}</h3><p className="mt-2.5 text-[14.5px] leading-relaxed max-w-sm" style={{ color: onDark ? 'rgba(255,255,255,0.74)' : onBright ? 'rgba(11,43,38,0.8)' : LP.dim }}>{b}</p></>;
  const navLinks = [['#try', 'Try it'], ['#features', 'What it does'], ['#for-you', 'Who it\'s for'], ['#pricing', 'Pricing'], ['/ride', 'Riders']];
  const themeBtn = (
    <button onClick={flip} aria-label={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'} className="lp-focus w-10 h-10 rounded-full flex items-center justify-center shrink-0" style={{ background: LP.bg2, border: `1px solid ${LP.line}` }}>
      <span className="lp-spin" key={theme}>{theme === 'dark' ? <Sun size={17} style={{ color: LP.amber }} /> : <Moon size={17} />}</span>
    </button>
  );
  const early = typeof spots === 'number' && spots > 0;
  const regular = (plan) => planPrice(plan, yearly ? 'yearly' : 'monthly', 0, false);
  const price = (plan) => planPrice(plan, yearly ? 'yearly' : 'monthly', 0, early);
  const perDay = (plan) => Math.round(price(plan) / (yearly ? 365 : 30) / 10) * 10;

  return (
    <div ref={rootRef} className="lp-root" style={{ ...vars, background: LP.bg, color: LP.ink, fontFamily: LP_BODY, minHeight: '100vh', transition: 'background-color .35s ease, color .35s ease' }}>
      <style>{`
        .lp-root ::selection { background: #FFB020; color: #0B2B26; }
        .lp-receipt { position: relative; width: 236px; background: ${LP.paper}; color: #0B2B26; padding: 18px 18px 26px; border-radius: 6px 6px 0 0;
          box-shadow: 0 30px 60px -28px var(--lp-shadow);
          -webkit-mask: linear-gradient(#000 0 0) top/100% calc(100% - 10px) no-repeat, conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom/16px 10px repeat-x;
                  mask: linear-gradient(#000 0 0) top/100% calc(100% - 10px) no-repeat, conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom/16px 10px repeat-x; }
        .lp-dash { border-top: 1.5px dashed rgba(11,43,38,0.28); }
        .lp-line { opacity: 0; transform: translateY(-4px); animation: lpPrint .28s ease-out forwards; }
        .lp-stamp { opacity: 0; transform: scale(1.25) rotate(-6deg); background: #E3F4EF; color: #0B3B33; border: 1.5px solid #0E9F8E; animation: lpStamp .38s cubic-bezier(.2,1.4,.4,1) forwards; }
        .lp-still .lp-line, .lp-still .lp-stamp { animation: none; opacity: 1; transform: none; }
        @keyframes lpPrint { to { opacity: 1; transform: none; } }
        @keyframes lpStamp { to { opacity: 1; transform: rotate(-3deg); } }
        .lp-phone { width: 250px; height: 510px; border-radius: 42px; padding: 10px; background: #0B2B26; box-shadow: 0 50px 90px -40px var(--lp-shadow), 0 0 90px -10px var(--lp-glow), inset 0 0 0 2px rgba(255,255,255,0.1); }
        .lp-phone-screen { position: relative; height: 100%; border-radius: 33px; overflow: hidden; background: #0A1F1C; }
        .lp-float { animation: lpFloat 7s ease-in-out infinite; }
        @keyframes lpFloat { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
        .lp-bar { transform-origin: bottom; transform: scaleY(0); animation: lpGrow .7s cubic-bezier(.2,.8,.2,1) forwards; }
        @keyframes lpGrow { to { transform: scaleY(1); } }
        .lp-bubble { opacity: 0; transform: translateY(10px) scale(.95); animation: lpPop .45s cubic-bezier(.2,1.3,.4,1) forwards; }
        @keyframes lpPop { to { opacity: 1; transform: none; } }
        .lp-hero-in > * { opacity: 0; transform: translateY(18px); animation: lpUp .8s cubic-bezier(.2,.7,.2,1) forwards; }
        .lp-hero-in > *:nth-child(2) { animation-delay: .12s; } .lp-hero-in > *:nth-child(3) { animation-delay: .24s; } .lp-hero-in > *:nth-child(4) { animation-delay: .36s; }
        @keyframes lpUp { to { opacity: 1; transform: none; } }
        [data-reveal] { opacity: 0; transform: translateY(26px); transition: opacity .8s cubic-bezier(.2,.7,.2,1), transform .8s cubic-bezier(.2,.7,.2,1); transition-delay: var(--d, 0s); }
        [data-reveal].lp-in { opacity: 1; transform: none; }
        .lp-tile { transition: opacity .8s cubic-bezier(.2,.7,.2,1), transform .8s cubic-bezier(.2,.7,.2,1), box-shadow .3s ease; }
        .lp-tile.lp-in:hover { transform: translateY(-4px); box-shadow: 0 28px 50px -30px var(--lp-shadow); }
        .lp-press { transition: transform .15s ease, box-shadow .2s ease, background-color .2s ease; }
        .lp-press:hover { transform: translateY(-1px); } .lp-press:active { transform: scale(.97); }
        .lp-new { animation: lpNew .45s cubic-bezier(.2,1.2,.4,1); }
        @keyframes lpNew { from { opacity: 0; transform: translateY(-8px); background: rgba(31,217,196,0.18); } to { opacity: 1; transform: none; } }
        .lp-marquee { display: flex; width: max-content; animation: lpMarq 42s linear infinite; }
        /* Works-offline phone: signal drops, sales keep coming with a "waiting" mark, signal returns, all sent (9s loop) */
        .lp-off-bar { animation: lpOffBar 9s infinite; }
        @keyframes lpOffBar { 0%, 8% { opacity: 1; } 14%, 62% { opacity: .18; } 70%, 100% { opacity: 1; } }
        .lp-off-row { animation: lpOffRow 9s infinite; animation-delay: calc(var(--r) * .45s); }
        @keyframes lpOffRow { 0%, 16% { opacity: 0; transform: translateY(8px); } 22%, 92% { opacity: 1; transform: none; } 100% { opacity: 0; } }
        .lp-off-wait { animation: lpOffWait 9s infinite; }
        @keyframes lpOffWait { 0%, 70% { opacity: 1; } 76%, 100% { opacity: 0; } }
        .lp-off-pill-a { animation: lpOffA 9s infinite; }
        @keyframes lpOffA { 0%, 10% { opacity: 0; } 15%, 68% { opacity: 1; } 73%, 100% { opacity: 0; } }
        .lp-off-pill-b { animation: lpOffB 9s infinite; }
        @keyframes lpOffB { 0%, 72% { opacity: 0; transform: scale(.9); } 76%, 94% { opacity: 1; transform: none; } 100% { opacity: 0; } }
        .lp-marquee-wrap:hover .lp-marquee { animation-play-state: paused; }
        @keyframes lpMarq { to { transform: translateX(-50%); } }
        .lp-orb { animation: lpOrb 18s ease-in-out infinite alternate; }
        @keyframes lpOrb { from { transform: translate(0,0) scale(1); } to { transform: translate(-40px, 30px) scale(1.06); } }
        .lp-spin { display: inline-flex; animation: lpSpin .45s cubic-bezier(.2,1.2,.4,1); }
        @keyframes lpSpin { from { transform: rotate(-90deg) scale(.5); opacity: 0; } }
        .lp-rot-word { display: inline-block; animation: lpWord .55s cubic-bezier(.2,.9,.2,1); }
        @keyframes lpWord { from { transform: translateY(85%); opacity: 0; filter: blur(4px); } to { transform: none; opacity: 1; filter: none; } }
        .lp-faq { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .35s ease; }
        .lp-faq.open { grid-template-rows: 1fr; }
        .lp-focus:focus-visible { outline: 3px solid ${LP.accent}; outline-offset: 3px; }
        .lp-bar-r { transform-origin: bottom; transform: scaleY(0); transition: transform .8s cubic-bezier(.2,.8,.2,1) var(--bd, 0s); }
        .lp-in .lp-bar-r { transform: scaleY(1); }
        .lp-line-grow { transform-origin: left; transform: scaleX(0); transition: transform 1.2s cubic-bezier(.2,.7,.2,1) .2s; }
        .lp-in .lp-line-grow { transform: scaleX(1); }
        @media (prefers-reduced-motion: reduce) {
          .lp-line, .lp-stamp, .lp-bubble, .lp-bar, .lp-hero-in > *, [data-reveal], .lp-new, .lp-spin, .lp-rot-word { animation: none !important; opacity: 1 !important; transform: none !important; transition: none !important; }
          .lp-float, .lp-marquee, .lp-orb { animation: none !important; }
          .lp-off-bar, .lp-off-row, .lp-off-wait, .lp-off-pill-b { animation: none !important; opacity: 1 !important; transform: none !important; }
          .lp-off-pill-a { animation: none !important; opacity: 0 !important; }
          .lp-line-grow, .lp-bar-r { transform: none !important; }
        }
      `}</style>

      <style>{`
        .lp-menu .lp-menu-bg { opacity: 0; transition: opacity .35s ease; }
        .lp-menu .lp-menu-glow { opacity: 0; transform: scale(.6); transition: opacity .6s ease, transform .9s cubic-bezier(.2,.7,.2,1); }
        .lp-menu .lp-mi { opacity: 0; transform: translateY(16px); transition: opacity .45s ease, transform .55s cubic-bezier(.2,.7,.2,1); transition-delay: 0s; }
        .lp-menu-open .lp-menu-bg { opacity: 1; }
        .lp-menu-open .lp-menu-glow { opacity: 1; transform: none; }
        .lp-menu-open .lp-mi { opacity: 1; transform: none; transition-delay: calc(var(--i, 0) * 45ms + 60ms); }
        @media (prefers-reduced-motion: reduce) { .lp-menu * { transition: none !important; } }
      `}</style>
      {/* How far down the page you are */}
      <div aria-hidden className="fixed top-0 left-0 right-0 h-[3px] z-50 origin-left" style={{ background: `linear-gradient(90deg, ${LP.teal}, ${LP.amber})`, transform: `scaleX(${scrolled})` }} />

      <header className={`sticky top-0 ${menu ? 'z-[60]' : 'z-40'} transition-[background-color,box-shadow] duration-300`} style={{ background: menu ? 'transparent' : scrolled > 0.005 ? LP.nav : 'transparent', backdropFilter: 'saturate(1.4) blur(14px)', WebkitBackdropFilter: 'saturate(1.4) blur(14px)', boxShadow: !menu && scrolled > 0.005 ? `0 1px 0 ${LP.line}` : 'none' }}>
        <div className={`${wrap} h-16 flex items-center justify-between gap-4`}>
          <a href="/" className="lp-focus flex items-center gap-2.5 rounded-lg"><XorlaMark size={28} /><span className="text-[19px] font-bold" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.03em' }}>Xorla</span></a>
          <nav className="hidden lg:flex items-center gap-1 text-[14.5px] font-semibold">
            {navLinks.map(([h, l]) => <a key={h} href={h} className="lp-focus px-3.5 py-2 rounded-full transition-colors hover:bg-[var(--lp-bg2)]" style={{ color: LP.dim }}>{l}</a>)}
          </nav>
          <div className="flex items-center gap-2">
            {themeBtn}
            <a href="/login" className="lp-focus hidden sm:inline-flex px-4 py-2 rounded-full text-[14.5px] font-semibold" style={{ color: LP.ink }}>Log in</a>
            <a href={start} className="lp-focus lp-press hidden sm:inline-flex px-5 py-2.5 rounded-full text-[14.5px] font-bold" style={{ background: LP.btn, color: LP.btnInk }}>Start free</a>
            <button onClick={() => setMenu((m) => !m)} aria-label={menu ? 'Close menu' : 'Open menu'} aria-expanded={menu} className="lp-focus lg:hidden relative z-[60] w-11 h-11 rounded-full flex items-center justify-center transition-colors" style={{ background: menu ? LP.btn : LP.bg2, border: `1px solid ${menu ? 'transparent' : LP.line}` }}>
              <span aria-hidden className="relative block w-[18px] h-[12px]">
                <span className="absolute left-0 right-0 h-[2px] rounded-full transition-all duration-300" style={{ top: menu ? 5 : 0, transform: menu ? 'rotate(45deg)' : 'none', background: menu ? LP.btnInk : LP.ink }} />
                <span className="absolute left-0 h-[2px] rounded-full transition-all duration-300" style={{ top: 5, width: menu ? 0 : 12, opacity: menu ? 0 : 1, background: LP.ink }} />
                <span className="absolute left-0 right-0 h-[2px] rounded-full transition-all duration-300" style={{ top: menu ? 5 : 10, transform: menu ? 'rotate(-45deg)' : 'none', background: menu ? LP.btnInk : LP.ink }} />
              </span>
            </button>
          </div>
        </div>
      </header>

      {/* Phone menu: a full panel built for Xorla, not a plain list */}
      <div className={`lp-menu lg:hidden fixed inset-0 z-[55] ${menu ? 'lp-menu-open' : ''}`} aria-hidden={!menu} style={{ pointerEvents: menu ? 'auto' : 'none' }}>
        <div className="lp-menu-bg absolute inset-0" style={{ background: LP.bg }} onClick={() => setMenu(false)} />
        <div aria-hidden className="lp-menu-glow absolute -top-24 -right-24 w-72 h-72 rounded-full" style={{ background: 'radial-gradient(circle, rgba(31,217,196,0.28), transparent 65%)' }} />
        <div aria-hidden className="lp-menu-glow absolute bottom-24 -left-24 w-64 h-64 rounded-full" style={{ background: 'radial-gradient(circle, rgba(255,176,32,0.20), transparent 65%)' }} />
        <nav aria-label="Menu" className="relative h-full flex flex-col px-5 sm:px-8 pt-20 overflow-y-auto" style={{ paddingBottom: 'max(20px, env(safe-area-inset-bottom))' }}>
          <div className="lp-mi text-[11.5px] font-bold uppercase tracking-[0.18em] mb-2" style={{ color: LP.faint, '--i': 0 }}>Explore Xorla</div>
          {[[ '#try', 'Try it', 'Tap products, watch profit add up', MousePointerClick, LP.teal],
            ['#features', 'What it does', 'Sales, stock, bookings, receipts', Sparkles, LP.amber],
            ['#for-you', "Who it's for", 'Shops, salons, hotels and more', Users, LP.teal],
            ['#pricing', 'Pricing', 'Start free. No card needed', Tag, LP.amber],
            ['/ride', 'Ride with us', 'Riders: earn delivering nearby', Bike, LP.coral],
          ].map(([h, l, d, Ic, col], i) => (
            <a key={h} href={h} onClick={() => setMenu(false)} className="lp-mi lp-focus group flex items-center gap-4 py-3.5" style={{ '--i': i + 1, borderBottom: `1px solid ${LP.line}` }}>
              <span className="text-[11px] font-bold w-5 shrink-0" style={{ fontFamily: LP_DISPLAY, color: LP.faint }}>{String(i + 1).padStart(2, '0')}</span>
              <span className="flex-1 min-w-0">
                <span className="block text-[22px] leading-tight font-bold" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.035em' }}>{l}</span>
                <span className="block text-[13px] mt-0.5" style={{ color: LP.dim }}>{d}</span>
              </span>
              <span className="w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 transition-transform group-active:scale-90" style={{ background: `${col}22`, color: col }}><Ic size={18} /></span>
            </a>
          ))}
          <div className="lp-mi mt-6 rounded-[22px] p-4 flex items-center gap-3.5" style={{ '--i': 6, background: LP.deep, color: '#EAF6F2' }}>
            <span className="w-11 h-11 rounded-2xl flex items-center justify-center shrink-0" style={{ background: 'rgba(255,255,255,0.08)' }}><XorlaMark size={24} /></span>
            <span className="flex-1 min-w-0 text-[12.5px] leading-snug"><strong className="block text-[14px]">Free to start, works offline</strong><span style={{ opacity: 0.75 }}>No network? Keep selling. It sends when you're back.</span></span>
          </div>
          <div className="flex-1 min-h-6" />
          <div className="lp-mi grid grid-cols-2 gap-2.5" style={{ '--i': 7 }}>
            <a href="/login" className="lp-focus h-[52px] rounded-full flex items-center justify-center text-[15px] font-semibold" style={{ border: `1.5px solid ${LP.line}`, color: LP.ink }}>Log in</a>
            <a href={start} className="lp-focus lp-press h-[52px] rounded-full flex items-center justify-center gap-1.5 text-[15px] font-bold" style={{ background: LP.btn, color: LP.btnInk }}>Start free <ArrowRight size={16} /></a>
          </div>
        </nav>
      </div>

      <main>
        {/* Hero */}
        <section className="relative overflow-hidden -mt-16 pt-16">
          <div aria-hidden className="absolute inset-0" style={{ backgroundImage: `radial-gradient(${LP.dots} 1.2px, transparent 1.2px)`, backgroundSize: '22px 22px', WebkitMaskImage: 'radial-gradient(ellipse 70% 60% at 70% 30%, #000 30%, transparent 75%)', maskImage: 'radial-gradient(ellipse 70% 60% at 70% 30%, #000 30%, transparent 75%)' }} />
          <div aria-hidden className="lp-orb absolute -right-48 -top-40 w-[760px] h-[760px] rounded-full" style={{ background: `radial-gradient(circle at 45% 45%, ${LP.tint} 0%, ${LP.tint} 42%, transparent 64%)` }} />
          <div className={`relative ${wrap} grid lg:grid-cols-[1.05fr_0.95fr] gap-10 lg:gap-8 items-center pt-8 sm:pt-12 lg:pt-14 pb-14 lg:pb-20`}>
            <div className="lp-hero-in">
              <a href="/ride" className="lp-focus inline-flex items-center gap-2 rounded-full pl-1.5 pr-3.5 py-1.5 text-[13px] font-semibold" style={{ background: LP.card, border: `1px solid ${LP.line}`, color: LP.dim }}><span className="px-2 py-0.5 rounded-full text-[11.5px] font-bold" style={{ background: LP.amber, color: LP.inkFixed }}>New</span>Delivery riders can now join Xorla<ChevronRight size={14} /></a>
              <h1 className="mt-6" style={H('clamp(40px, 6.2vw, 80px)', { lineHeight: 1.02, letterSpacing: '-0.045em', fontWeight: 800 })}>
                <span className="sr-only">Run your business without wahala.</span>
                <span aria-hidden>Run your business without <LpRotate words={LP_WORDS} still={still} /></span>
              </h1>
              <p className="mt-6 text-[16.5px] sm:text-[19px] leading-relaxed max-w-[540px]" style={{ color: LP.dim }}>Sales, stock, bookings, staff and payments, all on your phone. Xorla does the counting, so you can face your customers.</p>
              <div>
                <div className="mt-8 flex flex-col sm:flex-row gap-3">
                  <a href={start} className={btn} style={{ background: LP.btn, color: LP.btnInk, boxShadow: '0 14px 30px -14px rgba(11,59,51,0.7)' }}>Start free</a>
                  <a href="#try" className={btn} style={{ color: LP.ink, boxShadow: `inset 0 0 0 1.5px ${LP.line}` }}>Try it here first</a>
                </div>
                <ul className="mt-7 flex flex-wrap gap-x-6 gap-y-2 text-[14px] font-medium" style={{ color: LP.dim }}>
                  {['Free plan for small businesses', '30 days of Pro, free', 'Works offline'].map((x) => <li key={x} className="flex items-center gap-2"><Check size={15} strokeWidth={2.8} style={{ color: LP.accent }} />{x}</li>)}
                </ul>
              </div>
            </div>
            <div className={`relative h-[540px] sm:h-[570px] ${still ? 'lp-still' : ''}`}>
              <div className="absolute right-0 sm:right-[4%] lg:right-[2%] top-[18px]"><div className="lp-float"><LandingPhone /></div></div>
              <div className="absolute left-0 sm:left-[6%] lg:left-[2%] top-[150px] -rotate-[5deg] origin-top z-10"><LandingReceipt still={still} /></div>
              <div className="lp-bubble absolute left-0 sm:left-[4%] lg:left-0 top-[34px] max-w-[230px] z-20 rounded-2xl rounded-tr-md px-3.5 py-2.5 text-[12.5px] leading-snug" style={{ background: LP.wa, color: LP.waInk, boxShadow: `0 16px 30px -18px ${LP.shadow}`, animationDelay: '2.9s' }}>
                <div className="font-bold">New order from Chidi</div>2 crates of Coke, deliver to Aba Road. <span style={{ opacity: 0.7 }}>Paid online</span>
              </div>
              <div className="lp-bubble absolute right-0 sm:right-2 bottom-[18px] z-20 flex items-center gap-2.5 rounded-2xl px-3.5 py-2.5" style={{ background: LP.card, boxShadow: `0 18px 36px -20px ${LP.shadow}`, border: `1px solid ${LP.line}`, animationDelay: '3.4s' }}>
                <span className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: LP.amber }}><Bell size={15} style={{ color: LP.inkFixed }} /></span>
                <span className="text-[12.5px] leading-tight"><span className="block font-bold">Room 204 booked</span><span style={{ color: LP.faint }}>Deposit of {fmt(35000)} paid</span></span>
              </div>
            </div>
          </div>
        </section>

        {/* Every kind of business, moving past */}
        <section className="py-7 lp-marquee-wrap overflow-hidden" style={{ background: LP.bg2, borderTop: `1px solid ${LP.line}`, borderBottom: `1px solid ${LP.line}` }} aria-label="Made for every kind of business">
          <div className="lp-marquee gap-3" aria-hidden>
            {[...LP_KINDS, ...LP_KINDS].map(([Ic, l], i) => <span key={i} className="shrink-0 inline-flex items-center gap-2.5 rounded-full pl-2 pr-5 py-2 mr-3 text-[15px] font-semibold whitespace-nowrap" style={{ background: LP.card, border: `1px solid ${LP.line}` }}><span className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: LP.tint }}><Ic size={15} style={{ color: LP.accent }} /></span>{l}</span>)}
          </div>
          <span className="sr-only">{LP_KINDS.map(([, l]) => l).join(', ')}</span>
        </section>

        {/* Try it */}
        <section id="try" className={`${wrap} pt-20 sm:pt-24 scroll-mt-20`}>
          {head('Record a sale. Right here, right now.', 'Tap a few products the way you would on a busy day. Watch your sales and your profit add up by themselves.')}
          <div className="mt-10" data-reveal style={{ '--d': '0.1s' }}><LandingDemo /></div>
        </section>

        {/* What it does */}
        <section id="features" className={`${wrap} pt-20 sm:pt-28 scroll-mt-20`}>
          {head('Everything a busy owner needs, nothing you don\'t', 'Start with recording sales. Add stock, staff, bookings and online payments when you\'re ready. It all works together.')}
          <div className="mt-10 grid gap-4 lg:grid-cols-6">
            {tile(LP.deep, (
              <div className="grid sm:grid-cols-2 gap-6 items-end">
                <div>{tt('Know your profit every evening', 'Every sale and expense adds up by itself, so you always know what you made today. On Pro, your weekly summary also comes to you on WhatsApp.', true)}
                  <div className="mt-5 text-[40px] font-bold" style={{ fontFamily: LP_DISPLAY, color: LP.teal, letterSpacing: '-0.04em' }}><LpCount value={210500} ms={1400} /></div>
                  <div className="text-[13px]" style={{ color: 'rgba(255,255,255,0.6)' }}>profit this week</div>
                  <div className="mt-5 flex items-end gap-2 h-20" aria-hidden>
                    {[['M', 46], ['T', 58], ['W', 40], ['T', 66], ['F', 74], ['S', 100], ['S', 62]].map(([d, h], i) => (
                      <div key={i} className="flex-1 flex flex-col items-center gap-1.5 h-full justify-end"><span className="w-full rounded-md lp-bar-r" style={{ height: `${h}%`, background: i === 5 ? LP.amber : 'rgba(31,217,196,0.45)', '--bd': `${0.25 + i * 0.07}s` }} /><span className="text-[11px] font-semibold" style={{ color: 'rgba(255,255,255,0.55)' }}>{d}</span></div>
                    ))}
                  </div>
                </div>
                <div className="rounded-2xl p-4" style={{ background: '#DCF8C6', color: LP.inkFixed }}>
                  <div className="text-[12px] font-bold" style={{ color: '#0E7A5F' }}>Your week on Xorla</div>
                  <div className="text-[14px] leading-relaxed mt-1">Good evening Amaka. This week you sold <strong>{fmt(612400)}</strong>, spent <strong>{fmt(401900)}</strong> and made <strong>{fmt(210500)}</strong> profit. Your best seller was Peak Milk. Well done!</div>
                </div>
              </div>
            ), 'lg:col-span-4')}
            {tile(LP.tint, (
              <>
                {tt('Never run out of stock', 'Stock goes down with every sale. You hear about it before the shelf is empty.')}
                <div className="mt-5 space-y-2">
                  {[['Indomie (carton)', 3, LP.coral], ['Peak Milk tin', 24, LP.accent], ['Kings Oil 5L', 11, LP.accent]].map(([n, q, c]) => (
                    <div key={n} className="rounded-xl px-3.5 py-2.5 text-[14px]" style={{ background: LP.card }}>
                      <div className="flex items-center justify-between"><span className="font-semibold">{n}</span><span className="font-bold" style={{ color: c }}>{q} left</span></div>
                      <div className="mt-2 h-1.5 rounded-full overflow-hidden" style={{ background: LP.bg2 }}><span className="block h-full rounded-full lp-line-grow" style={{ width: `${Math.min(100, q * 3.5)}%`, background: c }} /></div>
                    </div>
                  ))}
                </div>
              </>
            ), 'lg:col-span-2', 0.08)}
            {tile(LP.card, (
              <>
                {tt('Your own online shop', 'Share one link on WhatsApp and Instagram. Customers order, book or pay from it, and you see it on your phone at once.')}
                <div className="mt-5 rounded-2xl p-3 flex items-center gap-3" style={{ background: LP.bg2, border: `1px solid ${LP.line}` }}>
                  <span className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0" style={{ background: LP.forest }}><Store size={18} color="#fff" /></span>
                  <span className="min-w-0"><span className="block text-[14px] font-bold truncate">xorla.vercel.app/amakastores</span><span className="block text-[12.5px]" style={{ color: LP.faint }}>Open 8am to 9pm</span></span>
                </div>
              </>
            ), 'lg:col-span-2', 0, { border: `1px solid ${LP.line}` })}
            {tile(LP.card, (
              <>
                {tt('Get paid online', 'Customers pay by card, transfer or USSD. The money goes straight to your bank.')}
                <div className="mt-5 flex items-center gap-3">
                  <span className="flex-1 h-11 rounded-full flex items-center justify-center text-[14px] font-bold" style={{ background: LP.btn, color: LP.btnInk }}><Lock size={14} className="mr-1.5" />Pay {fmt(29000)}</span>
                  <span className="h-11 px-4 rounded-full flex items-center gap-1.5 text-[14px] font-bold" style={{ background: LP.tint, color: LP.accent }}><Check size={15} />Paid</span>
                </div>
                <p className="mt-3 text-[12.5px]" style={{ color: LP.faint }}>Secured by Paystack</p>
              </>
            ), 'lg:col-span-2', 0.08, { border: `1px solid ${LP.line}` })}
            {tile(LP.card, (
              <>
                {tt('Staff without stress', 'Each person gets their own login. They record sales; you see who did what, from anywhere.')}
                <div className="mt-5 flex items-center gap-3"><span className="flex -space-x-2">{['TO', 'AD', 'CH'].map((x, i) => <span key={x} className="w-10 h-10 rounded-full flex items-center justify-center text-[12px] font-bold" style={{ background: ['#E3F4EF', '#FFE7B0', '#FFD9CC'][i], color: LP.inkFixed, boxShadow: `0 0 0 2px ${LP_THEMES[theme].card}` }}>{x}</span>)}</span><span className="text-[13.5px] leading-snug" style={{ color: LP.dim }}>Tolu recorded 12 sales today</span></div>
              </>
            ), 'lg:col-span-2', 0.16, { border: `1px solid ${LP.line}` })}
            {tile(LP.amber, (
              <div className="grid sm:grid-cols-[1fr_1.1fr] gap-6 items-center">
                <div>{tt('Ask Oga anything about your business', 'Oga is your business advisor. It reads your real numbers and answers in English, Pidgin, Igbo, Yoruba or Hausa.', false, true)}</div>
                <div className="space-y-2">
                  <div className="ml-auto max-w-[260px] rounded-2xl rounded-br-md px-3.5 py-2.5 text-[14px]" style={{ background: LP.forest, color: '#fff' }}>Which product dey bring me the most money?</div>
                  <div className="max-w-[300px] rounded-2xl rounded-bl-md px-3.5 py-2.5 text-[14px] leading-relaxed" style={{ background: '#fff', color: LP.inkFixed }}>Na Mama Gold Rice. This month e bring {fmt(312000)}, but only 4 bags remain. Order more before weekend.</div>
                </div>
              </div>
            ), 'lg:col-span-4')}
            {tile(LP.bg2, (
              <>
                {tt('Register your business with CAC', 'Apply for your business name inside Xorla. An accredited agent files it, and your certificate lands in your vault.')}
                <div className="mt-5 rounded-xl p-4 text-center" style={{ background: 'linear-gradient(160deg, #FBF6EA, #F3EBD7)', boxShadow: 'inset 0 0 0 1.5px rgba(150,110,40,0.35)' }}>
                  <div className="text-[10px] font-semibold tracking-[0.2em]" style={{ color: '#8A6A2F' }}>CERTIFICATE OF REGISTRATION</div>
                  <div className="mt-1 text-[17px] font-bold" style={{ fontFamily: 'Georgia, serif', color: '#1F2A26' }}>Amaka Stores</div>
                </div>
              </>
            ), 'lg:col-span-2', 0.08)}
            {tile(LP.bg2, (
              <>
                {tt('Reminders that get you paid', 'Xorla reminds customers who owe you on WhatsApp, politely, so you don\'t have to chase them.')}
                <div className="mt-5 rounded-2xl rounded-tl-md px-3.5 py-2.5 text-[13.5px] leading-relaxed" style={{ background: LP.wa, color: LP.waInk }}>Hello Emeka, a friendly reminder from Amaka Stores: your invoice of {fmt(18200)} is due today. Thank you!</div>
              </>
            ), 'lg:col-span-3')}
            {tile(LP.bg2, (
              <>
                {tt('Your papers, safe in one place', 'Keep your CAC certificate, TIN and licences in the vault. Share them with a bank or supplier in one tap.')}
                <div className="mt-5 flex gap-2">{[['CAC certificate', LP.accent], ['TIN', LP.amber], ['NAFDAC', LP.coral]].map(([n, c]) => <span key={n} className="flex-1 rounded-xl px-2.5 py-3 text-[12px] font-bold text-center" style={{ background: LP.card, borderTop: `3px solid ${c}` }}><FileText size={16} className="mx-auto mb-1" style={{ color: c }} />{n}</span>)}</div>
              </>
            ), 'lg:col-span-3', 0.08)}
          </div>
        </section>

        {/* Built for your kind of business */}
        <section id="for-you" className={`${wrap} pt-20 sm:pt-28 scroll-mt-20`}>
          {head('It changes to fit your business', 'Tell Xorla what you do when you sign up. A shop, a salon and a hotel each get the tools they need, in the words they use.')}
          <div className="mt-9 inline-flex p-1.5 rounded-full" role="tablist" aria-label="Type of business" data-reveal style={{ background: LP.bg2, border: `1px solid ${LP.line}` }}>
            {Object.entries(LP_TYPES).map(([k, v]) => <button key={k} role="tab" aria-selected={tab === k} onClick={() => setTab(k)} className="lp-focus px-5 sm:px-7 py-2.5 rounded-full text-[15px] font-bold transition-colors duration-300" style={tab === k ? { background: LP.btn, color: LP.btnInk } : { color: LP.dim }}>{v.label}</button>)}
          </div>
          <div key={tab} className="mt-6 grid lg:grid-cols-[1.15fr_0.85fr] gap-4 items-stretch lp-new" role="tabpanel">
            <div className="rounded-[28px] p-7 sm:p-9" style={{ background: LP.tint }}>
              <h3 style={H('clamp(22px, 2.4vw, 30px)')}>{t.title}</h3>
              <ul className="mt-6 space-y-4">{t.points.map((x) => <li key={x} className="flex items-start gap-3 text-[16px] leading-relaxed"><span className="w-6 h-6 rounded-full flex items-center justify-center shrink-0 mt-0.5" style={{ background: LP.btn }}><Check size={13} strokeWidth={3} style={{ color: LP.btnInk }} /></span>{x}</li>)}</ul>
            </div>
            <div className="rounded-[28px] p-6 flex flex-col" style={{ background: '#0A1F1C', color: '#EAF6F2', border: `1px solid ${LP.line}` }}>
              <div className="flex items-center gap-2"><XorlaMark size={18} /><span className="text-[13px] font-semibold">{t.screen.head}</span></div>
              <div className="mt-4 rounded-2xl overflow-hidden flex-1" style={{ background: '#13322C' }}>{t.screen.rows.map(([a, b], i) => <div key={a} className="flex items-center justify-between px-4 py-3.5 text-[14.5px]" style={{ borderTop: i ? '1px solid rgba(255,255,255,0.06)' : 'none' }}><span className="font-semibold">{a}</span><span style={{ color: '#93B0AA' }}>{b}</span></div>)}</div>
              <div className="mt-3 rounded-xl px-4 py-3 text-[13.5px] font-bold" style={{ background: t.screen.tone === 'amber' ? 'rgba(255,176,32,0.14)' : 'rgba(31,217,196,0.14)', color: t.screen.tone === 'amber' ? '#FFB020' : '#1FD9C4' }}>{t.screen.note}</div>
            </div>
          </div>
        </section>

        {/* How it works (a real sequence) */}
        <section className={`${wrap} pt-20 sm:pt-28`}>
          {head('Set up before your next customer walks in')}
          <div className="relative mt-10" data-reveal>
            <div aria-hidden className="hidden md:block absolute left-[16%] right-[16%] top-[34px] h-[2px] lp-line-grow" style={{ background: `linear-gradient(90deg, ${LP.teal}, ${LP.amber}, ${LP.coral})` }} />
            <ol className="relative grid md:grid-cols-3 gap-4">
              {[['Sign up with your email', 'It takes about a minute. Tell Xorla your business name and what you sell or do.'], ['Add what you sell', 'Type it in, or take a photo of your price list and Xorla fills it in for you.'], ['Record your first sale', 'Then share your shop link with customers, and invite your staff when you\'re ready.']].map(([a, b], i) => (
                <li key={a} className="rounded-[28px] p-7 md:text-center" style={{ background: LP.card, border: `1px solid ${LP.line}` }}>
                  <span className="md:mx-auto w-[52px] h-[52px] -mt-0 rounded-full flex items-center justify-center text-[20px] font-bold" style={{ fontFamily: LP_DISPLAY, background: [LP.teal, LP.amber, LP.coral][i], color: LP.inkFixed }}>{i + 1}</span>
                  <span className="block mt-5 text-[18px] font-semibold" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.02em' }}>{a}</span>
                  <span className="block mt-2 text-[15px] leading-relaxed" style={{ color: LP.dim }}>{b}</span>
                </li>
              ))}
            </ol>
          </div>
        </section>

        {/* Works offline */}
        <section id="offline" className={`${wrap} pt-20 sm:pt-28 scroll-mt-20`}>
          <div className="relative overflow-hidden rounded-[32px] grid lg:grid-cols-[1.1fr_0.9fr] gap-10 items-center p-7 sm:p-12" data-reveal style={{ background: LP.tint, border: `1px solid ${LP.line}` }}>
            <div aria-hidden className="absolute -right-24 -top-24 w-80 h-80 rounded-full lp-orb" style={{ background: 'radial-gradient(circle, rgba(255,176,32,0.22), transparent 65%)' }} />
            <div className="relative">
              <span className="inline-flex items-center gap-2 rounded-full px-3.5 py-1.5 text-[12.5px] font-bold uppercase tracking-[0.12em]" style={{ background: LP.card, color: LP.accent, border: `1px solid ${LP.line}` }}><WifiOff size={14} /> Works offline</span>
              <h2 className="mt-5 text-[32px] sm:text-[46px] leading-[1.05] font-extrabold" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.045em' }}>No network?<br /><span style={{ color: LP.amber }}>Keep selling.</span></h2>
              <p className="mt-4 text-[16px] sm:text-[17.5px] leading-relaxed max-w-xl" style={{ color: LP.dim }}>Data finishes. Network drops. Light goes and the router goes with it. Xorla keeps recording your sales and expenses on your phone, then sends them by itself the moment you're back online.</p>
              <ul className="mt-6 grid sm:grid-cols-3 gap-3">
                {[[Smartphone, 'Opens with no data', 'Your records are right there'], [CloudUpload, 'Sends by itself', 'When the network returns'], [ShieldCheck, 'Never counted twice', 'Even on a shaky network']].map(([Ic, a, b], i) => (
                  <li key={a} className="rounded-2xl p-3.5 sm:p-4 flex sm:block items-center gap-3" data-reveal style={{ '--d': `${0.1 + i * 0.08}s`, background: LP.card, border: `1px solid ${LP.line}` }}>
                    <Ic size={19} className="shrink-0" style={{ color: [LP.accent, LP.amber, LP.coral][i] }} />
                    <span className="min-w-0"><span className="block sm:mt-2.5 text-[14.5px] font-bold" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.02em' }}>{a}</span>
                    <span className="block text-[13px] mt-0.5" style={{ color: LP.dim }}>{b}</span></span>
                  </li>
                ))}
              </ul>
            </div>
            {/* A little phone that loses signal, keeps selling, then catches up */}
            <div className="relative flex justify-center" aria-hidden>
              <div className="lp-float w-[260px] rounded-[38px] p-3" style={{ background: '#0B2B26', boxShadow: `0 40px 80px -40px ${LP.shadow}` }}>
                <div className="rounded-[28px] overflow-hidden" style={{ background: '#0F2925', color: '#EAF6F2' }}>
                  <div className="flex items-center justify-between px-4 pt-3 text-[11px] font-semibold" style={{ color: '#A6C0BA' }}>
                    <span>9:41</span>
                    <span className="flex items-end gap-[2px] h-3">{[0, 1, 2, 3].map((b) => <span key={b} className="lp-off-bar w-[3px] rounded-sm" style={{ height: 4 + b * 2.5, background: '#EAF6F2', '--b': b }} />)}</span>
                  </div>
                  <div className="px-4 pt-4 pb-5">
                    <div className="text-[10.5px] font-bold uppercase tracking-[0.12em]" style={{ color: '#6E8B85' }}>Today</div>
                    <div className="text-[26px] font-bold mt-0.5" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.04em' }}>₦48,500</div>
                    <div className="mt-3 space-y-2">
                      {[['Indomie ×2', '₦1,200'], ['Peak Milk', '₦650'], ['Bread', '₦1,500']].map(([n, a], i) => (
                        <div key={n} className="lp-off-row flex items-center justify-between rounded-xl px-3 py-2 text-[12.5px]" style={{ background: 'rgba(255,255,255,0.05)', '--r': i }}>
                          <span>{n}</span>
                          <span className="flex items-center gap-1.5 font-semibold">{a}<span className="lp-off-wait inline-flex"><CloudUpload size={12} style={{ color: '#FFB020' }} /></span></span>
                        </div>
                      ))}
                    </div>
                    <div className="relative mt-4 h-9">
                      <div className="lp-off-pill-a absolute inset-0 rounded-full flex items-center justify-center gap-1.5 text-[11.5px] font-bold" style={{ background: 'rgba(255,176,32,0.16)', color: '#FFB020' }}><WifiOff size={13} /> Offline · 3 waiting</div>
                      <div className="lp-off-pill-b absolute inset-0 rounded-full flex items-center justify-center gap-1.5 text-[11.5px] font-bold" style={{ background: 'rgba(31,217,196,0.16)', color: '#1FD9C4' }}><Check size={13} /> All caught up</div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Trust */}
        <section className="mt-20 sm:mt-28 relative overflow-hidden" style={{ background: LP.forest }}>
          <div aria-hidden className="absolute -left-40 -bottom-40 w-[520px] h-[520px] rounded-full" style={{ background: 'radial-gradient(circle, rgba(31,217,196,0.16), transparent 65%)' }} />
          <div className={`relative ${wrap} py-20 grid lg:grid-cols-[0.85fr_1.15fr] gap-12`}>
            {head('Your money and your records stay yours', 'Here is how Xorla keeps your business safe, every day.', true)}
            <ul className="grid sm:grid-cols-2 gap-x-8 gap-y-7">
              {[[ShieldCheck, 'Staff see only what you allow', 'You approve every staff member, and remove them in one tap.'], [Lock, 'Lock it with a PIN', 'Nobody opens your Xorla on your phone without your PIN.'], [CreditCard, 'Payments by Paystack', 'Card, transfer and USSD. Xorla never sees card details.'], [FileText, 'Nothing is ever deleted', 'Stop paying and you move to Free with every record still there.'], [Bell, 'No surprise charges', 'We remind you 3 days before your plan renews.'], [Smartphone, 'Lose your phone, not your records', 'Everything is kept online. Log in on another phone.']].map(([Ic, a, b], i) => (
                <li key={a} className="flex gap-3.5" data-reveal style={{ '--d': `${(i % 2) * 0.08 + Math.floor(i / 2) * 0.06}s` }}>
                  <span className="w-11 h-11 rounded-2xl flex items-center justify-center shrink-0" style={{ background: 'rgba(31,217,196,0.14)' }}><Ic size={19} style={{ color: LP.teal }} /></span>
                  <span><span className="block text-[16px] font-bold text-white">{a}</span><span className="block mt-1 text-[14.5px] leading-relaxed" style={{ color: 'rgba(255,255,255,0.72)' }}>{b}</span></span>
                </li>
              ))}
            </ul>
          </div>
        </section>

        {/* Pricing */}
        <section id="pricing" className={`${wrap} pt-20 sm:pt-28 scroll-mt-20`}>
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            {head('Start free. Grow when you\'re ready.', 'Every paid plan starts with 30 days free. Pay by card, transfer or USSD.')}
            <div className="inline-flex p-1.5 rounded-full self-start md:self-auto" role="tablist" aria-label="Billing" data-reveal style={{ background: LP.bg2, border: `1px solid ${LP.line}` }}>
              {[[false, 'Monthly'], [true, 'Yearly']].map(([v, l]) => <button key={l} role="tab" aria-selected={yearly === v} onClick={() => setYearly(v)} className="lp-focus px-5 py-2.5 rounded-full text-[14.5px] font-bold transition-colors duration-300 flex items-center gap-2" style={yearly === v ? { background: LP.btn, color: LP.btnInk } : { color: LP.dim }}>{l}{v && <span className="px-2 py-0.5 rounded-full text-[11px] font-bold" style={{ background: LP.amber, color: LP.inkFixed }}>2 months free</span>}</button>)}
            </div>
          </div>
          {early && (
            <div className="mt-8 rounded-2xl px-5 py-4 flex flex-col sm:flex-row sm:items-center gap-3 sm:gap-5" style={{ background: LP.tint, border: `1px solid ${LP.line}` }}>
              <span className="self-start px-3 py-1 rounded-full text-[12.5px] font-bold shrink-0" style={{ background: LP.amber, color: LP.inkFixed }}>Early-supporter offer</span>
              <span className="text-[14.5px] leading-relaxed" style={{ color: LP.ink }}>The first 100 businesses to subscribe pay about a third less for their first 12 months. <strong>{spots} of 100 places left.</strong></span>
            </div>
          )}
          <div className="mt-6 grid md:grid-cols-3 gap-4 items-stretch">
            {[
              ['Free', null, 'For one person getting started', null, ['Up to 20 products or services', 'Sales, expenses, invoices and receipts', 'Your own online shop link', '10 room or rental bookings and 10 questions to Oga a month'], false],
              ['Pro', 'pro', 'For a growing business with staff', 'Everything in Free, plus', ['Up to 3 staff, each with their own login. They see only what you allow', 'Unlimited products, services and room bookings', 'Automatic WhatsApp: payment reminders, booking confirmations and business summaries', 'Oga, your business adviser: 150 questions a month in English, Pidgin, Igbo, Yoruba or Hausa', 'Your brand only: no "Powered by Xorla" on your shop and receipts', 'Unlimited papers in your document vault'], true],
              ['Business', 'business', 'For several branches, shops or warehouses', 'Everything in Pro, plus', ['3 locations included, and add more any time', 'Up to 10 staff, each placed at their branch', 'Move stock between branches, and see what each one sells', 'Every branch together on one screen, or one at a time', '500 questions to Oga and 500 WhatsApp messages a month'], false],
            ].map(([n, plan, who, plus, pts, star], i) => (
              <div key={n} data-reveal className="lp-tile rounded-[28px] p-7 flex flex-col" style={{ '--d': `${i * 0.08}s`, ...(star ? { background: LP.forest, color: '#fff', boxShadow: '0 30px 60px -30px rgba(11,59,51,0.7)' } : { background: LP.card, border: `1px solid ${LP.line}` }) }}>
                <div className="flex items-center justify-between gap-2"><span className="text-[18px] font-semibold" style={{ fontFamily: LP_DISPLAY }}>{n}</span>{star && <span className="px-3 py-1 rounded-full text-[12.5px] font-bold" style={{ background: LP.amber, color: LP.inkFixed }}>Most chosen</span>}</div>
                <div className="mt-1 text-[14px]" style={{ color: star ? 'rgba(255,255,255,0.72)' : LP.dim }}>{who}</div>
                <div className="mt-5 flex items-baseline gap-1.5 flex-wrap"><span className="text-[34px] font-bold" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.04em' }}>{plan ? <LpCount value={price(plan)} ms={500} /> : '₦0'}</span><span className="text-[14px]" style={{ color: star ? 'rgba(255,255,255,0.7)' : LP.faint }}>{plan ? (yearly ? 'a year' : 'a month') : 'forever'}</span></div>
                {plan ? (
                  <div className="mt-1 text-[13px] leading-snug" style={{ color: star ? 'rgba(255,255,255,0.72)' : LP.dim }}>
                    {early && <><span className="line-through">{fmt(regular(plan))}</span> after the offer · </>}About {fmt(perDay(plan))} a day
                  </div>
                ) : <div className="mt-1 text-[13px]" style={{ color: LP.dim }}>No card, no time limit</div>}
                {plus && <div className="mt-5 text-[13px] font-bold uppercase tracking-wide" style={{ color: star ? LP.teal : LP.accent }}>{plus}</div>}
                <ul className={`${plus ? 'mt-3' : 'mt-5'} space-y-2.5 flex-1`}>{pts.map((x) => <li key={x} className="flex items-start gap-2.5 text-[14.5px] leading-snug"><Check size={16} strokeWidth={2.8} className="shrink-0 mt-0.5" style={{ color: star ? LP.teal : LP.accent }} />{x}</li>)}</ul>
                <a href={start} className={`${btn} mt-7 w-full`} style={star ? { background: LP.amber, color: LP.inkFixed } : { background: LP.bg2, color: LP.ink }}>{plan ? 'Start 30 days free' : 'Start free'}</a>
                {plan && <div className="mt-2 text-[12.5px] text-center" style={{ color: star ? 'rgba(255,255,255,0.65)' : LP.faint }}>No card needed. Stop any time.</div>}
              </div>
            ))}
          </div>
          <div data-reveal className="mt-4 rounded-[24px] p-6" style={{ background: LP.card, border: `1px solid ${LP.line}` }}>
            <div className="text-[15px] font-bold">On every plan, Free included</div>
            <ul className="mt-3 grid sm:grid-cols-2 lg:grid-cols-3 gap-x-6 gap-y-2.5">
              {['Customers pay you online by card, transfer or USSD', 'Appointments, bookings and deposits', 'Deliveries with your riders or Xorla riders', 'Discount codes and shop posters', 'Works offline, and syncs when you are back', 'Reports on your profit and best sellers'].map((x) => <li key={x} className="flex items-start gap-2.5 text-[14px] leading-snug" style={{ color: LP.dim }}><Check size={15} strokeWidth={2.8} className="shrink-0 mt-0.5" style={{ color: LP.accent }} />{x}</li>)}
            </ul>
          </div>
          <p className="mt-5 text-[14.5px]" style={{ color: LP.dim }}><a href="/pricing" className="lp-focus font-bold underline underline-offset-4" style={{ color: LP.ink }}>See full pricing and early-supporter prices</a></p>
        </section>

        {/* Questions */}
        <section className={`${wrap} pt-20 sm:pt-28 grid lg:grid-cols-[0.8fr_1.2fr] gap-10`}>
          {head('Questions people ask', 'Something else on your mind? Sign up and tap Help inside Xorla. A real person answers.')}
          <div data-reveal style={{ borderTop: `1px solid ${LP.line}` }}>
            {LP_FAQ.map(([q, a], i) => {
              const open = faq === i;
              return (
                <div key={q} style={{ borderBottom: `1px solid ${LP.line}` }}>
                  <button onClick={() => setFaq(open ? -1 : i)} aria-expanded={open} className="lp-focus w-full flex items-center justify-between gap-4 py-5 text-left text-[17px] font-bold">
                    {q}<span className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 transition-transform duration-300" style={{ background: open ? LP.btn : LP.bg2, color: open ? LP.btnInk : LP.ink, transform: open ? 'rotate(180deg)' : 'none' }}>{open ? <Minus size={15} /> : <Plus size={15} />}</span>
                  </button>
                  <div className={`lp-faq ${open ? 'open' : ''}`}><div className="overflow-hidden"><p className="pb-5 -mt-1 text-[15.5px] leading-relaxed max-w-2xl" style={{ color: LP.dim }}>{a}</p></div></div>
                </div>
              );
            })}
          </div>
        </section>

        {/* Last call */}
        <section className={`${wrap} pt-20 sm:pt-28 pb-20`}>
          <div data-reveal className="relative overflow-hidden rounded-[36px] px-7 py-14 sm:px-14 sm:py-16 grid lg:grid-cols-[1.25fr_0.75fr] gap-10 items-center" style={{ background: LP.tint }}>
            <div aria-hidden className="absolute -right-20 -top-24 w-80 h-80 rounded-full" style={{ background: 'radial-gradient(circle, rgba(255,176,32,0.25), transparent 65%)' }} />
            <div className="relative">
              <h2 style={H('clamp(30px, 4.4vw, 56px)')}>Your next sale can be your first one on Xorla.</h2>
              <p className="mt-4 text-[17px] leading-relaxed max-w-lg" style={{ color: LP.dim }}>Free to start. Set up in minutes. Works on the phone you already have.</p>
              <div className="mt-8 flex flex-col sm:flex-row gap-3">
                <a href={start} className={btn} style={{ background: LP.btn, color: LP.btnInk }}>Start free</a>
                <a href="/login" className={btn} style={{ background: LP.card, color: LP.ink }}>I already have an account</a>
              </div>
            </div>
            <div className="hidden lg:flex justify-center relative"><div className="rotate-[4deg]"><LandingReceipt still /></div></div>
          </div>
        </section>
      </main>

      <footer style={{ borderTop: `1px solid ${LP.line}` }}>
        <div className={`${wrap} py-10 flex flex-col md:flex-row md:items-center justify-between gap-6`}>
          <div>
            <div className="flex items-center gap-2.5"><XorlaMark size={24} /><span className="text-[17px] font-bold" style={{ fontFamily: LP_DISPLAY, letterSpacing: '-0.03em' }}>Xorla</span></div>
            <div className="mt-2 text-[13.5px]" style={{ color: LP.faint }}>Made for businesses across Nigeria. © {new Date().getFullYear()} Xorla</div>
          </div>
          <nav className="flex flex-wrap items-center gap-x-6 gap-y-2 text-[14px] font-semibold" style={{ color: LP.dim }}>
            {[['/pricing', 'Pricing'], ['/ride', 'Ride with Xorla'], ['/terms', 'Terms'], ['/privacy', 'Privacy'], ['/login', 'Log in']].map(([h, l]) => <a key={h} href={h} className="lp-focus rounded">{l}</a>)}
            {themeBtn}
          </nav>
        </div>
      </footer>

      {/* Phones: Start free stays in reach once you scroll past the top */}
      <div className={`sm:hidden fixed left-0 right-0 bottom-0 z-40 px-4 pt-3 transition-transform duration-300 ${pastHero ? 'translate-y-0' : 'translate-y-full'}`} style={{ background: LP.nav, backdropFilter: 'blur(14px)', WebkitBackdropFilter: 'blur(14px)', borderTop: `1px solid ${LP.line}`, paddingBottom: 'calc(12px + env(safe-area-inset-bottom))' }}>
        <div className="flex gap-2">
          <a href="/login" className="lp-focus h-12 px-5 rounded-full text-[15px] font-bold flex items-center justify-center" style={{ color: LP.ink, boxShadow: `inset 0 0 0 1.5px ${LP.line}` }}>Log in</a>
          <a href={start} className="lp-focus flex-1 h-12 rounded-full text-[15.5px] font-bold flex items-center justify-center" style={{ background: LP.btn, color: LP.btnInk }}>Start free</a>
        </div>
      </div>
    </div>
  );
}

export default function Root() {
  const path = typeof window !== 'undefined' ? window.location.pathname : '';
  const storeMatch = path.match(/^\/store\/([A-Za-z0-9]+)/);
  const clean = path.replace(/\/+$/, '');
  const offerMatch = path.match(/^\/appt\/([a-f0-9]{20,64})/);
  // A store opened by its name: /amakastores, or amakastores.<STORE_ROOT_DOMAIN>
  const slugMatch = path.match(/^\/([A-Za-z0-9-]{3,30})\/?$/);
  const host = typeof window !== 'undefined' ? window.location.hostname : '';
  const storeSub = STORE_ROOT_DOMAIN && host.endsWith(`.${STORE_ROOT_DOMAIN}`) && clean === '' ? host.slice(0, -STORE_ROOT_DOMAIN.length - 1).toLowerCase().replace(/^(www|app)$/, '') : '';
  const guestMatch = path.match(/^\/booking\/([a-f0-9]{20,64})/);
  const orderMatch = path.match(/^\/order\/([a-f0-9]{20,64})/);
  const docsMatch = path.match(/^\/docs\/([a-f0-9]{32})/);
  const agentMatch = path.match(/^\/agent\/([a-f0-9]{64})/);
  // New visitors to the main address see the home page; anyone logged in (or using the installed app) goes straight in
  const showLanding = clean === '' && typeof window !== 'undefined' && !window.location.search && (() => {
    try { if (localStorage.getItem(SESSION_KEY)) return false; } catch (e) { return false; }
    try { if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true) return false; } catch (e) {}
    return true;
  })();
  const page = /^\/(ride|riders?)$/.test(clean) ? <RiderApp /> : agentMatch ? <CacAgentPage token={agentMatch[1]} /> : docsMatch ? <VaultShared token={docsMatch[1]} /> : offerMatch ? <AppointmentOffer token={offerMatch[1]} /> : guestMatch ? <GuestBooking token={guestMatch[1]} /> : orderMatch ? <CustomerOrder token={orderMatch[1]} /> : storeMatch ? <Storefront businessCode={storeMatch[1]} />
    : clean === '/pricing' ? <PricingPage />
    : clean === '/privacy' ? <LegalPage kind="privacy" />
    : clean === '/terms' ? <LegalPage kind="terms" />
    : clean === '/admin' ? <AdminDashboard />
    : clean === '/login' ? <XorlaApp />
    : storeSub ? <StoreBySlug slug={storeSub} />
    : slugMatch && STORE_SLUG_RE.test(slugMatch[1].toLowerCase()) ? <StoreBySlug slug={slugMatch[1].toLowerCase()} />
    : showLanding ? <LandingPage />
    : <XorlaApp />;
  return <>{page}<BrandDialogHost /></>;
}
